/* AIVIC_FUNCTION_BUNDLE_START owner=generateMenuWithFamilyValidation exports=generateMenuWithFamilyValidation */
const __aivicBundle_3_generateMenuWithFamilyValidation = (() => {
  function generateMenuWithFamilyValidation(request: {
    userId: string;
    familyMembers: Array<{
      memberId: string;
      age: number;
      allergies: string[];
      dietaryRestrictions: string[];
    }>;
    nutritionRequirements: {
      calories: number;
      protein: number;
      carbohydrates: number;
      fat: number;
    };
    dietaryRestrictions: string[];
    allergies: string[];
    cookingTimeLimit: number;
    budgetLimit: number;
  }): {
    menus: Array<{
      menuId: string;
      dishes: string[];
      totalCost: number;
      totalCookingTime: number;
      nutritionMatch: number;
    }>;
    validationStatus: string;
    familyValidated: boolean;
  } {
    if (!request.userId || String(request.userId).trim() === "") {
      throw new Error("userId is required");
    }
  
    if (!request.familyMembers || request.familyMembers.length === 0) {
      throw new Error("家族情報が登録されていません");
    }
  
    const aggregatedAllergies = new Set<string>();
    const aggregatedRestrictions = new Set<string>();
  
    for (const member of request.familyMembers) {
      if (member.allergies) {
        member.allergies.forEach((allergy) => aggregatedAllergies.add(allergy));
      }
      if (member.dietaryRestrictions) {
        member.dietaryRestrictions.forEach((restriction) =>
          aggregatedRestrictions.add(restriction)
        );
      }
    }
  
    const allAllergies = Array.from(
      new Set([...request.allergies, ...aggregatedAllergies])
    );
    const allRestrictions = Array.from(
      new Set([...request.dietaryRestrictions, ...aggregatedRestrictions])
    );
  
    const generatedMenus: Array<{
      menuId: string;
      dishes: string[];
      totalCost: number;
      totalCookingTime: number;
      nutritionMatch: number;
    }> = [];
  
    const menuCandidates = generateMenuCandidatesInternal(
      request.nutritionRequirements,
      request.cookingTimeLimit,
      request.budgetLimit,
      allAllergies,
      allRestrictions
    );
  
    for (let i = 0; i < menuCandidates.length; i++) {
      const candidate = menuCandidates[i];
      const nutritionMatch = calculateNutritionMatchInternal(
        candidate,
        request.nutritionRequirements
      );
  
      generatedMenus.push({
        menuId: `menu_${request.userId}_${randomUUID()}`,
        dishes: candidate.dishes,
        totalCost: candidate.totalCost,
        totalCookingTime: candidate.totalCookingTime,
        nutritionMatch,
      });
    }
  
    return {
      menus: generatedMenus,
      validationStatus: "success",
      familyValidated: true,
    };
  }
  
  function generateMenuCandidatesInternal(
    nutritionRequirements: {
      calories: number;
      protein: number;
      carbohydrates: number;
      fat: number;
    },
    cookingTimeLimit: number,
    budgetLimit: number,
    allergies: string[],
    restrictions: string[]
  ): Array<{
    dishes: string[];
    totalCost: number;
    totalCookingTime: number;
  }> {
    const candidates: Array<{
      dishes: string[];
      totalCost: number;
      totalCookingTime: number;
    }> = [];
  
    const dishDatabase = [
      {
        name: "Grilled Chicken",
        cost: 800,
        cookingTime: 30,
        calories: 400,
        protein: 45,
        carbs: 0,
        fat: 20,
        allergens: [],
        restrictions: [],
      },
      {
        name: "Rice Bowl",
        cost: 300,
        cookingTime: 15,
        calories: 400,
        protein: 8,
        carbs: 80,
        fat: 2,
        allergens: [],
        restrictions: [],
      },
      {
        name: "Vegetable Stir Fry",
        cost: 500,
        cookingTime: 20,
        calories: 250,
        protein: 10,
        carbs: 40,
        fat: 8,
        allergens: [],
        restrictions: [],
      },
      {
        name: "Salmon Fillet",
        cost: 1200,
        cookingTime: 25,
        calories: 350,
        protein: 40,
        carbs: 0,
        fat: 20,
        allergens: ["fish"],
        restrictions: [],
      },
      {
        name: "Pasta Carbonara",
        cost: 600,
        cookingTime: 20,
        calories: 550,
        protein: 20,
        carbs: 60,
        fat: 25,
        allergens: ["gluten", "eggs"],
        restrictions: [],
      },
    ];
  
    const validDishes = dishDatabase.filter((dish) => {
      const hasAllergen = dish.allergens.some((allergen) =>
        allergies.includes(allergen)
      );
      const hasRestriction = dish.restrictions.some((restriction) =>
        restrictions.includes(restriction)
      );
      return !hasAllergen && !hasRestriction;
    });
  
    if (validDishes.length === 0) {
      return candidates;
    }
  
    for (let i = 0; i < Math.min(3, validDishes.length); i++) {
      const selectedDishes = [validDishes[i]];
      let totalCost = validDishes[i].cost;
      let totalCookingTime = validDishes[i].cookingTime;
  
      for (let j = i + 1; j < validDishes.length; j++) {
        const nextDish = validDishes[j];
        const newCost = totalCost + nextDish.cost;
        const newCookingTime = totalCookingTime + nextDish.cookingTime;
  
        if (newCost <= budgetLimit && newCookingTime <= cookingTimeLimit) {
          selectedDishes.push(nextDish);
          totalCost = newCost;
          totalCookingTime = newCookingTime;
        }
  
        if (selectedDishes.length >= 3) break;
      }
  
      if (totalCost <= budgetLimit && totalCookingTime <= cookingTimeLimit) {
        candidates.push({
          dishes: selectedDishes.map((d) => d.name),
          totalCost,
          totalCookingTime,
        });
      }
    }
  
    return candidates;
  }
  
  function calculateNutritionMatchInternal(
    candidate: {
      dishes: string[];
      totalCost: number;
      totalCookingTime: number;
    },
    nutritionRequirements: {
      calories: number;
      protein: number;
      carbohydrates: number;
      fat: number;
    }
  ): number {
    const dishDatabase = [
      {
        name: "Grilled Chicken",
        calories: 400,
        protein: 45,
        carbs: 0,
        fat: 20,
      },
      { name: "Rice Bowl", calories: 400, protein: 8, carbs: 80, fat: 2 },
      {
        name: "Vegetable Stir Fry",
        calories: 250,
        protein: 10,
        carbs: 40,
        fat: 8,
      },
      { name: "Salmon Fillet", calories: 350, protein: 40, carbs: 0, fat: 20 },
      {
        name: "Pasta Carbonara",
        calories: 550,
        protein: 20,
        carbs: 60,
        fat: 25,
      },
    ];
  
    let totalCalories = 0;
    let totalProtein = 0;
    let totalCarbs = 0;
    let totalFat = 0;
  
    for (const dishName of candidate.dishes) {
      const dish = dishDatabase.find((d) => d.name === dishName);
      if (dish) {
        totalCalories += dish.calories;
        totalProtein += dish.protein;
        totalCarbs += dish.carbs;
        totalFat += dish.fat;
      }
    }
  
    const calorieMatch = Math.min(
      totalCalories / nutritionRequirements.calories,
      1
    );
    const proteinMatch = Math.min(
      totalProtein / nutritionRequirements.protein,
      1
    );
    const carbsMatch = Math.min(
      totalCarbs / nutritionRequirements.carbohydrates,
      1
    );
    const fatMatch = Math.min(totalFat / nutritionRequirements.fat, 1);
  
    const averageMatch = (calorieMatch + proteinMatch + carbsMatch + fatMatch) / 4;
  
    return Math.round(averageMatch * 100);
  }
  return { generateMenuWithFamilyValidation };
})();
