const __aivicBundle_5_detectDietaryRestrictionChange = (() => {
  function detectDietaryRestrictionChange(params: {
    existingRestrictions: Array<{ id: string; name: string; type: string; createdAt: string }>;
    newRestriction: { name: string; type: string; timestamp: string };
    detectionTimestamp: string;
  }): DietaryRestrictionChange {
    const { existingRestrictions, newRestriction, detectionTimestamp } = params;
  
    const existingCount = existingRestrictions.length;
    const newCount = existingCount + 1;
  
    const existingNames = existingRestrictions.map((r) => r.name.toLowerCase());
    const newRestrictionNameLower = newRestriction.name.toLowerCase();
  
    let changeType: 'ADD' | 'UPDATE' | 'DELETE';
    let detected = false;
  
    if (existingNames.includes(newRestrictionNameLower)) {
      changeType = 'UPDATE';
      detected = true;
    } else {
      changeType = 'ADD';
      detected = true;
    }
  
    return {
      changeType,
      changeContent: newRestriction.name,
      existingCount,
      newCount,
      timestamp: detectionTimestamp,
      detected,
    };
  }
  return { detectDietaryRestrictionChange };
})();
