const __aivicBundle_7_detectConstraintChange = (() => {
  function detectConstraintChange(
    constraintCondition: {
      userId: string;
      familyId: string;
      allergyItems: string[];
      dietaryRestrictions: string[];
      cookingTimeLimit: number;
      budgetLimit: number;
      lastUpdateDate: Date;
      createdAt: Date;
    },
    currentDateTime: Date
  ): ConstraintDetectionResult {
    if (!String(constraintCondition.userId).trim()) {
      throw new Error("userId is required");
    }
    if (!String(constraintCondition.familyId).trim()) {
      throw new Error("familyId is required");
    }
    if (constraintCondition.cookingTimeLimit === undefined || constraintCondition.cookingTimeLimit === null) {
      throw new Error("cookingTimeLimit is required");
    }
    if (constraintCondition.budgetLimit === undefined || constraintCondition.budgetLimit === null) {
      throw new Error("budgetLimit is required");
    }
    if (!constraintCondition.createdAt) {
      throw new Error("createdAt is required");
    }
  
    const elapsedMs = currentDateTime.getTime() - constraintCondition.lastUpdateDate.getTime();
    const elapsedDays = Math.floor(elapsedMs / (1000 * 60 * 60 * 24));
  
    const isDetected = elapsedDays >= 7;
  
    let priorityScore = 0;
    let priorityRank: 'high' | 'medium' | 'low' = 'low';
  
    if (isDetected) {
      const constraintComplexity =
        constraintCondition.allergyItems.length * 10 +
        constraintCondition.dietaryRestrictions.length * 8;
  
      const daysOverThreshold = Math.min(elapsedDays - 7, 30);
      const recencyFactor = (daysOverThreshold / 30) * 40;
  
      const budgetFactor = constraintCondition.budgetLimit > 0 ? (constraintCondition.budgetLimit / 5000) * 10 : 0;
      const cookingTimeFactor = constraintCondition.cookingTimeLimit > 0 ? (constraintCondition.cookingTimeLimit / 60) * 5 : 0;
  
      priorityScore = Math.min(100, constraintComplexity + recencyFactor + budgetFactor + cookingTimeFactor);
  
      if (priorityScore >= 70) {
        priorityRank = 'high';
      } else if (priorityScore >= 40) {
        priorityRank = 'medium';
      } else {
        priorityRank = 'low';
      }
    }
  
    const needsImmediateReflection = isDetected && priorityRank === 'high';
  
    return {
      isDetected,
      priorityScore,
      priorityRank,
      detectionTimestamp: currentDateTime,
      elapsedDays,
      lastUpdateDate: constraintCondition.lastUpdateDate,
      needsImmediateReflection
    };
  }
  return { detectConstraintChange };
})();
export const detectConstraintChange = __aivicBundle_7_detectConstraintChange.detectConstraintChange;
/* AIVIC_FUNCTION_BUNDLE_END owner=detectConstraintChange */

/* AIVIC_FUNCTION_BUNDLE_START owner=detectConstraintChanges exports=detectConstraintChanges */
const __aivicBundle_8_detectConstraintChanges = (() => {
  function detectConstraintChanges(
    constraintData: {
      userId: string;
      familyMemberId: string;
      lastUpdatedAt: Date;
      constraints: Array<{ type: string; value: string; active: boolean }>;
    },
    nowTimestamp: number
  ): {
    isChangeDetected: boolean;
    priorityAssigned: boolean;
    detectionEventLogged: boolean;
    detectionReason: string;
  } {
    // Validate required input: constraints
    if (
      constraintData.constraints === undefined ||
      constraintData.constraints === null ||
      !Array.isArray(constraintData.constraints)
    ) {
      throw new Error('constraints is required');
    }
  
    const lastUpdatedMs = constraintData.lastUpdatedAt.getTime();
    const elapsedMs = nowTimestamp - lastUpdatedMs;
  
    // 7日間をミリ秒に変換
    const sevenDaysMs = 7 * 24 * 60 * 60 * 1000;
  
    // 7日以上経過していない場合は変更検出を発火しない
    if (elapsedMs < sevenDaysMs) {
      return {
        isChangeDetected: false,
        priorityAssigned: false,
        detectionEventLogged: false,
        detectionReason: '',
      };
    }
  
    // 7日以上経過している場合は変更検出を実行
    // constraints の内容を確認して検出理由に含める
    const activeConstraints = constraintData.constraints.filter(
      (c) => c.active
    );
    const constraintSummary =
      activeConstraints.length > 0
        ? activeConstraints.map((c) => `${c.type}:${c.value}`).join(', ')
        : 'no active constraints';
  
    return {
      isChangeDetected: true,
      priorityAssigned: true,
      detectionEventLogged: true,
      detectionReason: `Constraint change detected for user ${constraintData.userId}, family member ${constraintData.familyMemberId}. Last updated ${Math.floor(elapsedMs / (24 * 60 * 60 * 1000))} days ago. Active constraints: ${constraintSummary}.`,
    };
  }
  return { detectConstraintChanges };
})();
export const detectConstraintChanges = __aivicBundle_8_detectConstraintChanges.detectConstraintChanges;
/* AIVIC_FUNCTION_BUNDLE_END owner=detectConstraintChanges */

