const __aivicBundle_9_detectConstraintChangesWithDuplicateAllergy = (() => {
  function detectConstraintChangesWithDuplicateAllergy(duplicate_allergy_input: {
    user_id: string;
    family_member_id: string;
    allergy_items: Array<{
      allergen_name: string;
      allergen_id: string;
      severity_level: string;
      added_at: Date;
    }>;
    timestamp: Date;
    change_source: string;
  }): void {
    if (!String(duplicate_allergy_input.user_id).trim()) {
      throw new Error('user_id is required');
    }
    if (!String(duplicate_allergy_input.family_member_id).trim()) {
      throw new Error('family_member_id is required');
    }
    if (duplicate_allergy_input.timestamp === undefined || duplicate_allergy_input.timestamp === null) {
      throw new Error('timestamp is required');
    }
    if (!String(duplicate_allergy_input.change_source).trim()) {
      throw new Error('change_source is required');
    }
  
    const seen = new Set<string>();
  
    for (const item of duplicate_allergy_input.allergy_items) {
      if (seen.has(item.allergen_id)) {
        throw new Error(`アレルギー情報に重複が検出されました: allergen_id '${item.allergen_id}' が複数回登録されています`);
      }
      seen.add(item.allergen_id);
    }
  }
  return { detectConstraintChangesWithDuplicateAllergy };
})();
