/* AIVIC_FUNCTION_BUNDLE_START owner=evaluateMealConstraintSatisfaction exports=evaluateMealConstraintSatisfaction */
const __aivicBundle_10_evaluateMealConstraintSatisfaction = (() => {
  function evaluateMealConstraintSatisfaction(
    mealPlan: {
      mealId: string;
      name: string;
      dishes: Array<{
        dishId: string;
        name: string;
        cookingTimeMin: number;
      }>;
      totalCookingTimeMin: number;
      estimatedCostJPY: number;
      nutritionScorePercentage: number;
      allergenRiskLevel: number;
      ingredients: Array<{
        ingredient_id?: string;
        ingredient_name?: string;
        quantity?: number;
        unit?: string;
        stock_available?: number;
      }> | string[];
    },
    constraints: {
      nutritionBalance: {
        name: string;
        targetScore: number;
        actualScore: number;
        weight: number;
      };
      cost: {
        name: string;
        budgetJPY: number;
        actualCostJPY: number;
        weight: number;
      };
      cookingTime: {
        name: string;
        maxTimeMin: number;
        actualTimeMin: number;
        weight: number;
      };
      allergenAvoidance: {
        name: string;
        restrictedAllergens: string[];
        detectedAllergens: string[];
        weight: number;
      };
    }
  ): ConstraintEvaluationResult {
    // Validate required inputs
    if (!String(mealPlan.mealId).trim()) {
      throw new Error("mealId is required");
    }
    if (!String(mealPlan.name).trim()) {
      throw new Error("name is required");
    }
    if (!mealPlan.dishes || !Array.isArray(mealPlan.dishes)) {
      throw new Error("dishes is required");
    }
    if (mealPlan.nutritionScorePercentage === undefined || mealPlan.nutritionScorePercentage === null) {
      throw new Error("nutritionScorePercentage is required");
    }
    if (mealPlan.allergenRiskLevel === undefined || mealPlan.allergenRiskLevel === null) {
      throw new Error("allergenRiskLevel is required");
    }
    if (!mealPlan.ingredients || !Array.isArray(mealPlan.ingredients)) {
      throw new Error("ingredients is required");
    }
  
    // Calculate nutrition balance score
    // ratio = targetScore / actualScore
    const nutritionRatio =
      constraints.nutritionBalance.actualScore > 0
        ? constraints.nutritionBalance.targetScore /
          constraints.nutritionBalance.actualScore
        : 0;
    const nutritionScore = Math.min(nutritionRatio * 100, 100);
  
    // Calculate cost score
    // ratio = budgetJPY / actualCostJPY
    const costRatio =
      mealPlan.estimatedCostJPY > 0
        ? constraints.cost.budgetJPY / mealPlan.estimatedCostJPY
        : 0;
    const costScore = Math.min(costRatio * 100, 100);
  
    // Calculate cooking time score
    // ratio = maxTimeMin / actualTimeMin
    const cookingTimeRatio =
      mealPlan.totalCookingTimeMin > 0
        ? constraints.cookingTime.maxTimeMin / mealPlan.totalCookingTimeMin
        : 0;
    const cookingTimeScore = Math.min(cookingTimeRatio * 100, 100);
  
    // Calculate allergen avoidance score
    const detectedAllergenCount = constraints.allergenAvoidance.detectedAllergens.length;
    const allergenScore =
      detectedAllergenCount === 0
        ? 100
        : Math.max(0, 100 - detectedAllergenCount * 10);
  
    // Calculate weighted overall score
    const overallScore =
      nutritionScore * constraints.nutritionBalance.weight +
      costScore * constraints.cost.weight +
      cookingTimeScore * constraints.cookingTime.weight +
      allergenScore * constraints.allergenAvoidance.weight;
  
    // Build satisfaction details
    const result: ConstraintEvaluationResult = {
      constraintScores: {
        nutritionBalance: nutritionScore,
        cost: costScore,
        cookingTime: cookingTimeScore,
        allergenAvoidance: allergenScore,
      },
      overallScore: Math.round(overallScore * 100) / 100,
      satisfactionDetails: {
        nutritionBalanceDetail: {
          score: nutritionScore,
          satisfied: nutritionScore >= 80,
          ratio: nutritionRatio,
        },
        costDetail: {
          score: costScore,
          satisfied: costScore >= 80,
          ratio: costRatio,
        },
        cookingTimeDetail: {
          score: cookingTimeScore,
          satisfied: cookingTimeScore >= 80,
          ratio: cookingTimeRatio,
        },
        allergenAvoidanceDetail: {
          score: allergenScore,
          satisfied: allergenScore >= 80,
          allergenCount: detectedAllergenCount,
        },
      },
    };
  
    return result;
  }
  return { evaluateMealConstraintSatisfaction };
})();
