/* AIVIC_FUNCTION_BUNDLE_START owner=evaluateConstraintSatisfaction exports=evaluateConstraintSatisfaction */
const __aivicBundle_11_evaluateConstraintSatisfaction = (() => {
  function evaluateConstraintSatisfaction(constraints: {
    nutrition: {
      targetCalories: number;
      targetProtein: number;
      actualCalories: number;
      actualProtein: number;
    };
    budget: {
      targetBudget: number;
      actualCost: number;
    };
    cookingTime: {
      targetMinutes: number;
      actualMinutes: number;
    };
  }): {
    nutritionScore: number;
    budgetScore: number;
    cookingTimeScore: number;
    totalScore: number;
  } {
    const nutritionScore = calculateNutritionScore(
      constraints.nutrition.targetCalories,
      constraints.nutrition.actualCalories,
      constraints.nutrition.targetProtein,
      constraints.nutrition.actualProtein
    );
  
    const budgetScore = calculateBudgetScore(
      constraints.budget.targetBudget,
      constraints.budget.actualCost
    );
  
    const cookingTimeScore = calculateCookingTimeScore(
      constraints.cookingTime.targetMinutes,
      constraints.cookingTime.actualMinutes
    );
  
    const totalScore = (nutritionScore + budgetScore + cookingTimeScore) / 3;
  
    return {
      nutritionScore,
      budgetScore,
      cookingTimeScore,
      totalScore,
    };
  }
  
  function calculateNutritionScore(
    targetCalories: number,
    actualCalories: number,
    targetProtein: number,
    actualProtein: number
  ): number {
    if (targetCalories === 0 || targetProtein === 0) {
      return 0;
    }
  
    const calorieRatio = actualCalories / targetCalories;
    const proteinRatio = actualProtein / targetProtein;
  
    const calorieScore = Math.min(calorieRatio, 1) * 100;
    const proteinScore = Math.min(proteinRatio, 1) * 100;
  
    return (calorieScore + proteinScore) / 2;
  }
  
  function calculateBudgetScore(
    targetBudget: number,
    actualCost: number
  ): number {
    if (targetBudget === 0) {
      return 0;
    }
  
    const costRatio = actualCost / targetBudget;
  
    return Math.min(costRatio, 1) * 100;
  }
  
  function calculateCookingTimeScore(
    targetMinutes: number,
    actualMinutes: number
  ): number {
    if (targetMinutes === 0) {
      return 0;
    }
  
    const timeRatio = actualMinutes / targetMinutes;
  
    return Math.min(timeRatio, 1) * 100;
  }
  return { evaluateConstraintSatisfaction };
})();
export const evaluateConstraintSatisfaction = __aivicBundle_11_evaluateConstraintSatisfaction.evaluateConstraintSatisfaction;
/* AIVIC_FUNCTION_BUNDLE_END owner=evaluateConstraintSatisfaction */

