/* AIVIC_FUNCTION_BUNDLE_START owner=evaluateConstraintFulfillment exports=evaluateConstraintFulfillment */
const __aivicBundle_13_evaluateConstraintFulfillment = (() => {
  function evaluateConstraintFulfillment(
    mealPlanProposal: any,
    constraints: any
  ): {
    isFulfilled: boolean;
    fulfillmentScores: {
      caloriesFulfillment: number;
      proteinsFulfillment: number;
      carbohydratesFulfillment: number;
      fatsFulfillment: number;
      allergenFulfillment: number;
      cookingTimeFulfillment: number;
      costFulfillment: number;
      overallScore: number;
    };
    violations: Array<{ type: string; detail: string | number }>;
  } {
    const violations: Array<{ type: string; detail: string | number }> = [];
  
    // Check calorie constraint
    if (mealPlanProposal.calories > constraints.maxCalories) {
      violations.push({
        type: 'カロリー',
        detail: mealPlanProposal.calories
      });
    }
  
    // Check protein constraint
    if (mealPlanProposal.proteins > constraints.maxProteins) {
      violations.push({
        type: 'タンパク質',
        detail: mealPlanProposal.proteins
      });
    }
  
    // Check carbohydrate constraint (minimum)
    if (mealPlanProposal.carbohydrates < constraints.minCarbohydrates) {
      violations.push({
        type: '炭水化物',
        detail: mealPlanProposal.carbohydrates
      });
    }
  
    // Check fat constraint
    if (mealPlanProposal.fats > constraints.maxFats) {
      violations.push({
        type: '脂質',
        detail: mealPlanProposal.fats
      });
    }
  
    // Check allergen constraint
    if (
      constraints.forbiddenAllergens &&
      constraints.forbiddenAllergens.length > 0 &&
      mealPlanProposal.allergens &&
      mealPlanProposal.allergens.length > 0
    ) {
      const hasConflict = mealPlanProposal.allergens.some((allergen: string) =>
        constraints.forbiddenAllergens.includes(allergen)
      );
      if (hasConflict) {
        violations.push({
          type: 'アレルゲン',
          detail: mealPlanProposal.allergens.join(', ')
        });
      }
    }
  
    // Check cooking time constraint
    if (mealPlanProposal.cookingTimeMinutes > constraints.maxCookingTimeMinutes) {
      violations.push({
        type: '調理時間',
        detail: mealPlanProposal.cookingTimeMinutes
      });
    }
  
    // Check cost constraint
    if (mealPlanProposal.estimatedCost > constraints.maxEstimatedCost) {
      violations.push({
        type: 'コスト',
        detail: mealPlanProposal.estimatedCost
      });
    }
  
    // Check required ingredient categories
    if (
      constraints.requiredIngredientCategories &&
      constraints.requiredIngredientCategories.length > 0 &&
      mealPlanProposal.ingredients
    ) {
      const ingredientNames = mealPlanProposal.ingredients.map(
        (ing: any) => ing.name.toLowerCase()
      );
  
      const categoryMap: Record<string, string[]> = {
        vegetable: ['broccoli', 'carrot', 'salad', 'potato', 'vegetable'],
        protein: ['chicken', 'beef', 'pork', 'shrimp', 'egg']
      };
  
      for (const requiredCategory of constraints.requiredIngredientCategories) {
        const categoryItems = categoryMap[requiredCategory] || [];
        const hasCategory = categoryItems.some((item) =>
          ingredientNames.some((name: string) => name.includes(item))
        );
        if (!hasCategory) {
          violations.push({
            type: '必須食材',
            detail: requiredCategory
          });
        }
      }
    }
  
    // If there are violations, throw error with the first violation type
    if (violations.length > 0) {
      throw new Error(`制約条件違反: ${violations[0].type}`);
    }
  
    // Calculate fulfillment scores
    const caloriesFulfillment = Math.min(
      100,
      (mealPlanProposal.calories / constraints.maxCalories) * 100
    );
    const proteinsFulfillment = Math.min(
      100,
      (mealPlanProposal.proteins / constraints.maxProteins) * 100
    );
    const carbohydratesFulfillment = Math.min(
      100,
      (mealPlanProposal.carbohydrates / constraints.minCarbohydrates) * 100
    );
    const fatsFulfillment = Math.min(
      100,
      (mealPlanProposal.fats / constraints.maxFats) * 100
    );
    const allergenFulfillment = 100;
    const cookingTimeFulfillment = Math.min(
      100,
      (mealPlanProposal.cookingTimeMinutes / constraints.maxCookingTimeMinutes) *
        100
    );
    const costFulfillment = Math.min(
      100,
      (mealPlanProposal.estimatedCost / constraints.maxEstimatedCost) * 100
    );
  
    const overallScore = Math.round(
      (caloriesFulfillment +
        proteinsFulfillment +
        carbohydratesFulfillment +
        fatsFulfillment +
        allergenFulfillment +
        cookingTimeFulfillment +
        costFulfillment) /
        7
    );
  
    return {
      isFulfilled: true,
      fulfillmentScores: {
        caloriesFulfillment: Math.round(caloriesFulfillment * 100) / 100,
        proteinsFulfillment: Math.round(proteinsFulfillment * 100) / 100,
        carbohydratesFulfillment: Math.round(carbohydratesFulfillment * 100) / 100,
        fatsFulfillment: Math.round(fatsFulfillment * 100) / 100,
        allergenFulfillment,
        cookingTimeFulfillment: Math.round(cookingTimeFulfillment * 100) / 100,
        costFulfillment: Math.round(costFulfillment * 100) / 100,
        overallScore
      },
      violations: []
    };
  }
  return { evaluateConstraintFulfillment };
})();
export const evaluateConstraintFulfillment = __aivicBundle_13_evaluateConstraintFulfillment.evaluateConstraintFulfillment;
/* AIVIC_FUNCTION_BUNDLE_END owner=evaluateConstraintFulfillment */

/* AIVIC_FUNCTION_BUNDLE_START owner=aggregateMealFeedback exports=aggregateMealFeedback */
const __aivicBundle_14_aggregateMealFeedback = (() => {
  function aggregateMealFeedback(
    feedbackData: Array<{
      date: string;
      satisfaction: number;
      completionRate: number;
      request: string;
    }>
  ): {
    aggregatedData: Array<{
      date: string;
      satisfaction: number;
      completionRate: number;
      request: string;
    }>;
    persistenceStatus: string;
    statistics: {
      averageSatisfaction: number;
      averageCompletionRate: number;
      totalRecords: number;
    };
  } {
    // Validate input
    if (!Array.isArray(feedbackData)) {
      feedbackData = [];
    }
  
    // Aggregate data: structure and validate each record
    const aggregatedData = feedbackData.map((item) => ({
      date: item.date,
      satisfaction: item.satisfaction,
      completionRate: item.completionRate,
      request: item.request,
    }));
  
    // Calculate statistics
    const totalRecords = aggregatedData.length;
    let totalSatisfaction = 0;
    let totalCompletionRate = 0;
  
    aggregatedData.forEach((item) => {
      totalSatisfaction += item.satisfaction;
      totalCompletionRate += item.completionRate;
    });
  
    const averageSatisfaction =
      totalRecords > 0 ? totalSatisfaction / totalRecords : 0;
    const averageCompletionRate =
      totalRecords > 0 ? totalCompletionRate / totalRecords : 0;
  
    return {
      aggregatedData,
      persistenceStatus: "persisted",
      statistics: {
        averageSatisfaction,
        averageCompletionRate,
        totalRecords,
      },
    };
  }
  return { aggregateMealFeedback };
})();
export const aggregateMealFeedback = __aivicBundle_14_aggregateMealFeedback.aggregateMealFeedback;
/* AIVIC_FUNCTION_BUNDLE_END owner=aggregateMealFeedback */

