const __aivicBundle_16_validateMealFeedbackScore = (() => {
  interface ValidateMealFeedbackScoreInput {
    meal_id: string;
    user_id: string;
    satisfaction_score: number;
    completion_degree: number;
    request: string;
  }
  
  interface ValidateMealFeedbackScoreOutput {
    is_valid: boolean;
    meal_id: string;
    user_id: string;
    satisfaction_score: number;
    completion_degree: number;
    request: string;
  }
  
   function validateMealFeedbackScore(
    input: ValidateMealFeedbackScoreInput
  ): ValidateMealFeedbackScoreOutput {
    const { meal_id, user_id, satisfaction_score, completion_degree, request } = input;
  
    if (satisfaction_score < 0 || satisfaction_score > 5) {
      throw new Error(`満足度スコアは0～5の範囲内である必要があります。入力値: ${satisfaction_score}`);
    }
  
    if (completion_degree < 0 || completion_degree > 100) {
      throw new Error(`完食度は0～100の範囲内である必要があります。入力値: ${completion_degree}`);
    }
  
    return {
      is_valid: true,
      meal_id,
      user_id,
      satisfaction_score,
      completion_degree,
      request,
    };
  }
  return { validateMealFeedbackScore };
})();
