/* AIVIC_FUNCTION_BUNDLE_START owner=rankMenuCandidatesByConstraints exports=rankMenuCandidatesByConstraints */
const __aivicBundle_23_rankMenuCandidatesByConstraints = (() => {
  function rankMenuCandidatesByConstraints(
    candidates: Array<{
      candidateId: string;
      satisfactionScore: number;
      nutritionScore: number;
      cookingTimeMinutes: number;
      budgetYen: number;
    }>,
    constraints: {
      nutritionScoreMin: number;
      cookingTimeMinutesMax: number;
      budgetYenMax: number;
    }
  ): Array<RankedMenuCandidate> {
    // Filter candidates that meet all constraints
    const filteredCandidates = candidates.filter(
      (candidate) =>
        candidate.nutritionScore >= constraints.nutritionScoreMin &&
        candidate.cookingTimeMinutes <= constraints.cookingTimeMinutesMax &&
        candidate.budgetYen <= constraints.budgetYenMax
    );
  
    // Sort by priority: nutrition score (desc) → cooking time (asc) → budget (asc) → candidateId (asc for stable ordering)
    const sortedCandidates = filteredCandidates.sort((a, b) => {
      // Primary: nutrition score descending
      if (a.nutritionScore !== b.nutritionScore) {
        return b.nutritionScore - a.nutritionScore;
      }
  
      // Secondary: cooking time ascending
      if (a.cookingTimeMinutes !== b.cookingTimeMinutes) {
        return a.cookingTimeMinutes - b.cookingTimeMinutes;
      }
  
      // Tertiary: budget ascending
      if (a.budgetYen !== b.budgetYen) {
        return a.budgetYen - b.budgetYen;
      }
  
      // Quaternary: candidateId ascending for stable ordering
      return a.candidateId.localeCompare(b.candidateId);
    });
  
    // Assign rank numbers starting from 1
    const rankedCandidates: Array<RankedMenuCandidate> = sortedCandidates.map(
      (candidate, index) => ({
        candidateId: candidate.candidateId,
        satisfactionScore: candidate.satisfactionScore,
        nutritionScore: candidate.nutritionScore,
        cookingTimeMinutes: candidate.cookingTimeMinutes,
        budgetYen: candidate.budgetYen,
        rank: index + 1,
      })
    );
  
    return rankedCandidates;
  }
  return { rankMenuCandidatesByConstraints };
})();
export const rankMenuCandidatesByConstraints = __aivicBundle_23_rankMenuCandidatesByConstraints.rankMenuCandidatesByConstraints;
/* AIVIC_FUNCTION_BUNDLE_END owner=rankMenuCandidatesByConstraints */

/* AIVIC_FUNCTION_BUNDLE_START owner=aggregateFamilyMealEvaluations exports=aggregateFamilyMealEvaluations */
const __aivicBundle_24_aggregateFamilyMealEvaluations = (() => {
  function aggregateFamilyMealEvaluations(
    mealEvaluationInputs: Array<{
      familyGroupId: string;
      familyMemberId: string;
      dishName: string;
      evaluationScore: number;
      evaluationDate: string;
      completionRatio: number;
      feedback: string;
    }>
  ): {
    memberEvaluationHistory: Record<string, Array<any>>;
    dishPreferencePatterns: Record<string, DishPreferencePattern>;
    dashboardSummary: {
      totalEvaluationsCount: number;
      familyMembersCount: number;
      dishesCount: number;
      highPreferenceDishes: string[];
      lowPreferenceDishes: string[];
    };
  } {
    const memberEvaluationHistory: Record<string, Array<any>> = {};
    const dishEvaluationsByDish: Record<
      string,
      Array<{
        memberId: string;
        score: number;
        completionRatio: number;
        evaluationDate: string;
      }>
    > = {};
    const membersByDish: Record<string, Set<string>> = {};
    const allMembers = new Set<string>();
    const allDishes = new Set<string>();
  
    // Build member evaluation history and collect dish data
    for (const evaluation of mealEvaluationInputs) {
      const { familyMemberId, dishName, evaluationScore, evaluationDate, completionRatio } = evaluation;
  
      allMembers.add(familyMemberId);
      allDishes.add(dishName);
  
      // Initialize member history if not exists
      if (!memberEvaluationHistory[familyMemberId]) {
        memberEvaluationHistory[familyMemberId] = [];
      }
  
      // Add evaluation to member history
      memberEvaluationHistory[familyMemberId].push({
        dishName,
        evaluationScore,
        evaluationDate,
        completionRatio,
        feedback: evaluation.feedback,
      });
  
      // Collect dish evaluations
      if (!dishEvaluationsByDish[dishName]) {
        dishEvaluationsByDish[dishName] = [];
      }
      dishEvaluationsByDish[dishName].push({
        memberId: familyMemberId,
        score: evaluationScore,
        completionRatio,
        evaluationDate,
      });
  
      // Track members per dish
      if (!membersByDish[dishName]) {
        membersByDish[dishName] = new Set();
      }
      membersByDish[dishName].add(familyMemberId);
    }
  
    // Sort member histories by evaluation date
    for (const memberId in memberEvaluationHistory) {
      memberEvaluationHistory[memberId].sort(
        (a, b) =>
          new Date(a.evaluationDate).getTime() - new Date(b.evaluationDate).getTime()
      );
    }
  
    // Calculate dish preference patterns
    const dishPreferencePatterns: Record<string, DishPreferencePattern> = {};
  
    for (const dishName of allDishes) {
      const evaluations = dishEvaluationsByDish[dishName];
      const memberPreferences: Record<string, { averageScore: number }> = {};
  
      // Calculate average score per member for this dish
      const scoresByMember: Record<string, number[]> = {};
      for (const evaluation of evaluations) {
        if (!scoresByMember[evaluation.memberId]) {
          scoresByMember[evaluation.memberId] = [];
        }
        scoresByMember[evaluation.memberId].push(evaluation.score);
      }
  
      for (const memberId in scoresByMember) {
        const scores = scoresByMember[memberId];
        const avgScore = scores.reduce((a, b) => a + b, 0) / scores.length;
        memberPreferences[memberId] = { averageScore: avgScore };
      }
  
      // Calculate overall average score
      const allScores = evaluations.map((e) => e.score);
      const averageScore = allScores.reduce((a, b) => a + b, 0) / allScores.length;
  
      // Calculate stability score (inverse of standard deviation)
      const variance =
        allScores.reduce((sum, score) => sum + Math.pow(score - averageScore, 2), 0) /
        allScores.length;
      const stdDev = Math.sqrt(variance);
      const stabilityScore = Math.max(0, 5 - stdDev); // Higher stability = lower variance
  
      // Calculate average completion ratio
      const averageCompletionRatio =
        evaluations.reduce((sum, e) => sum + e.completionRatio, 0) / evaluations.length;
  
      dishPreferencePatterns[dishName] = {
        averageScore,
        evaluationCount: evaluations.length,
        memberPreferences,
        stabilityScore,
        averageCompletionRatio,
      };
    }
  
    // Build dashboard summary
    const highPreferenceDishes: string[] = [];
    const lowPreferenceDishes: string[] = [];
  
    for (const dishName of allDishes) {
      const pattern = dishPreferencePatterns[dishName];
      if (pattern.averageScore >= 4.0) {
        highPreferenceDishes.push(dishName);
      } else if (pattern.averageScore < 3.0) {
        lowPreferenceDishes.push(dishName);
      }
    }
  
    const dashboardSummary = {
      totalEvaluationsCount: mealEvaluationInputs.length,
      familyMembersCount: allMembers.size,
      dishesCount: allDishes.size,
      highPreferenceDishes,
      lowPreferenceDishes,
    };
  
    return {
      memberEvaluationHistory,
      dishPreferencePatterns,
      dashboardSummary,
    };
  }
  return { aggregateFamilyMealEvaluations };
})();
export const aggregateFamilyMealEvaluations = __aivicBundle_24_aggregateFamilyMealEvaluations.aggregateFamilyMealEvaluations;
/* AIVIC_FUNCTION_BUNDLE_END owner=aggregateFamilyMealEvaluations */

