/* AIVIC_FUNCTION_BUNDLE_START owner=calculateNutritionAchievementDashboard exports=calculateNutritionAchievementDashboard */
const __aivicBundle_26_calculateNutritionAchievementDashboard = (() => {
  function calculateNutritionAchievementDashboard(nutritionData: {
    items: Array<{
      nutrient_id: string;
      nutrient_name: string;
      target_value: number;
      actual_value: number;
      unit: string;
    }>;
  }): {
    achievements: Array<{
      nutrient_id: string;
      nutrient_name: string;
      target_value: number;
      actual_value: number;
      achievement_rate: number;
      gap: number;
      gap_abs: number;
      priority: number;
      unit: string;
      visualization_value: number;
    }>;
    prioritized_items: Array<{
      nutrient_id: string;
      nutrient_name: string;
      target_value: number;
      actual_value: number;
      achievement_rate: number;
      gap: number;
      gap_abs: number;
      priority: number;
      unit: string;
      visualization_value: number;
    }>;
    summary: {
      total_items: number;
      average_achievement_rate: number;
      highest_priority_nutrient: {
        nutrient_id: string;
        nutrient_name: string;
        gap_abs: number;
      };
    };
  } {
    const achievements = nutritionData.items.map((item) => {
      const achievementRate = (item.actual_value / item.target_value) * 100;
      const gap = item.target_value - item.actual_value;
      const gapAbs = Math.abs(gap);
      const visualizationValue = Math.min(Math.max(achievementRate, 0), 100);
  
      return {
        nutrient_id: item.nutrient_id,
        nutrient_name: item.nutrient_name,
        target_value: item.target_value,
        actual_value: item.actual_value,
        achievement_rate: Math.round(achievementRate * 100) / 100,
        gap,
        gap_abs: gapAbs,
        priority: 0,
        unit: item.unit,
        visualization_value: visualizationValue,
      };
    });
  
    const prioritizedItems = [...achievements]
      .sort((a, b) => b.gap_abs - a.gap_abs)
      .map((item, index) => ({
        ...item,
        priority: index + 1,
      }));
  
    const totalItems = achievements.length;
    const averageAchievementRate =
      totalItems > 0
        ? Math.round(
            (achievements.reduce((sum, item) => sum + item.achievement_rate, 0) /
              totalItems) *
              100
          ) / 100
        : 0;
  
    const highestPriorityNutrient =
      prioritizedItems.length > 0
        ? {
            nutrient_id: prioritizedItems[0].nutrient_id,
            nutrient_name: prioritizedItems[0].nutrient_name,
            gap_abs: prioritizedItems[0].gap_abs,
          }
        : {
            nutrient_id: '',
            nutrient_name: '',
            gap_abs: 0,
          };
  
    return {
      achievements,
      prioritized_items: prioritizedItems,
      summary: {
        total_items: totalItems,
        average_achievement_rate: averageAchievementRate,
        highest_priority_nutrient: highestPriorityNutrient,
      },
    };
  }
  return { calculateNutritionAchievementDashboard };
})();
export const calculateNutritionAchievementDashboard = __aivicBundle_26_calculateNutritionAchievementDashboard.calculateNutritionAchievementDashboard;
