/* AIVIC_FUNCTION_BUNDLE_START owner=calculateNutrientAchievementRate exports=calculateNutrientAchievementRate */
const __aivicBundle_27_calculateNutrientAchievementRate = (() => {
  function calculateNutrientAchievementRate(
    targetValues: { calories: number; protein: number; fat: number },
    actualValues: { calories: number; protein: number; fat: number }
  ): {
    overallAchievementRate: number;
    nutrients: Array<{
      name: string;
      target: number;
      actual: number;
      achievementRate: number;
      status: string;
    }>;
    statusIndicator: string;
    completionMessage: string;
  } {
    const nutrientNames = ["calories", "protein", "fat"] as const;
  
    const nutrients = nutrientNames.map((name) => {
      const target = targetValues[name];
      const actual = actualValues[name];
      const achievementRate =
        target > 0 ? Math.round((actual / target) * 100) : 0;
      const status = achievementRate >= 100 ? "success" : "incomplete";
  
      return {
        name,
        target,
        actual,
        achievementRate,
        status,
      };
    });
  
    const overallAchievementRate = Math.round(
      nutrients.reduce((sum, n) => sum + n.achievementRate, 0) /
        nutrients.length
    );
  
    const statusIndicator =
      overallAchievementRate === 100
        ? "green"
        : overallAchievementRate >= 80
          ? "yellow"
          : "red";
  
    const completionMessage =
      overallAchievementRate === 100 ? "達成完了" : "達成途中";
  
    return {
      overallAchievementRate,
      nutrients,
      statusIndicator,
      completionMessage,
    };
  }
  return { calculateNutrientAchievementRate };
})();
export const calculateNutrientAchievementRate = __aivicBundle_27_calculateNutrientAchievementRate.calculateNutrientAchievementRate;
