/* AIVIC_FUNCTION_BUNDLE_START owner=calculateNutritionAchievementRate exports=calculateNutritionAchievementRate */
const __aivicBundle_28_calculateNutritionAchievementRate = (() => {
  function calculateNutritionAchievementRate(
    input: any,
    secondInput?: any
  ): any {
    // Handle two different input patterns based on test calls
    
    // Pattern 1: Two separate objects (recommended_nutrients, actual_nutrients)
    if (secondInput !== undefined) {
      const recommended = input as Record<string, number>;
      const actual = secondInput as Record<string, number>;
      
      const nutrients = Object.keys(recommended);
      const achievementRates: Record<string, number> = {};
      
      for (const nutrient of nutrients) {
        const recommendedValue = recommended[nutrient];
        const actualValue = actual[nutrient];
        
        if (recommendedValue <= 0) {
          throw new Error('推奨摂取量は正の数値である必要があります');
        }
        
        if (actualValue < 0) {
          throw new Error('摂取量は0以上の値である必要があります');
        }
        
        const rate = (actualValue / recommendedValue) * 100;
        const roundedRate = Math.round(rate * 100) / 100;
        achievementRates[nutrient.replace(/_[a-z]/, (m) => m[1].toUpperCase()).replace(/_g|_mg/, '') + '_achievement_rate'] = roundedRate;
      }
      
      // Calculate average achievement rate
      const rates = Object.values(achievementRates);
      const average = rates.length > 0 ? rates.reduce((a, b) => a + b, 0) / rates.length : 0;
      const roundedAverage = Math.round(average * 100) / 100;
      
      return {
        protein_achievement_rate: achievementRates['protein_achievement_rate'] ?? 0,
        calcium_achievement_rate: achievementRates['calcium_achievement_rate'] ?? 0,
        vitamin_c_achievement_rate: achievementRates['vitamin_c_achievement_rate'] ?? 0,
        average_achievement_rate: roundedAverage,
      };
    }
    
    // Pattern 2: Single object with target_intake and actual_intake
    const singleInput = input as Record<string, any>;
    
    if ('target_intake' in singleInput && 'actual_intake' in singleInput) {
      const targetIntake = singleInput.target_intake as number;
      const actualIntake = singleInput.actual_intake as number;
      
      if (targetIntake <= 0) {
        throw new Error('推奨摂取量は正の数値である必要があります');
      }
      
      if (actualIntake < 0) {
        throw new Error('摂取量は0以上の値である必要があります');
      }
      
      const achievementRatePercent = (actualIntake / targetIntake) * 100;
      const status = achievementRatePercent === 0 ? '未達成' : '達成';
      
      return {
        achievement_rate_percent: achievementRatePercent,
        achievement_status: status,
      };
    }
    
    // Pattern 3: Complex input with userId, startDate, endDate, nutritionItems
    if ('userId' in singleInput || 'startDate' in singleInput) {
      const performanceRecords = singleInput.performanceRecords as any[] || [];
      const targetItems = singleInput.nutritionItems as any[] || [];
      
      if (performanceRecords.length === 0) {
        const error: any = new Error('データ不足: 指定期間内に栄養摂取実績データが見つかりません');
        error.statusCode = 422;
        error.errorCode = 'INSUFFICIENT_PERFORMANCE_DATA';
        error.details = {
          availableRecordsCount: 0,
          requiredRecordCount: 1,
        };
        throw error;
      }
      
      return {
        performanceRecords,
        targetItems,
      };
    }
    
    // Fallback
    return {
      protein_achievement_rate: 0,
      calcium_achievement_rate: 0,
      vitamin_c_achievement_rate: 0,
      average_achievement_rate: 0,
    };
  }
  return { calculateNutritionAchievementRate };
})();
export const calculateNutritionAchievementRate = __aivicBundle_28_calculateNutritionAchievementRate.calculateNutritionAchievementRate;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateNutritionAchievementRate */

