/* AIVIC_FUNCTION_BUNDLE_START owner=analyzeMonthlyFoodCostExcessFactors exports=analyzeMonthlyFoodCostExcessFactors */
const __aivicBundle_30_analyzeMonthlyFoodCostExcessFactors = (() => {
  function analyzeMonthlyFoodCostExcessFactors(input: any): any {
    // Handle both snake_case and camelCase input properties
    
    
    const budgetLimit = input.budget_limit || input.monthlyBudget;
    const actualExpenditure = input.actual_expenditure || input.monthlyActualCost;
    
    const ingredientCompositions = input.ingredient_compositions || input.generatedMenus;
    const purchaseHistory = input.purchaseHistory || [];
    
  
    // Validate required fields
    if (!ingredientCompositions || !Array.isArray(ingredientCompositions)) {
      throw new Error("食材構成データが不正です");
    }
  
    // Check for incomplete composition data
    for (const composition of ingredientCompositions) {
      if (!composition.ingredient_name && !composition.name) {
        throw new Error("食材構成データに必須フィールド(ingredient_name)が欠落しています");
      }
    }
  
    const calculatedOverageAmount = actualExpenditure - budgetLimit;
    const calculatedOveragePercentage = budgetLimit > 0 
      ? (calculatedOverageAmount / budgetLimit) * 100 
      : 0;
  
    // Calculate ingredient composition overage
    let ingredientCompositionOverage = 0;
    let unitPriceVarianceOverage = 0;
  
    // Analyze ingredient composition impact
    if (ingredientCompositions.length > 0) {
      const compositionCost = ingredientCompositions.reduce((sum: number, comp: any) => {
        const price = comp.unit_price || comp.unitPrice || 0;
        const qty = comp.quantity || 0;
        return sum + (price * qty);
      }, 0);
      ingredientCompositionOverage = Math.max(0, compositionCost - (budgetLimit * 0.6));
    }
  
    // Analyze unit price variance impact
    if (purchaseHistory.length > 0) {
      unitPriceVarianceOverage = purchaseHistory.reduce((sum: number, purchase: any) => {
        const plannedPrice = purchase.plannedUnitPrice || 0;
        const actualPrice = purchase.actualUnitPrice || 0;
        const qty = purchase.quantity || 0;
        const variance = Math.max(0, (actualPrice - plannedPrice) * qty);
        return sum + variance;
      }, 0);
    }
  
    // Identify top overage ingredients
    const ingredientOverageMap = new Map<string, { overage: number; reason: string }>();
  
    for (const composition of ingredientCompositions) {
      const name = composition.ingredient_name || composition.name;
      const price = composition.unit_price || composition.unitPrice || 0;
      const qty = composition.quantity || 0;
      const cost = price * qty;
  
      if (cost > 0) {
        ingredientOverageMap.set(name, {
          overage: cost,
          reason: "食材構成による超過"
        });
      }
    }
  
    for (const purchase of purchaseHistory) {
      const name = purchase.ingredientName;
      const plannedPrice = purchase.plannedUnitPrice || 0;
      const actualPrice = purchase.actualUnitPrice || 0;
      const qty = purchase.quantity || 0;
      const variance = Math.max(0, (actualPrice - plannedPrice) * qty);
  
      if (variance > 0) {
        const existing = ingredientOverageMap.get(name) || { overage: 0, reason: "" };
        ingredientOverageMap.set(name, {
          overage: existing.overage + variance,
          reason: "単価変動による超過"
        });
      }
    }
  
    const topOverageIngredients = Array.from(ingredientOverageMap.entries())
      .map(([name, data]) => ({
        ingredientName: name,
        overageContribution: data.overage,
        reason: data.reason
      }))
      .sort((a, b) => b.overageContribution - a.overageContribution)
      .slice(0, 5);
  
    // Determine next month priority condition
    let nextMonthPriorityCondition = "バランス重視";
    if (calculatedOveragePercentage > 10) {
      nextMonthPriorityCondition = "予算重視";
    } else if (calculatedOveragePercentage > 5) {
      nextMonthPriorityCondition = "コスト最適化";
    }
  
    // Calculate recommended budget adjustment
    const recommendedBudgetAdjustment = budgetLimit * 1.1 + (calculatedOverageAmount > 0 ? calculatedOverageAmount : 0);
  
    // Determine adjustment rationale
    let adjustmentRationale = "前月の実績に基づき、予算を調整しました";
    if (calculatedOveragePercentage > 10) {
      adjustmentRationale = "超過率が高いため、予算を大幅に見直す必要があります";
    } else if (calculatedOveragePercentage > 5) {
      adjustmentRationale = "単価変動と食材構成の見直しにより、予算を最適化します";
    }
  
    return {
      overageAmount: calculatedOverageAmount,
      overagePercentage: Math.round(calculatedOveragePercentage * 100) / 100,
      ingredientCompositionOverage: Math.round(ingredientCompositionOverage * 100) / 100,
      unitPriceVarianceOverage: Math.round(unitPriceVarianceOverage * 100) / 100,
      topOverageIngredients,
      nextMonthPriorityCondition,
      recommendedBudgetAdjustment: Math.round(recommendedBudgetAdjustment * 100) / 100,
      adjustmentRationale
    };
  }
  return { analyzeMonthlyFoodCostExcessFactors };
})();
export const analyzeMonthlyFoodCostExcessFactors = __aivicBundle_30_analyzeMonthlyFoodCostExcessFactors.analyzeMonthlyFoodCostExcessFactors;
/* AIVIC_FUNCTION_BUNDLE_END owner=analyzeMonthlyFoodCostExcessFactors */

