/* AIVIC_FUNCTION_BUNDLE_START owner=calculateMenuPriorityScores exports=calculateMenuPriorityScores */
const __aivicBundle_33_calculateMenuPriorityScores = (() => {
  interface CalculateMenuPriorityScoresInput {
    menu_plans: Array<{
      menu_id: string;
      menu_name: string;
      ingredients: Array<{
        ingredient_id: string;
        ingredient_name: string;
        quantity: number;
      }>;
    }>;
    stock_data: Record<
      string,
      {
        stock_quantity: number;
        distributor_id: string;
      }
    >;
    price_data: Record<
      string,
      {
        base_price: number;
        discount_rate: number;
        is_on_sale: boolean;
      }
    >;
    seasonal_ingredients: {
      current_season: string;
      seasonal_list: string[];
    };
    current_date: string;
  }
  
  interface CalculateMenuPriorityScoresResult {
    menu_id: string;
    priority_score: number;
    seasonal_score: number;
    discount_score: number;
    stock_score: number;
  }
  
   function calculateMenuPriorityScores(
    input: CalculateMenuPriorityScoresInput
  ): CalculateMenuPriorityScoresResult[] {
    const { menu_plans, stock_data, price_data, seasonal_ingredients } = input;
  
    const results: CalculateMenuPriorityScoresResult[] = menu_plans.map(
      (menu) => {
        let seasonal_score = 0;
        let discount_score = 0;
        let stock_score = 0;
  
        // Calculate seasonal score
        const seasonal_ingredient_count = menu.ingredients.filter((ing) =>
          seasonal_ingredients.seasonal_list.includes(ing.ingredient_id)
        ).length;
        seasonal_score =
          (seasonal_ingredient_count / menu.ingredients.length) * 100;
  
        // Calculate discount score
        let total_discount_value = 0;
        let discounted_ingredient_count = 0;
        menu.ingredients.forEach((ing) => {
          const price_info = price_data[ing.ingredient_id];
          if (price_info && price_info.is_on_sale) {
            total_discount_value += price_info.discount_rate * 100;
            discounted_ingredient_count += 1;
          }
        });
        if (discounted_ingredient_count > 0) {
          discount_score =
            (total_discount_value / discounted_ingredient_count) *
            (discounted_ingredient_count / menu.ingredients.length);
        }
  
        // Calculate stock score
        let total_stock = 0;
        menu.ingredients.forEach((ing) => {
          const stock_info = stock_data[ing.ingredient_id];
          if (stock_info) {
            total_stock += stock_info.stock_quantity;
          }
        });
        stock_score = Math.min((total_stock / 100) * 10, 100);
  
        // Weighted priority score: seasonal 30%, discount 30%, stock 40%
        const priority_score =
          seasonal_score * 0.3 + discount_score * 0.3 + stock_score * 0.4;
  
        return {
          menu_id: menu.menu_id,
          priority_score: Math.min(Math.max(priority_score, 0), 100),
          seasonal_score: Math.min(Math.max(seasonal_score, 0), 100),
          discount_score: Math.min(Math.max(discount_score, 0), 100),
          stock_score: Math.min(Math.max(stock_score, 0), 100),
        };
      }
    );
  
    // Sort by priority_score descending
    results.sort((a, b) => b.priority_score - a.priority_score);
  
    return results;
  }
  return { calculateMenuPriorityScores };
})();
export const calculateMenuPriorityScores = __aivicBundle_33_calculateMenuPriorityScores.calculateMenuPriorityScores;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateMenuPriorityScores */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculateMealPriorityScore exports=calculateMealPriorityScore */
const __aivicBundle_34_calculateMealPriorityScore = (() => {
  function calculateMealPriorityScore(meal: {
    mealPlanId: string;
    dishes: Array<{
      dishId: string;
      dishName: string;
      ingredients: Array<{
        ingredientId: string;
        name: string;
        stockFulfillmentRate: number;
        discountRate: number;
        isSeasonalItem: boolean;
      }>;
    }>;
    createdAt: string;
  }): number {
    // Validate required inputs
    if (!meal.mealPlanId || String(meal.mealPlanId).trim() === '') {
      throw new Error('mealPlanId is required');
    }
    if (!meal.createdAt || String(meal.createdAt).trim() === '') {
      throw new Error('createdAt is required');
    }
  
    if (!meal.dishes || meal.dishes.length === 0) {
      return 0;
    }
  
    let totalStockFulfillmentRate = 0;
    let totalIngredients = 0;
    let seasonalItemCount = 0;
  
    for (const dish of meal.dishes) {
      if (!dish.ingredients) continue;
      for (const ingredient of dish.ingredients) {
        totalStockFulfillmentRate += ingredient.stockFulfillmentRate;
        totalIngredients += 1;
        if (ingredient.isSeasonalItem) {
          seasonalItemCount += 1;
        }
      }
    }
  
    if (totalIngredients === 0) {
      return 0;
    }
  
    const averageStockFulfillmentRate = totalStockFulfillmentRate / totalIngredients;
  
    const baseScore = averageStockFulfillmentRate;
  
    const seasonalBonus = seasonalItemCount > 0 ? 10 : 0;
  
    const finalScore = baseScore + seasonalBonus;
  
    return Math.min(finalScore, 100);
  }
  return { calculateMealPriorityScore };
})();
export const calculateMealPriorityScore = __aivicBundle_34_calculateMealPriorityScore.calculateMealPriorityScore;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateMealPriorityScore */

