/* AIVIC_FUNCTION_BUNDLE_START owner=calculateSeasonalAndDiscountPriority exports=calculateSeasonalAndDiscountPriority */
const __aivicBundle_36_calculateSeasonalAndDiscountPriority = (() => {
  function calculateSeasonalAndDiscountPriority(
    input: any
  ): {
    processed_count: number;
    skipped_count: number;
    total_count: number;
    scored_products: Array<{
      product_id: string;
      product_name: string;
      priority_score: number;
      price: number;
      discount_rate: number;
      is_seasonal: boolean;
      season_score: number;
    }>;
    skipped_products: Array<{
      product_id: string;
      product_name: string;
      reason: string;
      is_seasonal: boolean;
      season_score: number;
      discount_rate: number;
    }>;
    warnings: string[];
    is_partial_result: boolean;
    data_quality_score: number;
  } {
    const products = Array.isArray(input) ? input : [];
    const total_count = products.length;
  
    const scored_products: Array<{
      product_id: string;
      product_name: string;
      priority_score: number;
      price: number;
      discount_rate: number;
      is_seasonal: boolean;
      season_score: number;
    }> = [];
  
    const skipped_products: Array<{
      product_id: string;
      product_name: string;
      reason: string;
      is_seasonal: boolean;
      season_score: number;
      discount_rate: number;
    }> = [];
  
    const warnings: string[] = [];
  
    for (const product of products) {
      const hasValidPrice =
        product.price !== undefined &&
        product.price !== null &&
        typeof product.price === "number";
  
      if (!hasValidPrice) {
        skipped_products.push({
          product_id: product.product_id,
          product_name: product.product_name,
          reason: "price_missing",
          is_seasonal: product.is_seasonal,
          season_score: product.season_score,
          discount_rate: product.discount_rate,
        });
        warnings.push(
          `Product ${product.product_id} (${product.product_name}): price_missing`
        );
        continue;
      }
  
      const priority_score = product.season_score || 0;
  
      scored_products.push({
        product_id: product.product_id,
        product_name: product.product_name,
        priority_score,
        price: product.price,
        discount_rate: product.discount_rate,
        is_seasonal: product.is_seasonal,
        season_score: product.season_score,
      });
    }
  
    const processed_count = scored_products.length;
    const skipped_count = skipped_products.length;
    const is_partial_result = skipped_count > 0;
    const data_quality_score =
      total_count > 0 ? Math.round((processed_count / total_count) * 100) : 0;
  
    return {
      processed_count,
      skipped_count,
      total_count,
      scored_products,
      skipped_products,
      warnings,
      is_partial_result,
      data_quality_score,
    };
  }
  return { calculateSeasonalAndDiscountPriority };
})();
export const calculateSeasonalAndDiscountPriority = __aivicBundle_36_calculateSeasonalAndDiscountPriority.calculateSeasonalAndDiscountPriority;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateSeasonalAndDiscountPriority */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculateDivergenceAnalysis exports=calculateDivergenceAnalysis */
const __aivicBundle_37_calculateDivergenceAnalysis = (() => {
  function calculateDivergenceAnalysis(input: any): any {
    // Handle both camelCase and snake_case input formats
    const forecastData = input.forecastData || input.forecast_data || [];
    const actualData = input.actualData || input.actual_data || [];
    const params = input.params || {};
  
    // Determine if this is the detailed analysis format or simple format
    const isDetailedFormat = Array.isArray(forecastData) && forecastData.length > 0 && 'date' in forecastData[0];
    
    if (isDetailedFormat) {
      return calculateDetailedDivergenceAnalysis(forecastData, actualData, params);
    } else {
      return calculateSimpleDivergenceAnalysis(forecastData, actualData);
    }
  }
  
  function calculateDetailedDivergenceAnalysis(
    forecastData: any[],
    actualData: any[],
    params: any
  ): any {
    const categories = params.categories || [];
    const timeUnit = params.timeUnit || 'daily';
    
    // Group data by category and date
    const forecastByCategory: Record<string, Record<string, number>> = {};
    const actualByCategory: Record<string, Record<string, number>> = {};
    const dateSet = new Set<string>();
  
    forecastData.forEach((item: any) => {
      const cat = item.category;
      const date = item.date;
      if (!forecastByCategory[cat]) forecastByCategory[cat] = {};
      forecastByCategory[cat][date] = item.forecastDemand;
      dateSet.add(date);
    });
  
    actualData.forEach((item: any) => {
      const cat = item.category;
      const date = item.date;
      if (!actualByCategory[cat]) actualByCategory[cat] = {};
      actualByCategory[cat][date] = item.actualDemand;
      dateSet.add(date);
    });
  
    const sortedDates = Array.from(dateSet).sort();
  
    // Calculate MAPE and errors for each category
    const categoryAnalysis: any[] = [];
    const allErrors: number[] = [];
    const errorsByDate: Record<string, number[]> = {};
  
    categories.forEach((category: string) => {
      const forecast = forecastByCategory[category] || {};
      const actual = actualByCategory[category] || {};
      
      let totalMape = 0;
      let count = 0;
      const mapeValues: number[] = [];
  
      sortedDates.forEach((date: string) => {
        const f = forecast[date] || 0;
        const a = actual[date] || 0;
        
        if (f > 0) {
          const mape = Math.abs(f - a) / f * 100;
          mapeValues.push(mape);
          totalMape += mape;
          count++;
          allErrors.push(mape);
          
          if (!errorsByDate[date]) errorsByDate[date] = [];
          errorsByDate[date].push(mape);
        }
      });
  
      const avgMape = count > 0 ? totalMape / count : 0;
      const divergenceLevel = avgMape < 5 ? 'normal' : avgMape < 15 ? 'warning' : 'critical';
  
      categoryAnalysis.push({
        category,
        sampleCount: count,
        divergenceLevel,
        mapeValues,
        averageMape: avgMape,
      });
    });
  
    // Time series analysis
    const timeSeriesAnalysis = sortedDates.map((date: string, idx: number) => {
      const errors = errorsByDate[date] || [];
      const avgError = errors.length > 0 ? errors.reduce((a, b) => a + b, 0) / errors.length : 0;
      return {
        date,
        week_id: idx,
        averageError: avgError,
        errorCount: errors.length,
      };
    });
  
    // Calculate overall metrics
    const overallMape = allErrors.length > 0 ? allErrors.reduce((a, b) => a + b, 0) / allErrors.length : 0;
    const accuracyScore = Math.max(0, Math.min(100, 100 - overallMape));
    
    // RMSE and MAE
    const squaredErrors = allErrors.map(e => (e / 100) * (e / 100));
    const rmse = Math.sqrt(squaredErrors.reduce((a, b) => a + b, 0) / allErrors.length);
    const mae = allErrors.reduce((a, b) => a + b, 0) / allErrors.length / 100;
  
    // Visualization data
    const lineChartData = {
      labels: sortedDates,
      datasets: categories.map((cat: string) => {
        const forecast = forecastByCategory[cat] || {};
        const actual = actualByCategory[cat] || {};
        const mapeData = sortedDates.map((date: string) => {
          const f = forecast[date] || 0;
          const a = actual[date] || 0;
          return f > 0 ? Math.abs(f - a) / f * 100 : 0;
        });
        return {
          label: `${cat}_MAPE`,
          data: mapeData,
        };
      }),
    };
  
    const heatmapData: any[] = [];
    sortedDates.forEach((date: string) => {
      categories.forEach((cat: string) => {
        const forecast = forecastByCategory[cat] || {};
        const actual = actualByCategory[cat] || {};
        const f = forecast[date] || 0;
        const a = actual[date] || 0;
        const errorPercent = f > 0 ? Math.abs(f - a) / f * 100 : 0;
        const severity = errorPercent < 5 ? 'low' : errorPercent < 15 ? 'medium' : 'high';
        heatmapData.push({
          category: cat,
          date,
          errorPercent,
          severity,
        });
      });
    });
  
    // Trend analysis
    const errors = sortedDates.map(date => errorsByDate[date]?.reduce((a, b) => a + b, 0) / (errorsByDate[date]?.length || 1) || 0);
    let direction = 'stable';
    if (errors.length > 1) {
      const trend = errors[errors.length - 1] - errors[0];
      direction = trend > 2 ? 'up' : trend < -2 ? 'down' : 'stable';
    }
    const volatility = errors.length > 1 
      ? (Math.max(...errors) - Math.min(...errors)) / (Math.max(...errors) || 1) * 100
      : 0;
  
    const analysisDate = new Date().toISOString();
  
    return {
      categoryAnalysis,
      timeSeriesAnalysis,
      visualization: {
        lineChartData,
        heatmapData,
      },
      overallMetrics: {
        rmse,
        mae,
        accuracyScore,
      },
      trendAnalysis: {
        direction,
        volatility,
      },
      metadata: {
        analysisDate,
        dataPoints: forecastData.length,
        categoriesAnalyzed: categories.length,
        timeUnitUsed: 'daily',
      },
    };
  }
  
  function calculateSimpleDivergenceAnalysis(
    forecastData: any[],
    actualData: any[]
  ): any {
    // Build maps for quick lookup
    const forecastMap: Record<string, number> = {};
    const actualMap: Record<string, number> = {};
  
    forecastData.forEach((item: any) => {
      const key = `${item.item_id}`;
      forecastMap[key] = item.forecast_quantity || 0;
    });
  
    actualData.forEach((item: any) => {
      const key = `${item.item_id}`;
      actualMap[key] = item.actual_quantity || 0;
    });
  
    // Calculate divergence for each item
    const improvementSuggestions: any[] = [];
    const itemIds = new Set<number>();
  
    forecastData.forEach((item: any) => itemIds.add(item.item_id));
    actualData.forEach((item: any) => itemIds.add(item.item_id));
  
    const divergenceRates: Array<{ itemId: number; rate: number; itemName: string }> = [];
  
    itemIds.forEach((itemId: number) => {
      const forecast = forecastMap[itemId] || 0;
      const actual = actualMap[itemId] || 0;
      
      const divergenceRate = forecast > 0 ? Math.abs(forecast - actual) / forecast : 0;
      const itemName = forecastData.find((d: any) => d.item_id === itemId)?.item_name ||
                       actualData.find((d: any) => d.item_id === itemId)?.item_name ||
                       `Item ${itemId}`;
      
      divergenceRates.push({ itemId, rate: divergenceRate, itemName });
    });
  
    // Sort by divergence rate descending
    divergenceRates.sort((a, b) => b.rate - a.rate);
  
    // Assign priorities: top 2 high, next 2 medium, rest low
    divergenceRates.forEach((item, idx) => {
      let priority = '低';
      if (idx < 2) priority = '高';
      else if (idx < 4) priority = '中';
  
      const expectedEffect = item.rate * 100; // percentage improvement potential
  
      improvementSuggestions.push({
        item_id: item.itemId,
        item_name: item.itemName,
        divergence_rate: item.rate,
        divergence_factor: `予測値と実績値の乖離が${(item.rate * 100).toFixed(1)}%`,
        priority,
        expected_effect: expectedEffect,
      });
    });
  
    const analysisTimestamp = new Date().toISOString();
    const highPriorityCount = improvementSuggestions.filter(s => s.priority === '高').length;
    const mediumPriorityCount = improvementSuggestions.filter(s => s.priority === '中').length;
    const lowPriorityCount = improvementSuggestions.filter(s => s.priority === '低').length;
  
    return {
      improvement_suggestions: improvementSuggestions,
      analysis_timestamp: analysisTimestamp,
      total_items_analyzed: itemIds.size,
      high_priority_count: highPriorityCount,
      medium_priority_count: mediumPriorityCount,
      low_priority_count: lowPriorityCount,
    };
  }
  return { calculateDivergenceAnalysis };
})();
export const calculateDivergenceAnalysis = __aivicBundle_37_calculateDivergenceAnalysis.calculateDivergenceAnalysis;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateDivergenceAnalysis */

