/* AIVIC_FUNCTION_BUNDLE_START owner=calculateDemandForecastPrecision exports=calculateDemandForecastPrecision */
const __aivicBundle_40_calculateDemandForecastPrecision = (() => {
  interface CalculateDemandForecastPrecisionInput {
    predicted_demand: number;
    actual_demand: number;
    threshold_percentage: number;
  }
  
  interface CalculateDemandForecastPrecisionResult {
    meets_threshold: boolean;
    precision_percentage: number;
    judgment_status: 'below_threshold' | 'meets_threshold' | 'exceeds_threshold';
  }
  
   function calculateDemandForecastPrecision(
    input: CalculateDemandForecastPrecisionInput
  ): CalculateDemandForecastPrecisionResult {
    const { predicted_demand, actual_demand, threshold_percentage } = input;
  
    const absoluteError = Math.abs(predicted_demand - actual_demand);
    const precisionPercentage = ((predicted_demand - absoluteError) / predicted_demand) * 100;
  
    const meetsThreshold = precisionPercentage >= threshold_percentage;
  
    let judgmentStatus: 'below_threshold' | 'meets_threshold' | 'exceeds_threshold';
    if (precisionPercentage < threshold_percentage) {
      judgmentStatus = 'below_threshold';
    } else if (precisionPercentage === threshold_percentage) {
      judgmentStatus = 'meets_threshold';
    } else {
      judgmentStatus = 'exceeds_threshold';
    }
  
    return {
      meets_threshold: meetsThreshold,
      precision_percentage: precisionPercentage,
      judgment_status: judgmentStatus,
    };
  }
  return { calculateDemandForecastPrecision };
})();
export const calculateDemandForecastPrecision = __aivicBundle_40_calculateDemandForecastPrecision.calculateDemandForecastPrecision;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateDemandForecastPrecision */

