/* AIVIC_FUNCTION_BUNDLE_START owner=analyzeDeviationWithValidation exports=analyzeDeviationWithValidation */
const __aivicBundle_42_analyzeDeviationWithValidation = (() => {
  function analyzeDeviationWithValidation(
    data: Array<{
      date: string;
      predictedDemand: any;
      actualDemand: number;
    }>
  ): {
    status: string;
    totalDeviation: number;
    deviationRate: number;
    analysisInterrupted: boolean;
  } {
    // Validate date format
    for (const record of data) {
      const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
      if (!dateRegex.test(record.date)) {
        throw new Error(`日付フォーマットが不正です: ${record.date}`);
      }
    }
  
    // Validate predictedDemand values
    for (const record of data) {
      const predicted = record.predictedDemand;
  
      // Check for null, undefined, empty string
      if (predicted === null || predicted === undefined || predicted === "") {
        throw new Error(`予測値が無効です: ${predicted}`);
      }
  
      // Check for non-numeric strings
      if (typeof predicted === "string") {
        throw new Error(`予測値が無効です: ${predicted}`);
      }
  
      // Check for negative numbers
      if (typeof predicted === "number" && predicted < 0) {
        throw new Error(`予測値が無効です: ${predicted}`);
      }
  
      // Check for non-number types (symbols, objects, etc.)
      if (typeof predicted !== "number") {
        throw new Error(`予測値が無効です: ${predicted}`);
      }
    }
  
    // Calculate total deviation
    let totalDeviation = 0;
    for (const record of data) {
      const deviation = Math.abs(record.predictedDemand - record.actualDemand);
      totalDeviation += deviation;
    }
  
    // Calculate total predicted demand
    let totalPredicted = 0;
    for (const record of data) {
      totalPredicted += record.predictedDemand;
    }
  
    // Calculate deviation rate as percentage
    const deviationRate =
      totalPredicted > 0
        ? Math.round((totalDeviation / totalPredicted) * 100 * 100) / 100
        : 0;
  
    return {
      status: "success",
      totalDeviation,
      deviationRate,
      analysisInterrupted: false,
    };
  }
  return { analyzeDeviationWithValidation };
})();
export const analyzeDeviationWithValidation = __aivicBundle_42_analyzeDeviationWithValidation.analyzeDeviationWithValidation;
/* AIVIC_FUNCTION_BUNDLE_END owner=analyzeDeviationWithValidation */

