    const absWeather = Math.abs(weatherCorrelation);
    const absEvent = Math.abs(eventCorrelation);
    const absCompetitor = Math.abs(competitorCorrelation);
    const totalAbs = absWeather + absEvent + absCompetitor || 1;
  
    const weatherImpact = (absWeather / totalAbs) * 100;
