    let familySegment: string;
    switch (familyStructure) {
      case 'single':
        familySegment = 'single_household';
        break;
      case 'couple':
        familySegment = 'couple';
        break;
      case 'parent_child':
        familySegment = 'family_with_children';
        break;
      case 'multi_generation':
        familySegment = 'extended_family';
        break;
      default:
        familySegment = 'single_household';
    }
  
    // Determine dietary restriction segment
    let restrictionSegment: string;
    switch (dietaryRestrictions) {
      case 'none':
        restrictionSegment = 'unrestricted';
        break;
      case 'allergy':
        restrictionSegment = 'allergy_aware';
        break;
      case 'religious':
        restrictionSegment = 'religious_restriction';
        break;
      case 'other':
        restrictionSegment = 'other_restriction';
        break;
      default:
        restrictionSegment = 'unrestricted';
    }
  
    // Combine segments in format: age_family_restriction
    const segment = `${ageSegment}_${familySegment}_${restrictionSegment}`;
  
    return {
      userId,
      segment,
    };
