/* AIVIC_FUNCTION_BUNDLE_START owner=aggregateFunctionUsagePatterns exports=aggregateFunctionUsagePatterns */
const __aivicBundle_50_aggregateFunctionUsagePatterns = (() => {
  interface AggregateFunctionUsagePatternsInput {
    functionUsageLogs: Array<{
      functionId?: string;
      functionName?: string;
      usageCount?: number;
      sessionDurationSeconds?: number;
      churnUserCount?: number;
      totalUserCount?: number;
      uniqueSessionCount?: number;
      userId?: string;
      featureName?: string;
      timestamp?: number;
      actionType?: 'enter' | 'exit' | 'complete';
      duration?: number;
      sessionId?: string;
    }>;
    aggregationWeekStartDate: Date;
    aggregationWeekEndDate: Date;
  }
  
  interface AggregateFunctionUsagePatternsMetric {
    functionId?: string;
    functionName?: string;
    usageFrequency: number;
    churnRate: number;
    differentiationScore: number;
    averageSessionDurationSeconds: number;
    totalSessions?: number;
    avgDurationSeconds?: number;
    completionRate?: number;
    exitRate?: number;
    exitReasons?: Array<{ reason: string; frequency: number }>;
  }
  
  interface AggregateFunctionUsagePatternsResult {
    functionMetrics: AggregateFunctionUsagePatternsMetric[];
    dashboardFormat: {
      weekStartDate: string;
      weekEndDate: string;
      totalFunctionsAnalyzed: number;
      totalUsageSessions: number;
      functionRankings: Array<{
        functionId?: string;
        functionName?: string;
        usageFrequency: number;
        churnRatePercent: number;
        differentiationScore: number;
        averageSessionDurationSeconds: number;
      }>;
      errors?: undefined;
      warnings?: undefined;
    };
    aggregationStatus: 'completed' | 'failed';
    processedFunctionCount: number;
    failedFunctionCount: number;
    aggregationCompletedAt: string;
  }
  
   function aggregateFunctionUsagePatterns(
    input: AggregateFunctionUsagePatternsInput
  ): AggregateFunctionUsagePatternsResult {
    const {
      functionUsageLogs,
      aggregationWeekStartDate,
      aggregationWeekEndDate,
    } = input;
  
    const weekStartStr = aggregationWeekStartDate.toISOString().split('T')[0];
    const weekEndStr = aggregationWeekEndDate.toISOString().split('T')[0];
  
    const metricsMap = new Map<
      string,
      {
        functionId: string;
        functionName: string;
        usageCount: number;
        sessionDurationSeconds: number;
        churnUserCount: number;
        totalUserCount: number;
        uniqueSessionCount: number;
      }
    >();
  
    for (const log of functionUsageLogs) {
      const funcId = log.functionId || log.featureName || 'unknown';
      const funcName = log.functionName || log.featureName || funcId;
  
      if (!metricsMap.has(funcId)) {
        metricsMap.set(funcId, {
          functionId: funcId,
          functionName: funcName,
          usageCount: log.usageCount || 0,
          sessionDurationSeconds: log.sessionDurationSeconds || 0,
          churnUserCount: log.churnUserCount || 0,
          totalUserCount: log.totalUserCount || 1,
          uniqueSessionCount: log.uniqueSessionCount || 1,
        });
      }
    }
  
    let totalUsageSessions = 0;
    const functionMetrics: AggregateFunctionUsagePatternsMetric[] = [];
  
    for (const [, logData] of metricsMap) {
      const usageFrequency = logData.usageCount;
      const churnRate = logData.churnUserCount;
      
      const uniqueSessionCount = logData.uniqueSessionCount;
      const sessionDurationSeconds = logData.sessionDurationSeconds;
  
      totalUsageSessions += usageFrequency;
  
      const avgSessionDuration =
        uniqueSessionCount > 0
          ? Math.round(sessionDurationSeconds / uniqueSessionCount)
          : 0;
  
      const metric: AggregateFunctionUsagePatternsMetric = {
        functionId: logData.functionId,
        functionName: logData.functionName,
        usageFrequency,
        churnRate,
        differentiationScore: 0,
        averageSessionDurationSeconds: avgSessionDuration,
      };
  
      functionMetrics.push(metric);
    }
  
    for (const metric of functionMetrics) {
      const differentiationScore =
        totalUsageSessions > 0
          ? (metric.usageFrequency / totalUsageSessions) *
            (100 - metric.churnRate) *
            10
          : 0;
      metric.differentiationScore = differentiationScore;
    }
  
    const functionRankings = functionMetrics.map((m) => ({
      functionId: m.functionId,
      functionName: m.functionName,
      usageFrequency: m.usageFrequency,
      churnRatePercent: m.churnRate,
      differentiationScore: m.differentiationScore,
      averageSessionDurationSeconds: m.averageSessionDurationSeconds,
    }));
  
    const result: AggregateFunctionUsagePatternsResult = {
      functionMetrics,
      dashboardFormat: {
        weekStartDate: weekStartStr,
        weekEndDate: weekEndStr,
        totalFunctionsAnalyzed: metricsMap.size,
        totalUsageSessions,
        functionRankings,
      },
      aggregationStatus: 'completed',
      processedFunctionCount: metricsMap.size,
      failedFunctionCount: 0,
      aggregationCompletedAt: new Date().toISOString(),
    };
  
    return result;
  }
  return { aggregateFunctionUsagePatterns };
})();
export const aggregateFunctionUsagePatterns = __aivicBundle_50_aggregateFunctionUsagePatterns.aggregateFunctionUsagePatterns;
/* AIVIC_FUNCTION_BUNDLE_END owner=aggregateFunctionUsagePatterns */

