const __aivicBundle_51_aggregateFunctionUsageMetrics = (() => {
  interface AggregatedMetricsItem {
    function_id: string;
    function_name: string;
    function_category: string;
    usage_frequency: number;
    total_session_duration_seconds: number;
    average_session_duration_seconds: number;
    unique_user_count: number;
  }
  
  interface ChartDataItem {
    [key: string]: any;
  }
  
  interface TableDataItem {
    [key: string]: any;
  }
  
  interface DatabaseRecord {
    weekly_aggregation_id: string;
    function_id: string;
    function_name: string;
    week_start_date: Date;
    week_end_date: Date;
    usage_frequency_count: number;
    total_duration_seconds: number;
    average_duration_seconds: number;
    unique_user_count: number;
    aggregation_timestamp: string;
  }
  
  interface Metadata {
    total_functions_analyzed: number;
    functions_with_zero_usage: number;
    functions_with_usage: number;
    aggregation_period_start: Date;
    aggregation_period_end: Date;
  }
  
  interface AggregationResult {
    aggregated_metrics: AggregatedMetricsItem[];
    dashboard_display: {
      chart_data: ChartDataItem[];
      table_data: TableDataItem[];
    };
    database_records: DatabaseRecord[];
    metadata: Metadata;
  }
  
   function aggregateFunctionUsageMetrics(input: {
    functions: Array<{
      function_id: string;
      function_name: string;
      function_category: string;
    }>;
    usage_logs: Array<{
      usage_log_id: string;
      function_id: string;
      user_id: string;
      usage_timestamp: Date;
      session_duration_seconds: number;
    }>;
    week_start_date: Date;
    week_end_date: Date;
  }): AggregationResult {
    const { functions, usage_logs, week_start_date, week_end_date } = input;
  
    const metricsMap = new Map<
      string,
      {
        function_id: string;
        function_name: string;
        function_category: string;
        usage_frequency: number;
        total_session_duration_seconds: number;
        unique_users: Set<string>;
      }
    >();
  
    for (const func of functions) {
      metricsMap.set(func.function_id, {
        function_id: func.function_id,
        function_name: func.function_name,
        function_category: func.function_category,
        usage_frequency: 0,
        total_session_duration_seconds: 0,
        unique_users: new Set<string>(),
      });
    }
  
    for (const log of usage_logs) {
      const existing = metricsMap.get(log.function_id);
      if (existing) {
        existing.usage_frequency += 1;
        existing.total_session_duration_seconds += log.session_duration_seconds;
        existing.unique_users.add(log.user_id);
      }
    }
  
    const aggregated_metrics: AggregatedMetricsItem[] = [];
    const chart_data: ChartDataItem[] = [];
    const table_data: TableDataItem[] = [];
    const database_records: DatabaseRecord[] = [];
  
    let functions_with_zero_usage = 0;
    let functions_with_usage = 0;
  
    for (const [, metrics] of metricsMap) {
      const average_session_duration_seconds =
        metrics.usage_frequency > 0
          ? metrics.total_session_duration_seconds / metrics.usage_frequency
          : 0;
  
      const unique_user_count = metrics.unique_users.size;
  
      const aggregatedItem: AggregatedMetricsItem = {
        function_id: metrics.function_id,
        function_name: metrics.function_name,
        function_category: metrics.function_category,
        usage_frequency: metrics.usage_frequency,
        total_session_duration_seconds: metrics.total_session_duration_seconds,
        average_session_duration_seconds,
        unique_user_count,
      };
  
      aggregated_metrics.push(aggregatedItem);
  
      const chartColor =
        metrics.usage_frequency === 0 ? '#CCCCCC' : '#4A90E2';
  
      chart_data.push({
        function_id: metrics.function_id,
        function_name: metrics.function_name,
        display_name: metrics.function_name,
        usage_frequency: metrics.usage_frequency,
        usage_frequency_display: metrics.usage_frequency,
        average_session_duration_seconds,
        chart_color: chartColor,
      });
  
      const durationDisplay =
        average_session_duration_seconds === 0
          ? '0分'
          : `${Math.round(average_session_duration_seconds / 60)}分`;
  
      const userDisplay = `${unique_user_count}人`;
  
      table_data.push({
        function_id: metrics.function_id,
        function_name: metrics.function_name,
        usage_frequency: metrics.usage_frequency,
        total_session_duration_seconds: metrics.total_session_duration_seconds,
        average_session_duration_seconds,
        average_session_duration_display: durationDisplay,
        unique_user_count,
        unique_user_display: userDisplay,
      });
  
      const dbRecord: DatabaseRecord = {
        weekly_aggregation_id: randomUUID(),
        function_id: metrics.function_id,
        function_name: metrics.function_name,
        week_start_date,
        week_end_date,
        usage_frequency_count: metrics.usage_frequency,
        total_duration_seconds: metrics.total_session_duration_seconds,
        average_duration_seconds: average_session_duration_seconds,
        unique_user_count,
        aggregation_timestamp: new Date().toISOString(),
      };
  
      database_records.push(dbRecord);
  
      if (metrics.usage_frequency === 0) {
        functions_with_zero_usage += 1;
      } else {
        functions_with_usage += 1;
      }
    }
  
    const metadata: Metadata = {
      total_functions_analyzed: functions.length,
      functions_with_zero_usage,
      functions_with_usage,
      aggregation_period_start: week_start_date,
      aggregation_period_end: week_end_date,
    };
  
    return {
      aggregated_metrics,
      dashboard_display: {
        chart_data,
        table_data,
      },
      database_records,
      metadata,
    };
  }
  return { aggregateFunctionUsageMetrics };
})();
