/* AIVIC_FUNCTION_BUNDLE_START owner=aggregateDisengagementMetrics exports=aggregateDisengagementMetrics */
const __aivicBundle_52_aggregateDisengagementMetrics = (() => {
  function aggregateDisengagementMetrics(
    events: Array<{ event_timestamp: Date; event_type: string }>,
    analysisStartDate: Date,
    analysisEndDate: Date
  ): {
    total_disengagement_events: number;
    disengagement_at_period_start: number;
    disengagement_at_period_end: number;
    disengagement_in_period_middle: number;
    disengagement_rate: number;
    total_events_in_period: number;
    event_count_by_boundary: {
      at_period_start: number;
      in_period_middle: number;
      at_period_end: number;
    };
    timezone_adjusted: boolean;
  } {
    const startTime = analysisStartDate.getTime();
    const endTime = analysisEndDate.getTime();
  
    const disengagementEvents = events.filter(
      (e) => e.event_type === 'disengagement'
    );
  
    const eventsInPeriod = disengagementEvents.filter((e) => {
      const eventTime = e.event_timestamp.getTime();
      return eventTime >= startTime && eventTime <= endTime;
    });
  
    const totalEventsInPeriod = eventsInPeriod.length;
    const totalDisengagementEvents = eventsInPeriod.length;
  
    const periodDuration = endTime - startTime;
    const earlyBoundaryThreshold = startTime + periodDuration * 0.05;
    const lateBoundaryThreshold = endTime - periodDuration * 0.05;
  
    let atPeriodStart = 0;
    let inPeriodMiddle = 0;
    let atPeriodEnd = 0;
  
    eventsInPeriod.forEach((e) => {
      const eventTime = e.event_timestamp.getTime();
      if (eventTime <= earlyBoundaryThreshold) {
        atPeriodStart++;
      } else if (eventTime >= lateBoundaryThreshold) {
        atPeriodEnd++;
      } else {
        inPeriodMiddle++;
      }
    });
  
    const disengagementRate =
      totalEventsInPeriod > 0 ? totalDisengagementEvents / totalEventsInPeriod : 0;
  
    return {
      total_disengagement_events: totalDisengagementEvents,
      disengagement_at_period_start: atPeriodStart,
      disengagement_at_period_end: atPeriodEnd,
      disengagement_in_period_middle: inPeriodMiddle,
      disengagement_rate: disengagementRate,
      total_events_in_period: totalEventsInPeriod,
      event_count_by_boundary: {
        at_period_start: atPeriodStart,
        in_period_middle: inPeriodMiddle,
        at_period_end: atPeriodEnd,
      },
      timezone_adjusted: true,
    };
  }
  return { aggregateDisengagementMetrics };
})();
export const aggregateDisengagementMetrics = __aivicBundle_52_aggregateDisengagementMetrics.aggregateDisengagementMetrics;
/* AIVIC_FUNCTION_BUNDLE_END owner=aggregateDisengagementMetrics */

/* AIVIC_FUNCTION_BUNDLE_START owner=aggregateMonthlyCostData exports=aggregateMonthlyCostData */
const __aivicBundle_53_aggregateMonthlyCostData = (() => {
  interface AggregateMonthlyCostDataInput {
    budget_yen: number;
    period_start: string;
    period_end: string;
    purchases: Array<{
      purchase_id?: string;
      purchase_date: string;
      amount_yen: number;
      food_category: string;
      satisfaction_score: number;
    }>;
  }
  
  interface CategoryBreakdown {
    [category: string]: {
      total_yen: number;
      percentage: number;
    };
  }
  
  interface CategorySatisfactionDistribution {
    [category: string]: number;
  }
  
  interface NextMonthRecommendation {
    food_category: string;
    priority: 'high' | 'medium' | 'low';
    rationale: string;
  }
  
  interface AggregateMonthlyCostDataResult {
    total_cost_yen: number;
    budget_reduction_rate_percent: number;
    category_breakdown: CategoryBreakdown;
    average_satisfaction_score: number;
    category_satisfaction_distribution: CategorySatisfactionDistribution;
    next_month_recommendations: NextMonthRecommendation[];
    aggregation_timestamp: string;
  }
  
   function aggregateMonthlyCostData(
    input: AggregateMonthlyCostDataInput
  ): AggregateMonthlyCostDataResult {
    const { budget_yen, period_start, period_end, purchases } = input;
  
    // Validate required inputs
    if (!String(period_start).trim()) {
      throw new Error('period_start is required');
    }
  
    // Calculate total cost
    const total_cost_yen = purchases.reduce(
      (sum, purchase) => sum + purchase.amount_yen,
      0
    );
  
    // Calculate budget reduction rate
    const budget_reduction_rate_percent =
      ((budget_yen - total_cost_yen) / budget_yen) * 100;
  
    // Build category breakdown with satisfaction tracking
    const categoryMap: Record<
      string,
      { total_yen: number; scores: number[] }
    > = {};
  
    for (const purchase of purchases) {
      const category = purchase.food_category;
      if (!categoryMap[category]) {
        categoryMap[category] = { total_yen: 0, scores: [] };
      }
      categoryMap[category].total_yen += purchase.amount_yen;
      categoryMap[category].scores.push(purchase.satisfaction_score);
    }
  
    // Build category_breakdown with percentages
    const category_breakdown: CategoryBreakdown = {};
    for (const [category, data] of Object.entries(categoryMap)) {
      const percentage = parseFloat(
        ((data.total_yen / total_cost_yen) * 100).toFixed(1)
      );
      category_breakdown[category] = {
        total_yen: data.total_yen,
        percentage,
      };
    }
  
    // Calculate average satisfaction score
    const all_scores = purchases.map((p) => p.satisfaction_score);
    const average_satisfaction_score = parseFloat(
      (all_scores.reduce((sum, score) => sum + score, 0) / all_scores.length).toFixed(2)
    );
  
    // Build category satisfaction distribution
    const category_satisfaction_distribution: CategorySatisfactionDistribution = {};
    for (const [category, data] of Object.entries(categoryMap)) {
      const avg_score = parseFloat(
        (data.scores.reduce((sum, score) => sum + score, 0) / data.scores.length).toFixed(2)
      );
      category_satisfaction_distribution[category] = avg_score;
    }
  
    // Generate next month recommendations based on satisfaction and cost efficiency
    const next_month_recommendations: NextMonthRecommendation[] = [];
  
    // Sort categories by satisfaction score (descending)
    const sorted_categories = Object.entries(category_satisfaction_distribution)
      .sort(([, scoreA], [, scoreB]) => scoreB - scoreA);
  
    for (let i = 0; i < sorted_categories.length; i++) {
      const [category, satisfaction_score] = sorted_categories[i];
  
      let priority: 'high' | 'medium' | 'low';
      let rationale: string;
  
      if (i === 0) {
        // Highest satisfaction category
        priority = 'high';
        rationale = `高満足度（${satisfaction_score}点）かつ低コスト効率の${category}を次月優先`;
      } else if (i === sorted_categories.length - 1) {
        // Lowest satisfaction category
        priority = 'low';
        rationale = `満足度が低い（${satisfaction_score}点）${category}は削減検討`;
      } else {
        priority = 'medium';
        rationale = `${category}は中程度の満足度（${satisfaction_score}点）`;
      }
  
      next_month_recommendations.push({
        food_category: category,
        priority,
        rationale,
      });
    }
  
    // Use period_end as aggregation timestamp
    const aggregation_timestamp = period_end;
  
    return {
      total_cost_yen,
      budget_reduction_rate_percent,
      category_breakdown,
      average_satisfaction_score,
      category_satisfaction_distribution,
      next_month_recommendations,
      aggregation_timestamp,
    };
  }
  return { aggregateMonthlyCostData };
})();
export const aggregateMonthlyCostData = __aivicBundle_53_aggregateMonthlyCostData.aggregateMonthlyCostData;
/* AIVIC_FUNCTION_BUNDLE_END owner=aggregateMonthlyCostData */

/* AIVIC_FUNCTION_BUNDLE_START owner=aggregateMonthlyCostAndProposePriority exports=aggregateMonthlyCostAndProposePriority */
const __aivicBundle_54_aggregateMonthlyCostAndProposePriority = (() => {
  function aggregateMonthlyCostAndProposePriority(input: {
    userId: string;
    targetMonth: string;
    monthlyBudget: number;
    purchaseRecords: Array<{
      purchaseId?: string;
      userId?: string;
      purchaseDate: string;
      amount?: number;
      purchaseAmount?: number;
      foodItemId?: string;
      foodItemName?: string;
      quantity?: number;
      storeName?: string;
      satisfactionScore?: number;
    }>;
  }): {
    actualExpense: number;
    budgetRemaining: number;
    excessAmount: number;
    proposedPriorities: Array<{
      priorityType: string;
      reason: string;
      estimatedImpact: string;
    }>;
    nextMonthBudgetAdjustment: number;
    recommendedCostReductionCategories: string[];
  } {
    if (!String(input.userId).trim()) {
      throw new Error("userId is required");
    }
    if (!String(input.targetMonth).trim()) {
      throw new Error("targetMonth is required");
    }
  
    const { monthlyBudget, purchaseRecords } = input;
  
    const actualExpense = purchaseRecords.reduce((sum, record) => {
      const amount = record.amount ?? record.purchaseAmount ?? 0;
      return sum + amount;
    }, 0);
  
    const excessAmount = Math.max(0, actualExpense - monthlyBudget);
    const budgetRemaining = Math.max(0, monthlyBudget - actualExpense);
    const budgetRatio = monthlyBudget > 0 ? actualExpense / monthlyBudget : 0;
  
    const proposedPriorities: Array<{
      priorityType: string;
      reason: string;
      estimatedImpact: string;
    }> = [];
  
    if (budgetRemaining > monthlyBudget * 0.2) {
      proposedPriorities.push({
        priorityType: "OPTIMIZE_NUTRITION",
        reason: "予算に十分な余裕があり、栄養バランス最適化を優先",
        estimatedImpact: "HIGH",
      });
      proposedPriorities.push({
        priorityType: "SEASONAL_INGREDIENT",
        reason: "旬の食材導入により食費効率化と満足度向上を同時達成",
        estimatedImpact: "MEDIUM",
      });
      proposedPriorities.push({
        priorityType: "FAMILY_PREFERENCE",
        reason: "家族の嗜好学習継続による満足度維持",
        estimatedImpact: "MEDIUM",
      });
    } else if (excessAmount > 0) {
      proposedPriorities.push({
        priorityType: "COST_REDUCTION",
        reason: "予算超過を解消するため、食費削減を優先",
        estimatedImpact: "HIGH",
      });
      proposedPriorities.push({
        priorityType: "ALTERNATIVE_INGREDIENTS",
        reason: "代替食材の活用により同等の満足度を維持しながら削減",
        estimatedImpact: "MEDIUM",
      });
    } else {
      proposedPriorities.push({
        priorityType: "BALANCED_OPTIMIZATION",
        reason: "予算内で栄養と満足度のバランス最適化を優先",
        estimatedImpact: "HIGH",
      });
      proposedPriorities.push({
        priorityType: "SEASONAL_INGREDIENT",
        reason: "旬の食材導入により食費効率化と満足度向上を同時達成",
        estimatedImpact: "MEDIUM",
      });
    }
  
    const recommendedCostReductionCategories: string[] = [];
    if (excessAmount > 0 && budgetRatio > 1) {
      const categoryTotals: Record<string, number> = {};
      purchaseRecords.forEach((record) => {
        const foodItemName = record.foodItemName ?? "unknown";
        categoryTotals[foodItemName] = (categoryTotals[foodItemName] ?? 0) + (record.amount ?? record.purchaseAmount ?? 0);
      });
  
      const sortedCategories = Object.entries(categoryTotals)
        .sort(([, a], [, b]) => b - a)
        .slice(0, 3)
        .map(([category]) => category);
  
      recommendedCostReductionCategories.push(...sortedCategories);
    }
  
    const nextMonthBudgetAdjustment = excessAmount > 0 ? Math.ceil(excessAmount * 1.1) : 0;
  
    return {
      actualExpense,
      budgetRemaining,
      excessAmount,
      proposedPriorities,
      nextMonthBudgetAdjustment,
      recommendedCostReductionCategories,
    };
  }
  return { aggregateMonthlyCostAndProposePriority };
})();
export const aggregateMonthlyCostAndProposePriority = __aivicBundle_54_aggregateMonthlyCostAndProposePriority.aggregateMonthlyCostAndProposePriority;
