/* AIVIC_FUNCTION_BUNDLE_START owner=aggregateMonthlyFoodExpenseAndProposePriorities exports=aggregateMonthlyFoodExpenseAndProposePriorities */
const __aivicBundle_55_aggregateMonthlyFoodExpenseAndProposePriorities = (() => {
  function aggregateMonthlyFoodExpenseAndProposePriorities(input: any): any {
    const { monthlyFoodExpenseRecords = [], mealEvaluationRecords = [], priorityCriteria = {
        budgetOptimizationWeight: 0.3,
        nutritionBalanceWeight: 0.4,
        userSatisfactionWeight: 0.3,
        defaultSatisfactionScore: 3.0,
      } } = input;
  
    // Calculate monthly expense summary
    const totalAmount = monthlyFoodExpenseRecords.reduce(
      (sum: number, record: any) => sum + (record.totalAmount || 0),
      0
    );
    const budgetAmount = monthlyFoodExpenseRecords.reduce(
      (sum: number, record: any) => sum + (record.budgetAmount || 0),
      0
    );
    const budgetSurplusOrDeficit = budgetAmount - totalAmount;
    const budgetSurplusRatePercent =
      budgetAmount > 0 ? (budgetSurplusOrDeficit / budgetAmount) * 100 : 0;
  
    // Process meal evaluation records
    let totalSatisfactionScore = 0;
    let recordsWithNullSatisfaction = 0;
    const recordsProcessed = mealEvaluationRecords.length;
  
    mealEvaluationRecords.forEach((record: any) => {
      if (record.satisfactionScore === null || record.satisfactionScore === undefined) {
        recordsWithNullSatisfaction += 1;
        totalSatisfactionScore += priorityCriteria.defaultSatisfactionScore;
      } else {
        totalSatisfactionScore += record.satisfactionScore;
      }
    });
  
    const aggregatedSatisfactionScore =
      recordsProcessed > 0 ? totalSatisfactionScore / recordsProcessed : 0;
  
    // Generate priority conditions
    const nextMonthPriorityConditions: any[] = [];
  
    // Budget optimization priority
    const budgetOptimizationScore =
      budgetSurplusOrDeficit < 0
        ? 100 - Math.min(Math.abs(budgetSurplusOrDeficit) / budgetAmount, 1) * 100
        : Math.min((budgetSurplusOrDeficit / budgetAmount) * 100, 100);
  
    nextMonthPriorityConditions.push({
      priorityType: 'budget_optimization',
      priorityScore: Math.max(0, Math.min(100, budgetOptimizationScore)),
      recommendedAction: budgetSurplusOrDeficit < 0 ? '予算超過を削減' : '予算内で最適化',
    });
  
    // Nutrition balance priority
    const nutritionBalanceScore = Math.min(
      100,
      (aggregatedSatisfactionScore / 5) * 100
    );
  
    nextMonthPriorityConditions.push({
      priorityType: 'nutrition_balance',
      priorityScore: Math.max(0, Math.min(100, nutritionBalanceScore)),
      recommendedAction: '栄養バランスの改善',
    });
  
    // User satisfaction priority
    const userSatisfactionScore = (aggregatedSatisfactionScore / 5) * 100;
  
    nextMonthPriorityConditions.push({
      priorityType: 'user_satisfaction',
      priorityScore: Math.max(0, Math.min(100, userSatisfactionScore)),
      recommendedAction: '満足度向上を優先',
    });
  
    return {
      monthlyExpenseSummary: {
        totalAmount,
        budgetAmount,
        budgetSurplusOrDeficit,
        budgetSurplusRatePercent,
      },
      evaluationDataProcessing: {
        totalRecords: recordsProcessed,
        recordsWithNullSatisfaction,
        recordsProcessed,
        processingMethod: recordsWithNullSatisfaction > 0 ? 'default_value_applied' : 'normal',
      },
      aggregatedSatisfactionScore,
      nextMonthPriorityConditions,
      processStatus: 'success',
      errorOccurred: false,
      errorMessage: undefined,
    };
  }
  return { aggregateMonthlyFoodExpenseAndProposePriorities };
})();
export const aggregateMonthlyFoodExpenseAndProposePriorities = __aivicBundle_55_aggregateMonthlyFoodExpenseAndProposePriorities.aggregateMonthlyFoodExpenseAndProposePriorities;
/* AIVIC_FUNCTION_BUNDLE_END owner=aggregateMonthlyFoodExpenseAndProposePriorities */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculateMonthlyFoodExpenseSummary exports=calculateMonthlyFoodExpenseSummary */
const __aivicBundle_56_calculateMonthlyFoodExpenseSummary = (() => {
  function calculateMonthlyFoodExpenseSummary(input: {
    userId: string;
    year: number;
    month: number;
    budgetAmount: number;
    actualAmount: number;
  }): {
    actualExpense: number;
    budgetAmount: number;
    totalExpenseAmount?: number;
    budgetRatio?: number;
    reductionRate?: number;
    averageSatisfactionScore?: number;
    foodItemCostAnalysis?: Array<{
      foodItemName: string;
      totalCost: number;
      purchaseCount: number;
      averageUnitPrice: number;
      contributionRatio: number;
    }>;
  } {
    // Validate required inputs
    if (input.userId === undefined || input.userId === null || String(input.userId).trim() === "") {
      throw new Error("userId is required");
    }
    if (input.year === undefined || input.year === null || String(input.year).trim() === "") {
      throw new Error("year is required");
    }
    if (input.month === undefined || input.month === null || String(input.month).trim() === "") {
      throw new Error("month is required");
    }
  
    const actualExpense = input.actualAmount;
    const budgetAmount = input.budgetAmount;
  
    const budgetRatio = budgetAmount > 0 ? actualExpense / budgetAmount : 0;
    const reductionRate = budgetAmount > 0 ? (budgetAmount - actualExpense) / budgetAmount : 0;
  
    return {
      actualExpense: actualExpense,
      budgetAmount: budgetAmount,
      totalExpenseAmount: actualExpense,
      budgetRatio: budgetRatio,
      reductionRate: reductionRate,
      averageSatisfactionScore: 0,
      foodItemCostAnalysis: [],
    };
  }
  return { calculateMonthlyFoodExpenseSummary };
})();
export const calculateMonthlyFoodExpenseSummary = __aivicBundle_56_calculateMonthlyFoodExpenseSummary.calculateMonthlyFoodExpenseSummary;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateMonthlyFoodExpenseSummary */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculateReductionRate exports=calculateReductionRate */
const __aivicBundle_57_calculateReductionRate = (() => {
  interface CalculateReductionRateInput {
    actualExpense: number;
    budgetAmount: number;
  }
  
   function calculateReductionRate(input: CalculateReductionRateInput): number {
    const { actualExpense, budgetAmount } = input;
    
    if (budgetAmount === 0) {
      return 0;
    }
    
    const reductionRate = (budgetAmount - actualExpense) / budgetAmount;
    return reductionRate;
  }
  return { calculateReductionRate };
})();
export const calculateReductionRate = __aivicBundle_57_calculateReductionRate.calculateReductionRate;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateReductionRate */

/* AIVIC_FUNCTION_BUNDLE_START owner=generateNextMonthPriorityProposal exports=generateNextMonthPriorityProposal */
const __aivicBundle_58_generateNextMonthPriorityProposal = (() => {
  interface GenerateNextMonthPriorityProposalInput {
    userId: string;
    currentReductionRate: number;
    currentBudgetAmount: number;
    currentActualExpense: number;
  }
  
  interface GenerateNextMonthPriorityProposalResult {
    proposalType: string;
    recommendedAction: string;
    excessAmount: number;
    reductionRatePercentage: number;
    suggestedReductionTarget: number;
    priority: string;
  }
  
   function generateNextMonthPriorityProposal(
    input: GenerateNextMonthPriorityProposalInput
  ): GenerateNextMonthPriorityProposalResult {
    if (!String(input.userId).trim()) {
      throw new Error('userId is required');
    }
  
    const { currentReductionRate, currentBudgetAmount, currentActualExpense } = input;
  
    const excessAmount = currentActualExpense - currentBudgetAmount;
    const isOverBudget = excessAmount > 0;
    const reductionRatePercentage = Math.round(currentReductionRate * 100);
  
    let proposalType: string;
    let recommendedAction: string;
    let priority: string;
  
    if (isOverBudget) {
      proposalType = 'budget_exceeded';
      recommendedAction = 'cost_reduction_required';
      priority = 'high';
    } else {
      proposalType = 'budget_within_limit';
      recommendedAction = 'maintain_current_spending';
      priority = 'low';
    }
  
    const suggestedReductionTarget = isOverBudget ? excessAmount : 0;
  
    return {
      proposalType,
      recommendedAction,
      excessAmount,
      reductionRatePercentage,
      suggestedReductionTarget,
      priority,
    };
  }
  return { generateNextMonthPriorityProposal };
})();
export const generateNextMonthPriorityProposal = __aivicBundle_58_generateNextMonthPriorityProposal.generateNextMonthPriorityProposal;
/* AIVIC_FUNCTION_BUNDLE_END owner=generateNextMonthPriorityProposal */

/* AIVIC_FUNCTION_BUNDLE_START owner=validateAlgorithmImprovementThresholds exports=validateAlgorithmImprovementThresholds */
const __aivicBundle_59_validateAlgorithmImprovementThresholds = (() => {
  function validateAlgorithmImprovementThresholds(input: any): any {
    const proposal = input;
    
    const baselineSuccessRate = proposal.baseline_metrics?.success_rate ?? 0;
    const improvedSuccessRate = proposal.improved_metrics?.success_rate ?? 0;
    const successRateImprovement = proposal.improvement_details?.success_rate_improvement ?? 
      (improvedSuccessRate - baselineSuccessRate);
    
    const baselineSatisfactionScore = proposal.baseline_metrics?.satisfaction_score ?? 0;
    const improvedSatisfactionScore = proposal.improved_metrics?.satisfaction_score ?? 0;
    const satisfactionScoreImprovement = proposal.improvement_details?.satisfaction_score_improvement ?? 
      (improvedSatisfactionScore - baselineSatisfactionScore);
    
    const successRateThreshold = 5;
    const satisfactionThreshold = 0.5;
    
    const meetsSuccessRateThreshold = successRateImprovement >= successRateThreshold;
    const meetsSatisfactionThreshold = satisfactionScoreImprovement >= satisfactionThreshold;
    
    const failureReasons: string[] = [];
    
    if (!meetsSuccessRateThreshold) {
      failureReasons.push(`成功率向上が基準に達していない（${successRateImprovement}% < ${successRateThreshold}%）`);
    }
    
    if (!meetsSatisfactionThreshold) {
      failureReasons.push(`満足度向上が基準に達していない（${satisfactionScoreImprovement}ポイント < ${satisfactionThreshold}ポイント）`);
    }
    
    const canDeployToProduction = meetsSuccessRateThreshold && meetsSatisfactionThreshold;
    
    let recommendedAction: 'approve' | 'conditional_approve' | 'reject' | 'retest' = 'reject';
    if (canDeployToProduction) {
      recommendedAction = 'approve';
    } else if (failureReasons.length === 1) {
      recommendedAction = 'conditional_approve';
    } else {
      recommendedAction = 'reject';
    }
    
    const statisticalSignificance = Math.min(
      meetsSuccessRateThreshold ? 0.95 : 0.5,
      meetsSatisfactionThreshold ? 0.95 : 0.5
    );
    
    const judgmentReason = `アルゴリズム改善の検証結果：成功率${successRateImprovement}%向上、満足度${satisfactionScoreImprovement}ポイント向上。${
      canDeployToProduction 
        ? '全ての基準を満たし、本番反映を推奨します。' 
        : '一部の基準を満たしていません。'
    }`;
    
    return {
      can_deploy_to_production: canDeployToProduction,
      success_rate_improvement_pct: successRateImprovement,
      satisfaction_score_improvement_points: satisfactionScoreImprovement,
      meets_success_rate_threshold: meetsSuccessRateThreshold,
      meets_satisfaction_threshold: meetsSatisfactionThreshold,
      judgment_reason: judgmentReason,
      isApproved: canDeployToProduction,
      successRateImprovement: successRateImprovement,
      satisfactionScoreImprovement: satisfactionScoreImprovement,
      cookingTimeReductionImprovement: 0,
      failureReasons: failureReasons,
      recommendedAction: recommendedAction,
      statisticalSignificance: statisticalSignificance
    };
  }
  return { validateAlgorithmImprovementThresholds };
})();
export const validateAlgorithmImprovementThresholds = __aivicBundle_59_validateAlgorithmImprovementThresholds.validateAlgorithmImprovementThresholds;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateAlgorithmImprovementThresholds */

/* AIVIC_FUNCTION_BUNDLE_START owner=judgePrecisionImprovementViability exports=judgePrecisionImprovementViability */
const __aivicBundle_60_judgePrecisionImprovementViability = (() => {
  function judgePrecisionImprovementViability(input: any): any {
    const current_success_rate = input.current_success_rate ?? 0;
    const new_success_rate = input.new_success_rate ?? 0;
    const threshold_percentage = input.threshold_percentage ?? 0;
  
    const improvement_rate = new_success_rate - current_success_rate;
    const is_viable = improvement_rate >= threshold_percentage;
  
    const reason = is_viable
      ? `改善率${improvement_rate}%が閾値${threshold_percentage}%以上を達成`
      : `改善率${improvement_rate}%が閾値${threshold_percentage}%に満たない`;
  
    return {
      viable_for_production: is_viable,
      reason: reason,
    };
  }
  return { judgePrecisionImprovementViability };
})();
export const judgePrecisionImprovementViability = __aivicBundle_60_judgePrecisionImprovementViability.judgePrecisionImprovementViability;
