/* AIVIC_FUNCTION_BUNDLE_START owner=compareAlgorithmPerformance exports=compareAlgorithmPerformance */
const __aivicBundle_61_compareAlgorithmPerformance = (() => {
  interface CompareAlgorithmPerformanceInput {
    algorithmVersion?: string;
    generationSuccessRate?: number;
    cookingTimeReductionDegree?: number;
    userSatisfactionScore?: number;
    evaluationTimestamp?: string;
  }
  
  interface CompareAlgorithmPerformanceErrorResult {
    status: 400;
    error: string;
    details: {
      incompleteDataset?: 'before' | 'after';
      missingFields?: string[];
    };
  }
  
  interface CompareAlgorithmPerformanceSuccessResult {
    status: 200;
    successRateImprovement: number;
    satisfactionScoreImprovement: number;
    cookingTimeReductionImprovement: number;
    statisticalSignificance: number;
    isStatisticallySignificant: boolean;
    effectSize: string;
    recommendedAction: string;
  }
  
  type CompareAlgorithmPerformanceResult =
    | CompareAlgorithmPerformanceErrorResult
    | CompareAlgorithmPerformanceSuccessResult;
  
  function validateMetricsInput(
    data: any,
    datasetName: 'before' | 'after'
  ): { isValid: boolean; missingFields: string[] } {
    if (data === null || data === undefined || typeof data !== 'object') {
      return {
        isValid: false,
        missingFields: [
          'algorithmVersion',
          'generationSuccessRate',
          'cookingTimeReductionDegree',
          'userSatisfactionScore',
          'evaluationTimestamp',
        ],
      };
    }
  
    const requiredFields = [
      'algorithmVersion',
      'generationSuccessRate',
      'cookingTimeReductionDegree',
      'userSatisfactionScore',
      'evaluationTimestamp',
    ];
  
    const missingFields = requiredFields.filter(
      (field) => !(field in data) || data[field] === undefined
    );
  
    return {
      isValid: missingFields.length === 0,
      missingFields,
    };
  }
  
  function calculateEffectSize(
    successRateImprovement: number,
    satisfactionImprovement: number,
    cookingTimeImprovement: number
  ): string {
    const avgImprovement =
      (Math.abs(successRateImprovement) +
        Math.abs(satisfactionImprovement) +
        Math.abs(cookingTimeImprovement)) /
      3;
  
    if (avgImprovement >= 0.5) {
      return 'large';
    } else if (avgImprovement >= 0.2) {
      return 'medium';
    } else {
      return 'small';
    }
  }
  
  function calculateStatisticalSignificance(
    beforeMetrics: CompareAlgorithmPerformanceInput,
    afterMetrics: CompareAlgorithmPerformanceInput,
    sampleSize: number = 100
  ): number {
    const successRateDiff = Math.abs(
      (afterMetrics.generationSuccessRate || 0) -
        (beforeMetrics.generationSuccessRate || 0)
    );
    const satisfactionDiff = Math.abs(
      (afterMetrics.userSatisfactionScore || 0) -
        (beforeMetrics.userSatisfactionScore || 0)
    );
    const cookingTimeDiff = Math.abs(
      (afterMetrics.cookingTimeReductionDegree || 0) -
        (beforeMetrics.cookingTimeReductionDegree || 0)
    );
  
    const pooledVariance =
      (successRateDiff * successRateDiff +
        satisfactionDiff * satisfactionDiff +
        cookingTimeDiff * cookingTimeDiff) /
      3;
  
    const standardError = Math.sqrt(pooledVariance / sampleSize);
    const tStatistic =
      standardError > 0
        ? (successRateDiff + satisfactionDiff + cookingTimeDiff) /
          (3 * standardError)
        : 0;
  
    const pValue = 2 * (1 - normalCDF(Math.abs(tStatistic)));
  
    return pValue;
  }
  
  function normalCDF(z: number): number {
    const a1 = 0.254829592;
    const a2 = -0.284496736;
    const a3 = 1.421413741;
    const a4 = -1.453152027;
    const a5 = 1.061405429;
    const p = 0.3275911;
  
    const sign = z < 0 ? -1 : 1;
    z = Math.abs(z) / Math.sqrt(2);
  
    const t = 1.0 / (1.0 + p * z);
    const y =
      1.0 -
      (((((a5 * t + a4) * t + a3) * t + a2) * t + a1) * t * Math.exp(-z * z));
  
    return 0.5 * (1.0 + sign * y);
  }
  
   function compareAlgorithmPerformance(
    baselineMetrics: any,
    improvedMetrics: any,
    testSampleSize: number = 100
  ): CompareAlgorithmPerformanceResult {
    const beforeValidation = validateMetricsInput(baselineMetrics, 'before');
    const afterValidation = validateMetricsInput(improvedMetrics, 'after');
  
    if (!beforeValidation.isValid) {
      return {
        status: 400,
        error: `必須フィールドが不足しています: ${beforeValidation.missingFields.join(', ')}`,
        details: {
          incompleteDataset: 'before',
          missingFields: beforeValidation.missingFields,
        },
      };
    }
  
    if (!afterValidation.isValid) {
      return {
        status: 400,
        error: `必須フィールドが不足しています: ${afterValidation.missingFields.join(', ')}`,
        details: {
          incompleteDataset: 'after',
          missingFields: afterValidation.missingFields,
        },
      };
    }
  
    const successRateImprovement =
      (improvedMetrics.generationSuccessRate -
        baselineMetrics.generationSuccessRate) /
      100;
    const satisfactionScoreImprovement =
      improvedMetrics.userSatisfactionScore - baselineMetrics.userSatisfactionScore;
    const cookingTimeReductionImprovement =
      (improvedMetrics.cookingTimeReductionDegree -
        baselineMetrics.cookingTimeReductionDegree) /
      100;
  
    const pValue = calculateStatisticalSignificance(
      baselineMetrics,
      improvedMetrics,
      testSampleSize
    );
    const isStatisticallySignificant = pValue < 0.05;
  
    const effectSize = calculateEffectSize(
      successRateImprovement,
      satisfactionScoreImprovement,
      cookingTimeReductionImprovement
    );
  
    let recommendedAction = 'retest';
    if (isStatisticallySignificant && effectSize === 'large') {
      recommendedAction = 'approve';
    } else if (isStatisticallySignificant && effectSize === 'medium') {
      recommendedAction = 'conditional_approve';
    } else if (!isStatisticallySignificant && effectSize === 'small') {
      recommendedAction = 'retest';
    } else if (isStatisticallySignificant && effectSize === 'small') {
      recommendedAction = 'conditional_approve';
    }
  
    return {
      status: 200,
      successRateImprovement,
      satisfactionScoreImprovement,
      cookingTimeReductionImprovement,
      statisticalSignificance: pValue,
      isStatisticallySignificant,
      effectSize,
      recommendedAction,
    };
  }
  return { compareAlgorithmPerformance };
})();
