/* AIVIC_FUNCTION_BUNDLE_START owner=prioritizeImprovementProposals exports=prioritizeImprovementProposals */
const __aivicBundle_62_prioritizeImprovementProposals = (() => {
  function prioritizeImprovementProposals(
    proposals: any
  ): any {
    // Handle both array of proposals and single proposal object
    const proposalArray = Array.isArray(proposals) ? proposals : [proposals];
  
    if (!proposalArray || proposalArray.length === 0) {
      return [];
    }
  
    // Determine input format and calculate priority scores
    const scoredProposals = proposalArray.map((proposal: any) => {
      let priorityScore: number;
  
      // Format 1: proposal_id, accuracy_diff_percent, implementation_cost_points, family_satisfaction_impact_score
      if (
        'proposal_id' in proposal &&
        'accuracy_diff_percent' in proposal &&
        'implementation_cost_points' in proposal &&
        'family_satisfaction_impact_score' in proposal
      ) {
        // Priority score formula: (accuracy_diff * 2.0) + (satisfaction * 5.0) - (cost * 0.3)
        priorityScore =
          proposal.accuracy_diff_percent * 2.0 +
          proposal.family_satisfaction_impact_score * 5.0 -
          proposal.implementation_cost_points * 0.3;
  
        // Determine priority rank based on score
        let priorityRank: string;
        if (priorityScore >= 50) {
          priorityRank = 'high';
        } else if (priorityScore >= 35) {
          priorityRank = 'medium';
        } else {
          priorityRank = 'low';
        }
  
        return {
          ...proposal,
          priority_score: priorityScore,
          priority_rank: priorityRank,
        };
      }
  
      // Format 2: proposal_id, effectiveness_score, feasibility_score, cost_score
      if (
        'proposal_id' in proposal &&
        'effectiveness_score' in proposal &&
        'feasibility_score' in proposal &&
        'cost_score' in proposal
      ) {
        // Weighted score: (effectiveness * 0.4) + (feasibility * 0.3) + (cost * 0.3)
        priorityScore =
          proposal.effectiveness_score * 0.4 +
          proposal.feasibility_score * 0.3 +
          proposal.cost_score * 0.3;
  
        return {
          ...proposal,
          weighted_score: priorityScore,
        };
      }
  
      return proposal;
    });
  
    // Sort by priority score (descending)
    const sortedProposals = scoredProposals.sort((a: any, b: any) => {
      const scoreA = a.priority_score ?? a.weighted_score ?? 0;
      const scoreB = b.priority_score ?? b.weighted_score ?? 0;
      return scoreB - scoreA;
    });
  
    return sortedProposals;
  }
  return { prioritizeImprovementProposals };
})();
export const prioritizeImprovementProposals = __aivicBundle_62_prioritizeImprovementProposals.prioritizeImprovementProposals;
