/* AIVIC_FUNCTION_BUNDLE_START owner=compareMultipleImprovementProposals exports=compareMultipleImprovementProposals */
const __aivicBundle_65_compareMultipleImprovementProposals = (() => {
  function compareMultipleImprovementProposals(
    improvementProposals: any[]
  ): Array<{
    proposalId: string;
    proposalName: string;
    addressedPatternCount: number;
    totalPatternCount: number;
    estimatedImpactScore: number;
    costEfficiencyScore: number;
    riskAdjustedScore: number;
    recommendedDeploymentPhase: string;
    comparisonRank: number;
  }> {
    if (!improvementProposals || improvementProposals.length === 0) {
      return [];
    }
  
    const scoredProposals = improvementProposals.map((proposal) => {
      if (proposal.implementationCost === null || proposal.implementationCost === undefined) {
        throw new Error('実装コストが定義されていない改善案があります');
      }
  
      const addressedPatternCount = proposal.addressedFailurePatterns?.length ?? 0;
      const totalPatternCount = proposal.addressedFailurePatterns?.length ?? 0;
  
      const estimatedImpactScore =
        (proposal.expectedAccuracyImprovement ?? 0) * 0.4 +
        (proposal.expectedSatisfactionLift ?? 0) * 0.6;
  
      const costEfficiencyScore =
        proposal.implementationCost > 0
          ? (estimatedImpactScore / proposal.implementationCost) * 100
          : 0;
  
      const riskMultiplier =
        proposal.implementationRiskLevel === 'high'
          ? 0.7
          : proposal.implementationRiskLevel === 'medium'
            ? 0.85
            : 1.0;
  
      const riskAdjustedScore = costEfficiencyScore * riskMultiplier;
  
      return {
        proposalId: proposal.proposalId || proposal.id || '',
        proposalName: proposal.proposalName || proposal.name || '',
        addressedPatternCount,
        totalPatternCount,
        estimatedImpactScore,
        costEfficiencyScore,
        riskAdjustedScore,
        recommendedDeploymentPhase:
          proposal.recommendedDeploymentPhase || 'next_sprint',
        _sortKey: riskAdjustedScore,
      };
    });
  
    scoredProposals.sort((a, b) => b._sortKey - a._sortKey);
  
    return scoredProposals.map((proposal, index) => {
      const { _sortKey, ...result } = proposal;
      return {
        ...result,
        comparisonRank: index + 1,
      };
    });
  }
  return { compareMultipleImprovementProposals };
})();
export const compareMultipleImprovementProposals = __aivicBundle_65_compareMultipleImprovementProposals.compareMultipleImprovementProposals;
/* AIVIC_FUNCTION_BUNDLE_END owner=compareMultipleImprovementProposals */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculateWeeklyImprovementMetrics exports=calculateWeeklyImprovementMetrics */
const __aivicBundle_66_calculateWeeklyImprovementMetrics = (() => {
  interface CalculateWeeklyImprovementMetricsInput {
    previousWeekSatisfactionScore: number;
    currentWeekSatisfactionScore: number;
    previousWeekCompletionRate: number;
    currentWeekCompletionRate: number;
    previousWeekRejectionRate: number;
    currentWeekRejectionRate: number;
    previousWeekCookingTimeMinutes: number;
    currentWeekCookingTimeMinutes: number;
    improvementThresholdRatio: number;
  }
  
  interface CalculateWeeklyImprovementMetricsResult {
    satisfactionScoreChangeRate: number;
    completionRateChangeRate: number;
    rejectionRateReduction: number;
    cookingTimeShorteningRate: number;
    totalImprovementScore: number;
    isImprovementSuccess: boolean;
    improvementStatus: string;
  }
  
   function calculateWeeklyImprovementMetrics(
    input: CalculateWeeklyImprovementMetricsInput
  ): CalculateWeeklyImprovementMetricsResult {
    const {
      previousWeekSatisfactionScore,
      currentWeekSatisfactionScore,
      previousWeekCompletionRate,
      currentWeekCompletionRate,
      previousWeekRejectionRate,
      currentWeekRejectionRate,
      previousWeekCookingTimeMinutes,
      currentWeekCookingTimeMinutes,
      improvementThresholdRatio,
    } = input;
  
    // Calculate satisfaction score change rate
    const satisfactionScoreChangeRate =
      previousWeekSatisfactionScore > 0
        ? (currentWeekSatisfactionScore - previousWeekSatisfactionScore) /
          previousWeekSatisfactionScore
        : 0;
  
    // Calculate completion rate change rate
    const completionRateChangeRate =
      previousWeekCompletionRate > 0
        ? (currentWeekCompletionRate - previousWeekCompletionRate) /
          previousWeekCompletionRate
        : 0;
  
    // Calculate rejection rate reduction
    const rejectionRateReduction =
      previousWeekRejectionRate > 0
        ? (previousWeekRejectionRate - currentWeekRejectionRate) /
          previousWeekRejectionRate
        : 0;
  
    // Calculate cooking time shortening rate
    const cookingTimeShorteningRate =
      previousWeekCookingTimeMinutes > 0
        ? (previousWeekCookingTimeMinutes - currentWeekCookingTimeMinutes) /
          previousWeekCookingTimeMinutes
        : 0;
  
    // Calculate total improvement score as average of all metrics
    const totalImprovementScore =
      (satisfactionScoreChangeRate +
        completionRateChangeRate +
        rejectionRateReduction +
        cookingTimeShorteningRate) /
      4;
  
    // Determine improvement success based on threshold
    const isImprovementSuccess = totalImprovementScore > improvementThresholdRatio;
  
    // Set improvement status message
    const improvementStatus = isImprovementSuccess ? '改善成功' : '改善未達';
  
    return {
      satisfactionScoreChangeRate,
      completionRateChangeRate,
      rejectionRateReduction,
      cookingTimeShorteningRate,
      totalImprovementScore,
      isImprovementSuccess,
      improvementStatus,
    };
  }
  return { calculateWeeklyImprovementMetrics };
})();
export const calculateWeeklyImprovementMetrics = __aivicBundle_66_calculateWeeklyImprovementMetrics.calculateWeeklyImprovementMetrics;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateWeeklyImprovementMetrics */

/* AIVIC_FUNCTION_BUNDLE_START owner=validateAlgorithmImprovementMetrics exports=validateAlgorithmImprovementMetrics */
const __aivicBundle_67_validateAlgorithmImprovementMetrics = (() => {
  function validateAlgorithmImprovementMetrics(input: any): any {
    const { successRate, cookingTimeReduction, userSatisfactionScore, previousWeekSuccessRate, previousWeekCookingTimeReduction, previousWeekUserSatisfactionScore } = input;
  
    const processingLog: string[] = [];
    let evaluationMethod: "absolute" | "weekOverWeek" = "absolute";
    let weekOverWeekSuccessRateChange: number | null = null;
    let weekOverWeekCookingTimeChange: number | null = null;
    let weekOverWeekSatisfactionScoreChange: number | null = null;
  
    // 前週データの存在確認
    const hasPreviousWeekData =
      previousWeekSuccessRate !== null &&
      previousWeekSuccessRate !== undefined &&
      previousWeekCookingTimeReduction !== null &&
      previousWeekCookingTimeReduction !== undefined &&
      previousWeekUserSatisfactionScore !== null &&
      previousWeekUserSatisfactionScore !== undefined;
  
    if (!hasPreviousWeekData) {
      processingLog.push("前週データが存在しません。前週比計算をスキップします。");
      processingLog.push("絶対値指標のみに基づいて改善度を評価します。");
      evaluationMethod = "absolute";
    } else {
      evaluationMethod = "weekOverWeek";
      weekOverWeekSuccessRateChange = successRate - previousWeekSuccessRate;
      weekOverWeekCookingTimeChange =
        cookingTimeReduction - previousWeekCookingTimeReduction;
      weekOverWeekSatisfactionScoreChange =
        userSatisfactionScore - previousWeekUserSatisfactionScore;
      processingLog.push("前週データを使用して前週比計算を実行します。");
    }
  
    // 絶対値指標に基づく改善度評価
    const successRateThreshold = 0.85;
    const cookingTimeReductionThreshold = 10;
    const satisfactionScoreThreshold = 4.0;
  
    let improvementScore = 0;
    const scoreComponents: number[] = [];
  
    // 成功率の評価
    if (successRate >= successRateThreshold) {
      scoreComponents.push(35);
    } else {
      scoreComponents.push(Math.max(0, (successRate / successRateThreshold) * 35));
    }
  
    // 調理時間短縮の評価
    if (cookingTimeReduction >= cookingTimeReductionThreshold) {
      scoreComponents.push(35);
    } else {
      scoreComponents.push(
        Math.max(
          0,
          (cookingTimeReduction / cookingTimeReductionThreshold) * 35
        )
      );
    }
  
    // 満足度スコアの評価
    if (userSatisfactionScore >= satisfactionScoreThreshold) {
      scoreComponents.push(30);
    } else {
      scoreComponents.push(
        Math.max(0, (userSatisfactionScore / satisfactionScoreThreshold) * 30)
      );
    }
  
    improvementScore = Math.round(
      scoreComponents.reduce((a, b) => a + b, 0)
    );
  
    const improvementAssessment = improvementScore >= 80 ? "approved" : "rejected";
  
    // ダッシュボード表示用フォーマット
    const successRateDisplay = `${Math.round(successRate * 100)}%`;
    const cookingTimeReductionDisplay = `${cookingTimeReduction}分短縮`;
    const userSatisfactionScoreDisplay = `${userSatisfactionScore.toFixed(1)}/5.0`;
    const weekOverWeekChangeDisplay = hasPreviousWeekData
      ? `成功率: ${weekOverWeekSuccessRateChange! > 0 ? "+" : ""}${(weekOverWeekSuccessRateChange! * 100).toFixed(1)}%, 調理時間: ${weekOverWeekCookingTimeChange! > 0 ? "+" : ""}${weekOverWeekCookingTimeChange!.toFixed(1)}分, 満足度: ${weekOverWeekSatisfactionScoreChange! > 0 ? "+" : ""}${weekOverWeekSatisfactionScoreChange!.toFixed(1)}`
      : "スキップ（前週データなし）";
    const improvementBadge =
      improvementAssessment === "approved" ? "改善認定" : "改善未認定";
  
    const dashboardDisplay = {
      successRateDisplay,
      cookingTimeReductionDisplay,
      userSatisfactionScoreDisplay,
      weekOverWeekChangeDisplay,
      improvementBadge,
    };
  
    return {
      evaluationMethod,
      successRate,
      cookingTimeReduction,
      userSatisfactionScore,
      weekOverWeekSuccessRateChange,
      weekOverWeekCookingTimeChange,
      weekOverWeekSatisfactionScoreChange,
      improvementAssessment,
      improvementScore,
      dashboardDisplay,
      processingLog,
      errorOccurred: false,
    };
  }
  return { validateAlgorithmImprovementMetrics };
})();
export const validateAlgorithmImprovementMetrics = __aivicBundle_67_validateAlgorithmImprovementMetrics.validateAlgorithmImprovementMetrics;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateAlgorithmImprovementMetrics */

/* AIVIC_FUNCTION_BUNDLE_START owner=validateDeploymentImprovementMetrics exports=validateDeploymentImprovementMetrics */
const __aivicBundle_68_validateDeploymentImprovementMetrics = (() => {
  function validateDeploymentImprovementMetrics(metricsDataset: any): {
    isValid: boolean;
    warning: string;
    missingMetrics: string[];
    processingHalted: boolean;
    userPrompt: string;
  } {
    const requiredMetrics = [
      'processingSpeed',
      'accuracy',
      'resourceUsageRate',
      'successRate',
      'userSatisfactionScore',
    ];
  
    const missingMetrics: string[] = [];
  
    for (const metric of requiredMetrics) {
      const value = metricsDataset[metric];
      if (value === undefined || value === null || value === '') {
        missingMetrics.push(metric);
      }
    }
  
    const isValid = missingMetrics.length === 0;
  
    let warning = '';
    let userPrompt = '';
  
    if (!isValid) {
      warning = `欠落指標: ${missingMetrics.join(', ')}`;
      userPrompt = 'データ補完が必要です';
    }
  
    return {
      isValid,
      warning,
      missingMetrics,
      processingHalted: !isValid,
      userPrompt,
    };
  }
  return { validateDeploymentImprovementMetrics };
})();
