/* AIVIC_FUNCTION_BUNDLE_START owner=deleteExpiredMealEvaluationData exports=deleteExpiredMealEvaluationData */
const __aivicBundle_69_deleteExpiredMealEvaluationData = (() => {
  function deleteExpiredMealEvaluationData(input: {
    retentionPolicy?: number;
    database: { mealEvaluationRecords: Array<{ id: number; createdAt: string }> };
    logger: { error: string[] };
    currentDateTime: Date;
  }): { status: string; deletedCount: number; remainingCount?: number; deletionTimestamp?: string } {
    const { retentionPolicy, database, logger, currentDateTime } = input;
  
    if (retentionPolicy === undefined) {
      logger.error.push('保持期間ポリシーが未定義です。データ削除処理をスキップします。');
      return {
        status: 'skipped',
        deletedCount: 0,
      };
    }
  
    const retentionPolicyMs = retentionPolicy * 30 * 24 * 60 * 60 * 1000;
    const cutoffDate = new Date(currentDateTime.getTime() - retentionPolicyMs);
  
    const recordsToDelete: number[] = [];
    const recordsToKeep: Array<{ id: number; createdAt: string }> = [];
  
    for (const record of database.mealEvaluationRecords) {
      const recordDate = new Date(record.createdAt);
      if (recordDate < cutoffDate) {
        recordsToDelete.push(record.id);
      } else {
        recordsToKeep.push(record);
      }
    }
  
    database.mealEvaluationRecords = recordsToKeep;
  
    return {
      status: 'completed',
      deletedCount: recordsToDelete.length,
      remainingCount: recordsToKeep.length,
      deletionTimestamp: currentDateTime.toISOString(),
    };
  }
  return { deleteExpiredMealEvaluationData };
})();
export const deleteExpiredMealEvaluationData = __aivicBundle_69_deleteExpiredMealEvaluationData.deleteExpiredMealEvaluationData;
/* AIVIC_FUNCTION_BUNDLE_END owner=deleteExpiredMealEvaluationData */

