/* AIVIC_FUNCTION_BUNDLE_START owner=calculateSuccessRateImprovement exports=calculateSuccessRateImprovement */
const __aivicBundle_72_calculateSuccessRateImprovement = (() => {
  function calculateSuccessRateImprovement(
    baselineSuccessRate: number,
    improvedSuccessRate: number
  ): number {
    if (typeof baselineSuccessRate !== 'number' || typeof improvedSuccessRate !== 'number') {
      throw new Error('Success rate must be a number');
    }
  
    if (baselineSuccessRate < 0 || baselineSuccessRate > 1) {
      throw new Error('Baseline success rate must be between 0 and 1');
    }
  
    if (improvedSuccessRate < 0 || improvedSuccessRate > 1) {
      throw new Error('Improved success rate must be between 0 and 1');
    }
  
    if (baselineSuccessRate === 0) {
      throw new Error('Baseline success rate cannot be zero (division by zero)');
    }
  
    const improvementPercentage = ((improvedSuccessRate - baselineSuccessRate) / baselineSuccessRate) * 100;
  
    return improvementPercentage;
  }
  return { calculateSuccessRateImprovement };
})();
export const calculateSuccessRateImprovement = __aivicBundle_72_calculateSuccessRateImprovement.calculateSuccessRateImprovement;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateSuccessRateImprovement */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculateCookingTimeReduction exports=calculateCookingTimeReduction */
const __aivicBundle_73_calculateCookingTimeReduction = (() => {
  function calculateCookingTimeReduction(
    baselineCookingTime: number,
    improvedCookingTime: number
  ): number {
    if (typeof baselineCookingTime !== 'number' || typeof improvedCookingTime !== 'number') {
      throw new Error('Cooking time values must be numbers');
    }
  
    if (baselineCookingTime <= 0) {
      throw new Error('Baseline cooking time must be positive');
    }
  
    if (improvedCookingTime < 0) {
      throw new Error('Improved cooking time must be non-negative');
    }
  
    const reductionPercentage = ((baselineCookingTime - improvedCookingTime) / baselineCookingTime) * 100;
  
    return reductionPercentage;
  }
  return { calculateCookingTimeReduction };
})();
