/* AIVIC_FUNCTION_BUNDLE_START owner=aggregateAlgorithmMetrics exports=aggregateAlgorithmMetrics */
const __aivicBundle_75_aggregateAlgorithmMetrics = (() => {
  function aggregateAlgorithmMetrics(
    improvementPatterns: Array<{
      patternId: string;
      preData: {
        successRate: number;
        cookingTime: number;
        satisfactionScore: number;
      };
      postData: {
        successRate: number;
        cookingTime: number;
        satisfactionScore: number;
      };
    }>
  ): {
    patternCount: number;
    averageSuccessRateImprovement: number;
    averageCookingTimeReduction: number;
    averageSatisfactionScoreChange: number;
    minSuccessRateImprovement: number;
    maxSuccessRateImprovement: number;
  } {
    if (!improvementPatterns || improvementPatterns.length === 0) {
      return {
        patternCount: 0,
        averageSuccessRateImprovement: 0,
        averageCookingTimeReduction: 0,
        averageSatisfactionScoreChange: 0,
        minSuccessRateImprovement: 0,
        maxSuccessRateImprovement: 0,
      };
    }
  
    const improvements = improvementPatterns.map((pattern) => {
      const successRateImprovement =
        ((pattern.postData.successRate - pattern.preData.successRate) /
          pattern.preData.successRate) *
        100;
  
      const cookingTimeReduction =
        ((pattern.preData.cookingTime - pattern.postData.cookingTime) /
          pattern.preData.cookingTime) *
        100;
  
      const satisfactionScoreChange =
        ((pattern.postData.satisfactionScore -
          pattern.preData.satisfactionScore) /
          pattern.preData.satisfactionScore) *
        100;
  
      return {
        successRateImprovement,
        cookingTimeReduction,
        satisfactionScoreChange,
      };
    });
  
    const successRateImprovements = improvements.map(
      (i) => i.successRateImprovement
    );
    const cookingTimeReductions = improvements.map((i) => i.cookingTimeReduction);
    const satisfactionScoreChanges = improvements.map(
      (i) => i.satisfactionScoreChange
    );
  
    const averageSuccessRateImprovement =
      successRateImprovements.reduce((sum, val) => sum + val, 0) /
      improvements.length;
  
    const averageCookingTimeReduction =
      cookingTimeReductions.reduce((sum, val) => sum + val, 0) /
      improvements.length;
  
    const averageSatisfactionScoreChange =
      satisfactionScoreChanges.reduce((sum, val) => sum + val, 0) /
      improvements.length;
  
    const minSuccessRateImprovement = Math.min(...successRateImprovements);
    const maxSuccessRateImprovement = Math.max(...successRateImprovements);
  
    return {
      patternCount: improvementPatterns.length,
      averageSuccessRateImprovement,
      averageCookingTimeReduction,
      averageSatisfactionScoreChange,
      minSuccessRateImprovement,
      maxSuccessRateImprovement,
    };
  }
  return { aggregateAlgorithmMetrics };
})();
export const aggregateAlgorithmMetrics = __aivicBundle_75_aggregateAlgorithmMetrics.aggregateAlgorithmMetrics;
