/* AIVIC_FUNCTION_BUNDLE_START owner=exportComparisonResultsToCSV exports=exportComparisonResultsToCSV */
const __aivicBundle_77_exportComparisonResultsToCSV = (() => {
  function exportComparisonResultsToCSV(
    comparisonResults: any,
    outputFilePath?: string
  ): { exportedFilePath: string; recordCount: number; exportTimestamp: string; success: boolean } | string {
    // Handle both single object and array inputs
    const resultsArray = Array.isArray(comparisonResults)
      ? comparisonResults
      : [comparisonResults];
  
    if (resultsArray.length === 0) {
      const timestamp = new Date().toISOString();
      const filePath = outputFilePath || "comparison_results.csv";
      return {
        exportedFilePath: filePath,
        recordCount: 0,
        exportTimestamp: timestamp,
        success: true,
      };
    }
  
    // Build CSV header
    const headers = [
      "Baseline Version",
      "Improved Version",
      "Success Rate Improvement (%)",
      "Cooking Time Reduction (%)",
      "Satisfaction Score Improvement (%)",
      "Statistical Significance",
      "Is Significant",
    ];
  
    // Build CSV rows
    const rows: string[] = [headers.map((h) => `"${h}"`).join(",")];
  
    for (const result of resultsArray) {
      const row = [
        `"${result.baselineVersion || ""}"`,
        `"${result.improvedVersion || ""}"`,
        String(result.successRateImprovement ?? ""),
        String(result.cookingTimeReductionImprovement ?? ""),
        String(result.satisfactionScoreImprovement ?? ""),
        String(result.statisticalSignificance ?? ""),
        String(result.isSignificant ?? false),
      ];
      rows.push(row.join(","));
    }
  
    const csvContent = rows.join("\n");
    const exportedFilePath = outputFilePath || "comparison_results.csv";
    const exportTimestamp = new Date().toISOString();
  
    // Determine return type based on whether outputFilePath is provided
    // If outputFilePath is provided, return object; otherwise return CSV string for backward compatibility
    if (outputFilePath) {
      return {
        exportedFilePath,
        recordCount: resultsArray.length,
        exportTimestamp,
        success: true,
      };
    }
  
    // Return CSV content as string when no outputFilePath provided (for test compatibility)
    return csvContent;
  }
  return { exportComparisonResultsToCSV };
})();
export const exportComparisonResultsToCSV: (...args: any[]) => any = (...args: any[]) => (__aivicBundle_77_exportComparisonResultsToCSV.exportComparisonResultsToCSV as (...args: any[]) => any)(...args);
/* AIVIC_FUNCTION_BUNDLE_END owner=exportComparisonResultsToCSV */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculateAlgorithmImprovementEffect exports=calculateAlgorithmImprovementEffect */
const __aivicBundle_78_calculateAlgorithmImprovementEffect = (() => {
  function calculateAlgorithmImprovementEffect(input: {
    beforeSuccessRate?: number;
    afterSuccessRate?: number;
    minimumThreshold?: number;
    improvementTargetRate?: number;
    productionStartDate?: Date;
    productionEndDate?: Date;
    preImprovementMetrics?: {
      successRate: number;
      cookingTimeReduction: number;
      satisfactionScore: number;
    };
    postImprovementMetrics?: {
      successRate: number;
      cookingTimeReduction: number;
      satisfactionScore: number;
    };
  }): {
    beforeSuccessRate: number;
    afterSuccessRate: number;
    minimumThreshold: number;
    improvementTargetRate: number;
    improvementDifference: number;
    progressPercentage: number;
    isThresholdMet: boolean;
    progressStatus: string;
    isImprovementValid: boolean;
    recommendedAction: string;
  } {
    // 本番稼働期間の検証（7日以上必須）
    if (input.productionStartDate && input.productionEndDate) {
      const durationMs = input.productionEndDate.getTime() - input.productionStartDate.getTime();
      const durationDays = durationMs / (1000 * 60 * 60 * 24);
      if (durationDays < 7) {
        throw new Error('本番稼働期間は7日以上である必要があります');
      }
    }
  
    // 改善前後の成功率を取得
    const beforeSuccessRate = input.beforeSuccessRate ?? (input.preImprovementMetrics?.successRate ?? 0) * 100;
    const afterSuccessRate = input.afterSuccessRate ?? (input.postImprovementMetrics?.successRate ?? 0) * 100;
    const minimumThreshold = input.minimumThreshold ?? 75.0;
    const improvementTargetRate = input.improvementTargetRate ?? 5.0;
  
    // 改善差分を計算
    const improvementDifference = afterSuccessRate - beforeSuccessRate;
  
    // 進捗パーセンテージを計算
    const progressPercentage = improvementTargetRate > 0 ? (improvementDifference / improvementTargetRate) * 100 : 0;
  
    // 最小閾値達成判定
    const isThresholdMet = afterSuccessRate >= minimumThreshold;
  
    // 改善有効判定（改善差分が正かつ最小閾値達成）
    const isImprovementValid = improvementDifference > 0 && isThresholdMet;
  
    // 進捗状況の判定
    let progressStatus = '未達成';
    if (progressPercentage >= 100) {
      progressStatus = '達成中';
    }
    if (progressPercentage >= 150) {
      progressStatus = '目標達成';
    }
  
    // 推奨アクションの決定
    let recommendedAction = '改善効果を確認してください';
    if (isImprovementValid && progressPercentage >= 100) {
      recommendedAction = '改善効果を本番反映へ進める';
    } else if (!isThresholdMet) {
      recommendedAction = '最小閾値に達していません。さらなる改善が必要です';
    }
  
    return {
      beforeSuccessRate,
      afterSuccessRate,
      minimumThreshold,
      improvementTargetRate,
      improvementDifference,
      progressPercentage,
      isThresholdMet,
      progressStatus,
      isImprovementValid,
      recommendedAction,
    };
  }
  return { calculateAlgorithmImprovementEffect };
})();
export const calculateAlgorithmImprovementEffect = __aivicBundle_78_calculateAlgorithmImprovementEffect.calculateAlgorithmImprovementEffect;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateAlgorithmImprovementEffect */

