/* AIVIC_FUNCTION_BUNDLE_START owner=detectOverdueEvaluationAndNotify exports=detectOverdueEvaluationAndNotify */
const __aivicBundle_81_detectOverdueEvaluationAndNotify = (() => {
  function detectOverdueEvaluationAndNotify(input: any) {
    const currentTimestamp = new Date(input.current_timestamp);
    const mealCompletionTimestamp = new Date(input.meal_completion_timestamp);
    const evaluationDeadlineHours = input.evaluation_deadline_hours;
  
    const elapsedMs = currentTimestamp.getTime() - mealCompletionTimestamp.getTime();
    const elapsedHours = elapsedMs / (1000 * 60 * 60);
    const deadlineMs = evaluationDeadlineHours * 60 * 60 * 1000;
  
    const isDeadlineOverdue = elapsedMs > deadlineMs;
    const hoursOverdue = Math.max(0, elapsedHours - evaluationDeadlineHours);
  
    const notificationTimestamp = new Date().toISOString();
  
    const notificationMessage = `食事評価入力期限超過のお知らせ: ${input.family_member_name}様の${mealCompletionTimestamp.toLocaleDateString('ja-JP')}の食事評価が期限を超過しました。`;
  
    const notificationLog = {
      household_head_user_id: input.household_head_user_id,
      household_head_email: input.household_head_email,
      notification_type: 'evaluation_deadline_overdue',
      family_member_id: input.family_member_id,
      family_member_name: input.family_member_name,
      meal_id: input.meal_id,
      notification_timestamp: notificationTimestamp,
      notification_content: notificationMessage,
      notification_status: isDeadlineOverdue ? 'sent' : 'pending',
      deadline_at: input.deadline_timestamp,
    };
  
    return {
      is_deadline_overdue: isDeadlineOverdue,
      hours_overdue: hoursOverdue,
      notification_sent: isDeadlineOverdue,
      notification_recipient_user_id: input.household_head_user_id,
      notification_recipient_email: input.household_head_email,
      affected_family_member_id: input.family_member_id,
      affected_family_member_name: input.family_member_name,
      notification_message: notificationMessage,
      notification_log: notificationLog,
    };
  }
  return { detectOverdueEvaluationAndNotify };
})();
