/* AIVIC_FUNCTION_BUNDLE_START owner=generateWeeklyMenuWithEvaluationFiltering exports=generateWeeklyMenuWithEvaluationFiltering */
const __aivicBundle_82_generateWeeklyMenuWithEvaluationFiltering = (() => {
  function generateWeeklyMenuWithEvaluationFiltering(
    input: any
  ): any {
    const startTime = new Date().toISOString();
    const startTimeMs = Date.now();
  
    const referenceDate = new Date(input.referenceDate);
    const evaluationDeadlineHours = input.evaluationDeadlineHours ?? 24;
    const mealEvaluations = input.mealEvaluations ?? [];
  
    // Filter evaluations based on deadline
    const now = new Date();
    const deadlineMs = evaluationDeadlineHours * 60 * 60 * 1000;
  
    const retainedEvaluations: any[] = [];
    const excludedEvaluationIds: string[] = [];
    const retainedEvaluationIds: string[] = [];
  
    mealEvaluations.forEach((evaluation: any) => {
      const evaluationTime = new Date(evaluation.recordedAt ?? evaluation.timestamp);
      const ageMs = now.getTime() - evaluationTime.getTime();
  
      if (ageMs <= deadlineMs) {
        retainedEvaluations.push(evaluation);
        retainedEvaluationIds.push(evaluation.evaluationId);
      } else {
        excludedEvaluationIds.push(evaluation.evaluationId);
      }
    });
  
    const filteredEvaluationCount = retainedEvaluations.length;
    const retentionRate =
      mealEvaluations.length > 0
        ? filteredEvaluationCount / mealEvaluations.length
        : 0;
  
    // Calculate average satisfaction and completion from retained evaluations
    let totalSatisfaction = 0;
    let totalCompletion = 0;
    retainedEvaluations.forEach((evaluation: any) => {
      totalSatisfaction += evaluation.satisfactionScore ?? 0;
      totalCompletion += evaluation.completionRate ?? 0;
    });
  
    const averageSatisfactionFromRetained =
      retainedEvaluations.length > 0
        ? totalSatisfaction / retainedEvaluations.length
        : 0;
    const averageCompletionFromRetained =
      retainedEvaluations.length > 0
        ? totalCompletion / retainedEvaluations.length
        : 0;
  
    // Generate weekly menu structure
    const weekStartDate = new Date(referenceDate);
    weekStartDate.setUTCHours(0, 0, 0, 0);
  
    const weekEndDate = new Date(referenceDate);
    weekEndDate.setUTCDate(weekEndDate.getUTCDate() + 6);
    weekEndDate.setUTCHours(23, 59, 59, 999);
  
    // Build daily menus using retained evaluations
    const dailyMenus: any[] = [];
    for (let dayOffset = 0; dayOffset < 7; dayOffset++) {
      const dayDate = new Date(weekStartDate);
      dayDate.setUTCDate(dayDate.getUTCDate() + dayOffset);
  
      const meals: any[] = [];
  
      // Distribute retained evaluations across days
      if (retainedEvaluations.length > 0) {
        const evaluationIndex = dayOffset % retainedEvaluations.length;
        const evaluation = retainedEvaluations[evaluationIndex];
  
        meals.push({
          mealId: evaluation.mealId ?? `meal-${dayOffset}`,
          mealName: evaluation.mealName ?? `Meal ${dayOffset + 1}`,
          satisfactionScore: evaluation.satisfactionScore ?? 0,
          completionRate: evaluation.completionRate ?? 0,
          evaluationSource: evaluation.evaluationId,
        });
      }
  
      dailyMenus.push({
        date: dayDate,
        meals: meals,
      });
    }
  
    const endTimeMs = Date.now();
    const endTime = new Date().toISOString();
    const processingDurationMs = endTimeMs - startTimeMs;
  
    // Calculate data integrity score
    const dataIntegrityScore = Math.min(
      100,
      Math.round(retentionRate * 100 + (retainedEvaluations.length > 0 ? 45 : 0))
    );
  
    return {
      success: true,
      filteredEvaluationCount: filteredEvaluationCount,
      retainedEvaluationIds: retainedEvaluationIds,
      excludedEvaluationIds: excludedEvaluationIds,
      generatedMenu: {
        weekStartDate: weekStartDate,
        weekEndDate: weekEndDate,
        dailyMenus: dailyMenus,
      },
      qualityMetrics: {
        retentionRate: retentionRate,
        dataIntegrityScore: dataIntegrityScore,
        averageSatisfactionFromRetained: averageSatisfactionFromRetained,
        averageCompletionFromRetained: averageCompletionFromRetained,
      },
      executionMetadata: {
        startTime: startTime,
        endTime: endTime,
        processingDurationMs: processingDurationMs,
        processedEvaluationCount: mealEvaluations.length,
        excludedEvaluationCount: excludedEvaluationIds.length,
        retainedEvaluationCount: retainedEvaluationIds.length,
      },
    };
  }
  return { generateWeeklyMenuWithEvaluationFiltering };
})();
