/* AIVIC_FUNCTION_BUNDLE_START owner=validateAlgorithmImprovement exports=validateAlgorithmImprovement */
const __aivicBundle_87_validateAlgorithmImprovement = (() => {
  function validateAlgorithmImprovement(input: any): any {
    // Handle first test case: improvementProposal with target_metrics and validation_criteria
    if (input.proposal_id && input.target_metrics && input.validation_criteria) {
      const {
        target_metrics,
        validation_criteria,
        nutritionist_approval,
        technical_feasibility_score,
        user_impact_score,
      } = input;
  
      const successRateMeets =
        target_metrics.success_rate_improvement_percent >=
        validation_criteria.min_success_rate_improvement;
      const cookingTimeMeets =
        target_metrics.cooking_time_reduction_percent >=
        validation_criteria.min_cooking_time_reduction;
      const satisfactionMeets =
        target_metrics.satisfaction_score_improvement >=
        validation_criteria.min_satisfaction_score_improvement;
  
      const allMeetCriteria =
        successRateMeets && cookingTimeMeets && satisfactionMeets;
      const nutritionistApproved = nutritionist_approval === true;
  
      const estimatedEffectScore =
        (technical_feasibility_score * 0.4 + user_impact_score * 0.6) *
        (allMeetCriteria ? 1.0 : 0.7);
  
      return {
        is_approved: allMeetCriteria && nutritionistApproved,
        approval_reason: allMeetCriteria ? '承認可能' : '基準未達',
        validation_status: allMeetCriteria ? 'OK' : 'NG',
        success_rate_meets_criteria: successRateMeets,
        cooking_time_meets_criteria: cookingTimeMeets,
        satisfaction_score_meets_criteria: satisfactionMeets,
        nutritionist_approval_status: nutritionistApproved
          ? 'approved'
          : 'rejected',
        estimated_effect_score: estimatedEffectScore,
        implementation_recommended: allMeetCriteria && nutritionistApproved,
      };
    }
  
    // Handle second test case: improvementData with validationCriteria array
    if (input.algorithmVersionId && Array.isArray(input.validationCriteria)) {
      const { validationCriteria } = input;
  
      const passedCriteria = validationCriteria.filter(
        (c: any) => c.isPass === true
      );
      const failedCriteria = validationCriteria
        .filter((c: any) => c.isPass === false)
        .map((c: any) => ({
          criteriaId: c.criteriaId,
          criteriaName: c.criteriaName,
          targetThreshold: c.targetThreshold,
          actualValue: c.actualValue,
          gap: c.actualValue - c.targetThreshold,
        }));
  
      const totalCriteriaCount = validationCriteria.length;
      const passCriteriaCount = passedCriteria.length;
      const failCriteriaCount = failedCriteria.length;
  
      const approvalStatus = failCriteriaCount === 0 ? '可' : '否';
  
      const approvalReason =
        failCriteriaCount === 0
          ? '全基準を満たしています'
          : failedCriteria
              .map((c: any) => `${c.criteriaName}(目標: ${c.targetThreshold}, 実績: ${c.actualValue})`)
              .join(', ');
  
      const validationTimestamp = new Date().toISOString();
  
      return {
        approvalStatus,
        failedCriteria,
        passedCriteria,
        totalCriteriaCount,
        passCriteriaCount,
        failCriteriaCount,
        approvalReason,
        validationTimestamp,
      };
    }
  
    // Fallback for other input shapes
    return {
      is_approved: false,
      approval_reason: '入力形式が不正です',
      validation_status: 'ERROR',
    };
  }
  return { validateAlgorithmImprovement };
})();
export const validateAlgorithmImprovement = __aivicBundle_87_validateAlgorithmImprovement.validateAlgorithmImprovement;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateAlgorithmImprovement */

