/* AIVIC_FUNCTION_BUNDLE_START owner=calculateImprovementEffectProspect exports=calculateImprovementEffectProspect */
const __aivicBundle_89_calculateImprovementEffectProspect = (() => {
  function calculateImprovementEffectProspect(input: {
    before_accuracy: number;
    after_accuracy: number;
    before_processing_time_sec: number;
    after_processing_time_sec: number;
    before_resource_usage_percent: number;
    after_resource_usage_percent: number;
  }): number {
    const {
      before_accuracy,
      after_accuracy,
      before_processing_time_sec,
      after_processing_time_sec,
      before_resource_usage_percent,
      after_resource_usage_percent,
    } = input;
  
    // Validation: before_accuracy must be in range [0, 100]
    if (before_accuracy < 0 || before_accuracy > 100) {
      throw new Error('精度は0～100の範囲内である必要があります');
    }
  
    // Validation: after_accuracy must be in range [0, 100]
    if (after_accuracy < 0 || after_accuracy > 100) {
      throw new Error('精度は0～100の範囲内である必要があります');
    }
  
    // Validation: before_processing_time_sec must be positive
    if (before_processing_time_sec <= 0) {
      throw new Error('処理速度は正の値である必要があります');
    }
  
    // Validation: after_processing_time_sec must be positive
    if (after_processing_time_sec <= 0) {
      throw new Error('処理速度は正の値である必要があります');
    }
  
    // Validation: before_resource_usage_percent must be positive
    if (before_resource_usage_percent <= 0) {
      throw new Error('リソース使用率は正の値である必要があります');
    }
  
    // Validation: after_resource_usage_percent must be in range [0, 100]
    if (after_resource_usage_percent < 0 || after_resource_usage_percent > 100) {
      throw new Error('リソース使用率は0～100の範囲内である必要があります');
    }
  
    // Calculate improvement rates for each metric
    const accuracyImprovementRate = ((after_accuracy - before_accuracy) / before_accuracy) * 100;
    const processingTimeImprovementRate = ((before_processing_time_sec - after_processing_time_sec) / before_processing_time_sec) * 100;
    const resourceImprovementRate = ((before_resource_usage_percent - after_resource_usage_percent) / before_resource_usage_percent) * 100;
  
    // Calculate average improvement effect
    const averageImprovementEffect = (accuracyImprovementRate + processingTimeImprovementRate + resourceImprovementRate) / 3;
  
    // Clamp result to [0, 100] range
    const result = Math.max(0, Math.min(100, averageImprovementEffect));
  
    return result;
  }
  return { calculateImprovementEffectProspect };
})();
export const calculateImprovementEffectProspect = __aivicBundle_89_calculateImprovementEffectProspect.calculateImprovementEffectProspect;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateImprovementEffectProspect */

/* AIVIC_FUNCTION_BUNDLE_START owner=processMultipleRestrictionsWithPriority exports=processMultipleRestrictionsWithPriority */
const __aivicBundle_90_processMultipleRestrictionsWithPriority = (() => {
  interface ProcessMultipleRestrictionsWithPriorityInput {
    id: string;
    timestamp: string;
    priority: number;
    type: string;
    content: string;
    userId: string;
  }
  
  interface ProcessedRestriction extends ProcessMultipleRestrictionsWithPriorityInput {
    executionOrder: number;
    status: string;
  }
  
  interface ProcessingLogEntry {
    restrictionId: string;
    priority: number;
    executionSequence: number;
    timestamp: string;
    message: string;
  }
  
  interface DashboardSummary {
    totalProcessed: number;
    allSuccessful: boolean;
    processingOrderCorrect: boolean;
    executionSequence: number[];
  }
  
  interface ProcessMultipleRestrictionsResult {
    processedRestrictions: ProcessedRestriction[];
    processingLog: ProcessingLogEntry[];
    dashboardSummary: DashboardSummary;
  }
  
   function processMultipleRestrictionsWithPriority(
    restrictionChanges: ProcessMultipleRestrictionsWithPriorityInput[]
  ): ProcessMultipleRestrictionsResult {
    const sortedRestrictions = [...restrictionChanges].sort(
      (a, b) => a.priority - b.priority
    );
  
    const processedRestrictions: ProcessedRestriction[] = sortedRestrictions.map(
      (restriction, index) => ({
        ...restriction,
        executionOrder: index + 1,
        status: 'completed',
      })
    );
  
    const processingLog: ProcessingLogEntry[] = processedRestrictions.map(
      (restriction) => ({
        restrictionId: restriction.id,
        priority: restriction.priority,
        executionSequence: restriction.executionOrder,
        timestamp: new Date().toISOString(),
        message: `Priority ${restriction.priority} restriction processed: ${restriction.content}`,
      })
    );
  
    const executionSequence = processedRestrictions.map(
      (r) => r.executionOrder
    );
  
    const dashboardSummary: DashboardSummary = {
      totalProcessed: processedRestrictions.length,
      allSuccessful: processedRestrictions.every((r) => r.status === 'completed'),
      processingOrderCorrect: executionSequence.every(
        (val, idx) => val === idx + 1
      ),
      executionSequence,
    };
  
    return {
      processedRestrictions,
      processingLog,
      dashboardSummary,
    };
  }
  return { processMultipleRestrictionsWithPriority };
})();
export const processMultipleRestrictionsWithPriority = __aivicBundle_90_processMultipleRestrictionsWithPriority.processMultipleRestrictionsWithPriority;
