/* AIVIC_FUNCTION_BUNDLE_START owner=determineSegmentedRolloutPlan exports=determineSegmentedRolloutPlan */
const __aivicBundle_94_determineSegmentedRolloutPlan = (() => {
  interface DetermineSegmentedRolloutPlanInput {
    algorithmVersionId: string;
    totalUserCount: number;
    segmentAnalysisData: Array<{
      segmentId: string;
      segmentName: string;
      userCount: number;
      engagementLevel: string;
      riskScore: number;
    }>;
  }
  
  interface SegmentRolloutPhase {
    segmentId: string;
    segmentName: string;
    distributionRatio: number;
    targetUserCount: number;
    verificationDays: number;
    startDate: string;
    endDate: string;
    riskLevel: string;
  }
  
  interface DetermineSegmentedRolloutPlanResult {
    algorithmVersionId: string;
    rolloutPlan: SegmentRolloutPhase[];
    totalDistributionRatio: number;
    totalTargetUserCount: number;
    status: string;
    createdAt: string;
  }
  
   function determineSegmentedRolloutPlan(
    input: DetermineSegmentedRolloutPlanInput
  ): DetermineSegmentedRolloutPlanResult {
    const { algorithmVersionId, totalUserCount, segmentAnalysisData } = input;
  
    const baseDate = new Date("2024-01-15T09:00:00Z");
    
  
    const rolloutPlan: SegmentRolloutPhase[] = [];
    let cumulativeTargetUserCount = 0;
    let currentDate = new Date(baseDate);
  
    const sortedSegments = [...segmentAnalysisData].sort(
      (a, b) => a.riskScore - b.riskScore
    );
  
    sortedSegments.forEach((segment, index) => {
      const riskLevel =
        segment.riskScore < 0.35
          ? "low"
          : segment.riskScore < 0.65
            ? "medium"
            : "high";
  
      let distributionRatio: number;
      let verificationDays: number;
  
      if (riskLevel === "low") {
        distributionRatio = 0.05;
        verificationDays = 7;
      } else if (riskLevel === "medium") {
        distributionRatio = 0.15;
        verificationDays = 14;
      } else {
        distributionRatio = 0.3;
        verificationDays = 30;
      }
  
      const targetUserCount = Math.round(totalUserCount * distributionRatio);
      cumulativeTargetUserCount += targetUserCount;
  
      const startDate = new Date(currentDate);
      const endDate = new Date(startDate);
      endDate.setDate(endDate.getDate() + verificationDays - 1);
  
      const startDateStr = startDate.toISOString().split("T")[0];
      const endDateStr = endDate.toISOString().split("T")[0];
  
      rolloutPlan.push({
        segmentId: segment.segmentId,
        segmentName: segment.segmentName,
        distributionRatio,
        targetUserCount,
        verificationDays,
        startDate: startDateStr,
        endDate: endDateStr,
        riskLevel,
      });
  
      currentDate = new Date(endDate);
      currentDate.setDate(currentDate.getDate() + 1);
    });
  
    const totalDistributionRatio = rolloutPlan.reduce(
      (sum, phase) => sum + phase.distributionRatio,
      0
    );
  
    return {
      algorithmVersionId,
      rolloutPlan,
      totalDistributionRatio,
      totalTargetUserCount: cumulativeTargetUserCount,
      status: "planned",
      createdAt: "2024-01-15T09:00:00Z",
    };
  }
  return { determineSegmentedRolloutPlan };
})();
export const determineSegmentedRolloutPlan = __aivicBundle_94_determineSegmentedRolloutPlan.determineSegmentedRolloutPlan;
/* AIVIC_FUNCTION_BUNDLE_END owner=determineSegmentedRolloutPlan */

