    const interval = config.verificationInterval || 30;
  
    const nextDate = new Date(lastDate);
    nextDate.setDate(nextDate.getDate() + interval);
  
    const today = new Date();
    today.setHours(0, 0, 0, 0);
  
    const nextDateNormalized = new Date(nextDate);
    nextDateNormalized.setHours(0, 0, 0, 0);
  
    const daysUntil = Math.floor(
      (nextDateNormalized.getTime() - today.getTime()) / (1000 * 60 * 60 * 24)
    );
  
    const isOverdue = daysUntil <= 0;
  
    const formatDate = (date: Date): string => {
      const year = date.getUTCFullYear();
      const month = String(date.getUTCMonth() + 1).padStart(2, '0');
      const day = String(date.getUTCDate()).padStart(2, '0');
      return `${year}-${month}-${day}`;
    };
  
    const lastDateNormalized = new Date(lastDate);
    lastDateNormalized.setHours(0, 0, 0, 0);
  
    const verificationCycleLabel = interval === 30 ? 'monthly' : interval === 7 ? 'weekly' : 'custom';
  
    return {
      nextVerificationDate: nextDate,
      isVerificationDue: isOverdue,
      daysUntilNextVerification: Math.max(0, daysUntil),
      verificationCycle: verificationCycleLabel,
      lastVerificationDateFormatted: formatDate(lastDateNormalized),
      nextVerificationDateFormatted: formatDate(nextDateNormalized),
    };
