/* AIVIC_FUNCTION_BUNDLE_START owner=validateNutritionStandardVerificationTiming exports=validateNutritionStandardVerificationTiming */
const __aivicBundle_98_validateNutritionStandardVerificationTiming = (() => {
  function validateNutritionStandardVerificationTiming(input: {
    nutrition_standard_logic_id?: string;
    verification_cycle: string | null;
    last_verification_date: string;
    current_date: string;
  }): {
    should_execute_verification: boolean;
    next_verification_scheduled_date: string;
    verification_target_period: {
      start_date: string;
      end_date: string;
    } | null;
    days_since_last_verification: number;
  } {
    if (!input.verification_cycle || input.verification_cycle === '') {
      throw new Error('検証周期が定義されていません');
    }
  
    const validCycles = ['monthly', 'quarterly', 'annual'];
    if (!validCycles.includes(input.verification_cycle)) {
      throw new Error('検証周期が無効です');
    }
  
    let lastVerificationDate: Date;
    let currentDate: Date;
  
    try {
      lastVerificationDate = new Date(input.last_verification_date);
      currentDate = new Date(input.current_date);
  
      if (isNaN(lastVerificationDate.getTime()) || isNaN(currentDate.getTime())) {
        throw new Error('検証対象期間の日付が無効です');
      }
    } catch {
      throw new Error('検証対象期間の日付フォーマットが無効です');
    }
  
    const daysSinceLastVerification = Math.floor(
      (currentDate.getTime() - lastVerificationDate.getTime()) / (1000 * 60 * 60 * 24)
    );
  
    let verificationIntervalDays: number;
    switch (input.verification_cycle) {
      case 'monthly':
        verificationIntervalDays = 30;
        break;
      case 'quarterly':
        verificationIntervalDays = 90;
        break;
      case 'annual':
        verificationIntervalDays = 365;
        break;
      default:
        verificationIntervalDays = 30;
    }
  
    const shouldExecuteVerification = daysSinceLastVerification >= verificationIntervalDays;
  
    const nextVerificationDate = new Date(lastVerificationDate);
    nextVerificationDate.setDate(nextVerificationDate.getDate() + verificationIntervalDays);
    const nextVerificationScheduledDateStr = nextVerificationDate.toISOString();
  
    const verificationTargetPeriod = shouldExecuteVerification
      ? {
          start_date: input.last_verification_date,
          end_date: input.current_date,
        }
      : null;
  
    return {
      should_execute_verification: shouldExecuteVerification,
      next_verification_scheduled_date: nextVerificationScheduledDateStr,
      verification_target_period: verificationTargetPeriod,
      days_since_last_verification: daysSinceLastVerification,
    };
  }
  return { validateNutritionStandardVerificationTiming };
})();
export const validateNutritionStandardVerificationTiming = __aivicBundle_98_validateNutritionStandardVerificationTiming.validateNutritionStandardVerificationTiming;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateNutritionStandardVerificationTiming */

/* AIVIC_FUNCTION_BUNDLE_START owner=aggregateWeeklyBehaviorIndicators exports=aggregateWeeklyBehaviorIndicators */
const __aivicBundle_99_aggregateWeeklyBehaviorIndicators = (() => {
  function aggregateWeeklyBehaviorIndicators(
    mealGenerationLogs: any[],
    weekStartDate: Date,
    weekEndDate: Date
  ): {
    week_start_date: Date;
    week_end_date: Date;
    menu_generation_success_rate: number;
    cooking_time_reduction_rate: number;
    average_satisfaction_score: number;
    total_menu_generations: number;
    successful_menu_generations: number;
    weekStartDate?: string;
    weekEndDate?: string;
    mealGenerationSuccessRate?: number;
    cookingTimeReductionRate?: number;
    userSatisfactionScore?: number;
    totalMealsGenerated?: number;
    totalMealsAccepted?: number;
    totalMealsRejected?: number;
    averageCookingTimeMinutes?: number;
    algorithmVersion?: string;
  } {
    // Filter logs within the week range
    const logsInWeek = mealGenerationLogs.filter((log) => {
      const logTime = new Date(log.menu_generation_timestamp);
      return logTime >= weekStartDate && logTime <= weekEndDate;
    });
  
    const totalGenerations = logsInWeek.length;
    const successfulGenerations = logsInWeek.filter(
      (log) => log.generation_success === true
    ).length;
  
    // Calculate success rate as percentage
    const successRate =
      totalGenerations > 0 ? (successfulGenerations / totalGenerations) * 100 : 0;
  
    // Calculate cooking time reduction rate
    let totalReductionRatio = 0;
    for (const log of logsInWeek) {
      const targetTime = log.target_cooking_time_minutes || 1;
      const actualTime = log.actual_cooking_time_minutes || 0;
      const reductionRatio = (targetTime - actualTime) / targetTime;
      totalReductionRatio += reductionRatio;
    }
    const avgReductionRate =
      totalGenerations > 0 ? (totalReductionRatio / totalGenerations) * 100 : 0;
  
    // Calculate average satisfaction score
    let totalSatisfaction = 0;
    for (const log of logsInWeek) {
      totalSatisfaction += log.satisfaction_score || 0;
    }
    const avgSatisfaction =
      totalGenerations > 0 ? totalSatisfaction / totalGenerations : 0;
  
    // Round to 2 decimal places for consistency with test expectations
    const roundedSuccessRate = Math.round(successRate * 100) / 100;
    const roundedReductionRate = Math.round(avgReductionRate * 100) / 100;
    const roundedSatisfaction = Math.round(avgSatisfaction * 100) / 100;
  
    return {
      week_start_date: weekStartDate,
      week_end_date: weekEndDate,
      menu_generation_success_rate: roundedSuccessRate,
      cooking_time_reduction_rate: roundedReductionRate,
      average_satisfaction_score: roundedSatisfaction,
      total_menu_generations: totalGenerations,
      successful_menu_generations: successfulGenerations,
      // camelCase aliases for compatibility
      weekStartDate: weekStartDate.toISOString(),
      weekEndDate: weekEndDate.toISOString(),
      mealGenerationSuccessRate: roundedSuccessRate,
      cookingTimeReductionRate: roundedReductionRate,
      userSatisfactionScore: roundedSatisfaction,
      totalMealsGenerated: totalGenerations,
      totalMealsAccepted: successfulGenerations,
      totalMealsRejected: totalGenerations - successfulGenerations,
      averageCookingTimeMinutes:
        totalGenerations > 0
          ? Math.round(
              (logsInWeek.reduce(
                (sum, log) => sum + (log.actual_cooking_time_minutes || 0),
                0
              ) /
                totalGenerations) *
                100
            ) / 100
          : 0,
    };
  }
  return { aggregateWeeklyBehaviorIndicators };
})();
export const aggregateWeeklyBehaviorIndicators = __aivicBundle_99_aggregateWeeklyBehaviorIndicators.aggregateWeeklyBehaviorIndicators;
/* AIVIC_FUNCTION_BUNDLE_END owner=aggregateWeeklyBehaviorIndicators */

