const __aivicBundle_101_calculateAlgorithmImprovementDegree = (() => {
  function calculateAlgorithmImprovementDegree(
    baselineVersion: {
      success_rate?: number;
      successRate?: number;
      cooking_time_reduction?: number;
      cookingTimeReduction?: number;
      user_satisfaction_score?: number;
      satisfactionScore?: number;
    },
    improvedVersion: {
      success_rate?: number;
      successRate?: number;
      cooking_time_reduction?: number;
      cookingTimeReduction?: number;
      user_satisfaction_score?: number;
      satisfactionScore?: number;
    }
  ): {
    improvement_degree: number;
    is_calculable: boolean;
    overallImprovementScore?: number;
    successRateImprovement?: number;
    satisfactionImprovement?: number;
    cookingTimeImprovement?: number;
    improvementStatus?: 'approved' | 'conditional' | 'rejected';
  } {
    // Extract values from either snake_case or camelCase properties
    const baselineSuccessRate = baselineVersion.success_rate ?? baselineVersion.successRate ?? 0;
    const baselineCookingTimeReduction = baselineVersion.cooking_time_reduction ?? baselineVersion.cookingTimeReduction ?? 0;
    const baselineSatisfactionScore = baselineVersion.user_satisfaction_score ?? baselineVersion.satisfactionScore ?? 0;
  
    const improvedSuccessRate = improvedVersion.success_rate ?? improvedVersion.successRate ?? 0;
    const improvedCookingTimeReduction = improvedVersion.cooking_time_reduction ?? improvedVersion.cookingTimeReduction ?? 0;
    const improvedSatisfactionScore = improvedVersion.user_satisfaction_score ?? improvedVersion.satisfactionScore ?? 0;
  
    // Calculate individual improvements (deltas)
    const successRateImprovement = improvedSuccessRate - baselineSuccessRate;
    const satisfactionImprovement = improvedSatisfactionScore - baselineSatisfactionScore;
    const cookingTimeImprovement = improvedCookingTimeReduction - baselineCookingTimeReduction;
  
    // Check if calculation is possible (avoid division by zero or all-zero inputs)
    const allBaselineZero = baselineSuccessRate === 0 && baselineCookingTimeReduction === 0 && baselineSatisfactionScore === 0;
    const allImprovedZero = improvedSuccessRate === 0 && improvedCookingTimeReduction === 0 && improvedSatisfactionScore === 0;
  
    // When both versions have all zero metrics, improvement degree is 0 and calculable
    if (allBaselineZero && allImprovedZero) {
      return {
        improvement_degree: 0,
        is_calculable: false,
        overallImprovementScore: 0,
        successRateImprovement: 0,
        satisfactionImprovement: 0,
        cookingTimeImprovement: 0,
        improvementStatus: 'rejected',
      };
    }
  
    // Calculate weighted overall improvement score
    // Weights: success_rate (30%), satisfaction (40%), cooking_time (30%)
    const successRateWeight = 0.3;
    const satisfactionWeight = 0.4;
    const cookingTimeWeight = 0.3;
  
    const overallImprovementScore =
      successRateImprovement * successRateWeight +
      satisfactionImprovement * satisfactionWeight +
      cookingTimeImprovement * cookingTimeWeight;
  
    // Determine improvement status based on overall score
    let improvementStatus: 'approved' | 'conditional' | 'rejected' = 'rejected';
    const approvalThreshold = 0.05; // 5% improvement threshold
    const conditionalThreshold = 0.01; // 1% improvement threshold
  
    if (overallImprovementScore >= approvalThreshold) {
      improvementStatus = 'approved';
    } else if (overallImprovementScore >= conditionalThreshold) {
      improvementStatus = 'conditional';
    } else {
      improvementStatus = 'rejected';
    }
  
    return {
      improvement_degree: overallImprovementScore,
      is_calculable: true,
      overallImprovementScore,
      successRateImprovement,
      satisfactionImprovement,
      cookingTimeImprovement,
      improvementStatus,
    };
  }
  return { calculateAlgorithmImprovementDegree };
})();
