const __aivicBundle_102_calculateNutritionAchievementDegree = (() => {
  function calculateNutritionAchievementDegree(nutritionData: {
    nutrientId?: string;
    nutrient_id?: string;
    nutrientName?: string;
    nutrient_name?: string;
    recommendedValue?: number;
    target_value?: number;
    actualValue?: number;
    actual_value?: number;
    unit?: string;
  }): number {
    const recommendedValue = nutritionData.recommendedValue ?? nutritionData.target_value;
    const actualValue = nutritionData.actualValue ?? nutritionData.actual_value;
  
    if (recommendedValue === undefined || actualValue === undefined) {
      throw new Error('推奨値と実績値は必須です');
    }
  
    if (recommendedValue === 0) {
      throw new Error('推奨値がゼロです');
    }
  
    if (recommendedValue < 0) {
      throw new Error('推奨値が負の値です');
    }
  
    const achievementDegree = (actualValue / recommendedValue) * 100;
  
    return achievementDegree;
  }
  return { calculateNutritionAchievementDegree };
})();
