/* AIVIC_FUNCTION_BUNDLE_START owner=aggregateImprovementProposals exports=aggregateImprovementProposals */
const __aivicBundle_105_aggregateImprovementProposals = (() => {
  function aggregateImprovementProposals(
    proposalData: Array<{
      proposal_id: string;
      proposal_name: string;
      description?: string;
      priority_score: number;
      implementation_effort?: string;
      expected_impact?: number;
      status: string;
      created_at?: string;
      updated_at?: string;
      dependencies: string[];
      implementation_date?: Date;
    }>
  ): {
    total_proposals: number;
    proposals_by_status: Record<string, number>;
    average_priority_score: number;
    aggregated_proposals: Array<{
      proposal_id: string;
      proposal_name: string;
      priority_score: number;
      implementation_date?: Date;
      dependencies: string[];
      status: string;
      description?: string;
      implementation_effort?: string;
      expected_impact?: number;
      created_at?: string;
      updated_at?: string;
    }>;
    proposals: Array<{
      proposal_id: string;
      proposal_name: string;
      priority_score: number;
      implementation_date?: Date;
      dependencies: string[];
      status: string;
      description?: string;
      implementation_effort?: string;
      expected_impact?: number;
      created_at?: string;
      updated_at?: string;
    }>;
  } {
    const total_proposals = proposalData.length;
  
    const proposals_by_status: Record<string, number> = {};
    let totalPriorityScore = 0;
  
    for (const proposal of proposalData) {
      proposals_by_status[proposal.status] =
        (proposals_by_status[proposal.status] || 0) + 1;
      totalPriorityScore += proposal.priority_score;
    }
  
    const average_priority_score =
      total_proposals > 0 ? totalPriorityScore / total_proposals : 0;
  
    const aggregated_proposals = proposalData
      .map((proposal) => ({
        proposal_id: proposal.proposal_id,
        proposal_name: proposal.proposal_name,
        priority_score: proposal.priority_score,
        implementation_date: proposal.implementation_date,
        dependencies: proposal.dependencies,
        status: proposal.status,
        description: proposal.description,
        implementation_effort: proposal.implementation_effort,
        expected_impact: proposal.expected_impact,
        created_at: proposal.created_at,
        updated_at: proposal.updated_at,
      }))
      .sort((a, b) => {
        const dateA = a.created_at ? new Date(a.created_at).getTime() : 0;
        const dateB = b.created_at ? new Date(b.created_at).getTime() : 0;
        return dateB - dateA;
      });
  
    return {
      total_proposals,
      proposals_by_status,
      average_priority_score,
      aggregated_proposals,
      proposals: aggregated_proposals,
    };
  }
  return { aggregateImprovementProposals };
})();
export const aggregateImprovementProposals: (...args: any[]) => any = (...args: any[]) => (__aivicBundle_105_aggregateImprovementProposals.aggregateImprovementProposals as (...args: any[]) => any)(...args);
