/* AIVIC_FUNCTION_BUNDLE_START owner=sortProposalsByPriority exports=sortProposalsByPriority */
const __aivicBundle_106_sortProposalsByPriority = (() => {
  function sortProposalsByPriority(
    proposals: ImprovementProposal[],
    sortOrder: 'asc' | 'desc' | 'ascending' | 'descending'
  ): ProposalWithPriority[] {
    const normalizedOrder = sortOrder === 'asc' || sortOrder === 'ascending' ? 'asc' : 'desc';
  
    const sorted = [...proposals].sort((a, b) => {
      if (normalizedOrder === 'desc') {
        return b.priorityScore - a.priorityScore;
      } else {
        return a.priorityScore - b.priorityScore;
      }
    });
  
    return sorted.map((proposal, index) => ({
      proposal_id: proposal.proposalId,
      proposal_name: proposal.proposalName,
      priority_rank: index + 1,
      priority_score: proposal.priorityScore,
      implementation_date: proposal.recommendedDeploymentPhase,
      status: 'approved',
    }));
  }
  return { sortProposalsByPriority };
})();
export const sortProposalsByPriority = __aivicBundle_106_sortProposalsByPriority.sortProposalsByPriority;
/* AIVIC_FUNCTION_BUNDLE_END owner=sortProposalsByPriority */

/* AIVIC_FUNCTION_BUNDLE_START owner=sortProposalsByImplementationDate exports=sortProposalsByImplementationDate */
const __aivicBundle_107_sortProposalsByImplementationDate = (() => {
  function sortProposalsByImplementationDate(
    proposals: any[],
    sortOrder: 'asc' | 'desc' | 'ascending' | 'descending'
  ): ProposalWithPriority[] {
    if (!proposals || proposals.length === 0) {
      return [];
    }
  
    // Normalize sort order
    const isAscending = sortOrder === 'asc' || sortOrder === 'ascending';
  
    // Sort proposals by implementation_date
    const sorted = [...proposals].sort((a, b) => {
      const dateA = a.implementation_date instanceof Date 
        ? a.implementation_date 
        : new Date(a.implementation_date);
      const dateB = b.implementation_date instanceof Date 
        ? b.implementation_date 
        : new Date(b.implementation_date);
  
      if (isAscending) {
        return dateA.getTime() - dateB.getTime();
      } else {
        return dateB.getTime() - dateA.getTime();
      }
    });
  
    // Assign priority ranks starting from 1
    return sorted.map((proposal, index) => ({
      proposal_id: proposal.proposal_id,
      proposal_name: proposal.proposal_name,
      priority_rank: index + 1,
      priority_score: proposal.priority_score,
      implementation_date: proposal.implementation_date instanceof Date 
        ? proposal.implementation_date 
        : new Date(proposal.implementation_date),
      status: proposal.status,
      dependencies: proposal.dependencies || [],
    }));
  }
  return { sortProposalsByImplementationDate };
})();
export const sortProposalsByImplementationDate = __aivicBundle_107_sortProposalsByImplementationDate.sortProposalsByImplementationDate;
/* AIVIC_FUNCTION_BUNDLE_END owner=sortProposalsByImplementationDate */

/* AIVIC_FUNCTION_BUNDLE_START owner=validateDependencyChain exports=validateDependencyChain */
const __aivicBundle_108_validateDependencyChain = (() => {
  function validateDependencyChain(
    proposals: any[]
  ): DependencyChainValidation {
    if (!Array.isArray(proposals)) {
      return {
        is_valid: false,
        circular_dependencies: [],
        missing_dependencies: [],
        execution_order: [],
        validation_errors: ["Input must be an array of proposals"],
      };
    }
  
    const proposalMap = new Map<string, any>();
    const dependencyMap = new Map<string, string[]>();
  
    // Build proposal map and dependency map
    for (const proposal of proposals) {
      if (!proposal.proposal_id) {
        return {
          is_valid: false,
          circular_dependencies: [],
          missing_dependencies: [],
          execution_order: [],
          validation_errors: ["Proposal missing proposal_id"],
        };
      }
      proposalMap.set(proposal.proposal_id, proposal);
      const deps = Array.isArray(proposal.dependencies)
        ? proposal.dependencies
        : [];
      dependencyMap.set(proposal.proposal_id, deps);
    }
  
    // Detect circular dependencies using DFS
    const circularDeps: string[] = [];
    const visited = new Set<string>();
    const recursionStack = new Set<string>();
  
    const hasCycle = (nodeId: string): boolean => {
      visited.add(nodeId);
      recursionStack.add(nodeId);
  
      const deps = dependencyMap.get(nodeId) || [];
      for (const dep of deps) {
        if (!visited.has(dep)) {
          if (hasCycle(dep)) {
            return true;
          }
        } else if (recursionStack.has(dep)) {
          if (!circularDeps.includes(nodeId)) {
            circularDeps.push(nodeId);
          }
          if (!circularDeps.includes(dep)) {
            circularDeps.push(dep);
          }
          return true;
        }
      }
  
      recursionStack.delete(nodeId);
      return false;
    };
  
    for (const proposalId of proposalMap.keys()) {
      if (!visited.has(proposalId)) {
        hasCycle(proposalId);
      }
    }
  
    // Check for missing dependencies
    const missingDeps: string[] = [];
    for (const [proposalId, deps] of dependencyMap.entries()) {
      for (const dep of deps) {
        if (!proposalMap.has(dep)) {
          if (!missingDeps.includes(dep)) {
            missingDeps.push(dep);
          }
        }
      }
    }
  
    // Topological sort to determine execution order
    const executionOrder: string[] = [];
    const inDegree = new Map<string, number>();
    const adjList = new Map<string, string[]>();
  
    // Initialize
    for (const proposalId of proposalMap.keys()) {
      inDegree.set(proposalId, 0);
      adjList.set(proposalId, []);
    }
  
    // Build adjacency list and calculate in-degrees
    for (const [proposalId, deps] of dependencyMap.entries()) {
      for (const dep of deps) {
        if (proposalMap.has(dep)) {
          const current = adjList.get(dep) || [];
          current.push(proposalId);
          adjList.set(dep, current);
          inDegree.set(proposalId, (inDegree.get(proposalId) || 0) + 1);
        }
      }
    }
  
    // Kahn's algorithm for topological sort
    const queue: string[] = [];
    for (const [proposalId, degree] of inDegree.entries()) {
      if (degree === 0) {
        queue.push(proposalId);
      }
    }
  
    while (queue.length > 0) {
      const current = queue.shift()!;
      executionOrder.push(current);
  
      const neighbors = adjList.get(current) || [];
      for (const neighbor of neighbors) {
        const newDegree = (inDegree.get(neighbor) || 0) - 1;
        inDegree.set(neighbor, newDegree);
        if (newDegree === 0) {
          queue.push(neighbor);
        }
      }
    }
  
    const isValid =
      circularDeps.length === 0 &&
      missingDeps.length === 0 &&
      executionOrder.length === proposalMap.size;
  
    const validationErrors: string[] = [];
    if (circularDeps.length > 0) {
      validationErrors.push(
        `Circular dependencies detected: ${circularDeps.join(", ")}`
      );
    }
    if (missingDeps.length > 0) {
      validationErrors.push(
        `Missing dependencies: ${missingDeps.join(", ")}`
      );
    }
    if (executionOrder.length !== proposalMap.size) {
      validationErrors.push("Not all proposals can be ordered due to cycles");
    }
  
    return {
      is_valid: isValid,
      circular_dependencies: circularDeps,
      missing_dependencies: missingDeps,
      execution_order: executionOrder,
      validation_errors: validationErrors,
    };
  }
  return { validateDependencyChain };
})();
export const validateDependencyChain = __aivicBundle_108_validateDependencyChain.validateDependencyChain;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateDependencyChain */

/* AIVIC_FUNCTION_BUNDLE_START owner=reflectProposalUpdate exports=reflectProposalUpdate */
const __aivicBundle_109_reflectProposalUpdate = (() => {
  function reflectProposalUpdate(
    proposals: ImprovementProposal[],
    updateData: {
      proposal_id?: string;
      proposal_name?: string;
      priority_score?: number;
      new_priority_score?: number;
      implementation_date?: string | Date;
      new_implementation_date?: string | Date;
      dependencies?: string[];
      status?: string;
      new_status?: string;
    }
  ): ImprovementProposal[] {
    if (!Array.isArray(proposals)) {
      return proposals as unknown as ImprovementProposal[];
    }
  
    return proposals.map((proposal) => {
      const updated: ImprovementProposal = {
        ...proposal,
      };
  
      const priorityScore = updateData.new_priority_score ?? updateData.priority_score;
      if (priorityScore !== undefined) {
        updated.priorityScore = priorityScore;
      }
  
      const status = updateData.new_status ?? updateData.status;
      if (status !== undefined) {
        updated.status = status;
      }
  
      const implDate = updateData.new_implementation_date ?? updateData.implementation_date;
      if (implDate !== undefined) {
        const dateValue = implDate;
        updated.implementation_date =
          dateValue instanceof Date ? dateValue : new Date(dateValue as string);
      }
  
      if (updateData.dependencies !== undefined) {
        updated.dependencies = updateData.dependencies;
      }
  
      return updated;
    });
  }
  return { reflectProposalUpdate };
})();
