/* AIVIC_FUNCTION_BUNDLE_START owner=calculateDependentSchedules exports=calculateDependentSchedules */
const __aivicBundle_110_calculateDependentSchedules = (() => {
  function calculateDependentSchedules(
    proposals: Array<{
      proposalId: string;
      proposalName?: string;
      dependsOn?: string | null;
      scheduledDate: Date;
      status?: 'pending' | 'completed';
      completedDate?: Date | null;
    }>
  ): Array<{
    proposalId: string;
    scheduledDate?: Date;
    adjustedScheduledDate: Date;
    status?: 'pending' | 'completed';
    completedDate?: Date | null;
  }> {
    if (!proposals || proposals.length === 0) {
      return [];
    }
  
    const proposalMap = new Map(proposals.map(p => [p.proposalId, p]));
    const result: Array<{
      proposalId: string;
      scheduledDate?: Date;
      adjustedScheduledDate: Date;
      status?: 'pending' | 'completed';
      completedDate?: Date | null;
    }> = [];
  
    const calculateAdjustedDate = (proposal: typeof proposals[0]): Date => {
      if (!proposal.dependsOn) {
        return proposal.scheduledDate;
      }
  
      const dependency = proposalMap.get(proposal.dependsOn);
      if (!dependency) {
        return proposal.scheduledDate;
      }
  
      let dependencyEndDate: Date;
  
      if (dependency.status === 'completed' && dependency.completedDate) {
        dependencyEndDate = new Date(dependency.completedDate);
      } else {
        const dependencyAdjusted = calculateAdjustedDate(dependency);
        dependencyEndDate = new Date(dependencyAdjusted);
      }
  
      const proposedDate = new Date(proposal.scheduledDate);
  
      if (proposedDate <= dependencyEndDate) {
        const adjustedDate = new Date(dependencyEndDate);
        adjustedDate.setDate(adjustedDate.getDate() + 1);
        return adjustedDate;
      }
  
      return proposedDate;
    };
  
    for (const proposal of proposals) {
      const adjustedScheduledDate = calculateAdjustedDate(proposal);
  
      result.push({
        proposalId: proposal.proposalId,
        scheduledDate: proposal.scheduledDate,
        adjustedScheduledDate,
        status: proposal.status,
        completedDate: proposal.completedDate || null
      });
    }
  
    return result;
  }
  return { calculateDependentSchedules };
})();
export const calculateDependentSchedules = __aivicBundle_110_calculateDependentSchedules.calculateDependentSchedules;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateDependentSchedules */

/* AIVIC_FUNCTION_BUNDLE_START owner=updateProposalScheduleWithDependencies exports=updateProposalScheduleWithDependencies */
const __aivicBundle_111_updateProposalScheduleWithDependencies = (() => {
  function updateProposalScheduleWithDependencies(
    proposals: any[],
    proposalId: string,
    requestedScheduledDate: Date
  ): ScheduleUpdate & {
    proposalId: string;
    requestedScheduledDate: Date;
    adjustedScheduledDate: Date;
    adjustmentReason: string;
  } {
    // Find the target proposal
    const targetProposal = proposals.find((p) => p.proposalId === proposalId);
    if (!targetProposal) {
      return {
        proposal_id: proposalId,
        new_implementation_date: requestedScheduledDate.toISOString(),
        dependent_proposals: [],
        schedule_conflict: false,
        conflict_details: '',
        proposalId: proposalId,
        requestedScheduledDate: requestedScheduledDate,
        adjustedScheduledDate: requestedScheduledDate,
        adjustmentReason: ''
      };
    }
  
    // Build dependency chain: collect all proposals this one depends on (transitively)
    const dependencyChain: any[] = [];
    const visited = new Set<string>();
  
    function collectDependencies(propId: string) {
      if (visited.has(propId)) return;
      visited.add(propId);
  
      const prop = proposals.find((p) => p.proposalId === propId);
      if (!prop) return;
  
      if (prop.dependsOn) {
        dependencyChain.push(prop.dependsOn);
        collectDependencies(prop.dependsOn);
      }
    }
  
    collectDependencies(proposalId);
  
    // Calculate the earliest date this proposal can be scheduled
    // by walking up the dependency chain and finding the latest completion/scheduled date
    let adjustedDate = new Date(requestedScheduledDate);
    let hasConflict = false;
    let conflictDetails = '';
  
    for (const depId of dependencyChain) {
      const depProposal = proposals.find((p) => p.proposalId === depId);
      if (!depProposal) continue;
  
      // Determine when the dependency will be completed
      let depCompletionDate: Date;
      if (depProposal.status === 'completed' && depProposal.completedDate) {
        depCompletionDate = new Date(depProposal.completedDate);
      } else {
        // Use scheduled date or adjusted scheduled date if available
        depCompletionDate = depProposal.adjustedScheduledDate
          ? new Date(depProposal.adjustedScheduledDate)
          : new Date(depProposal.scheduledDate);
      }
  
      // The target proposal must start after the dependency completes
      const earliestStart = new Date(depCompletionDate);
      earliestStart.setDate(earliestStart.getDate() + 1);
  
      if (adjustedDate < earliestStart) {
        adjustedDate = new Date(earliestStart);
      }
  
      // Check for conflict: if requested date is before dependency completion
      if (requestedScheduledDate < depCompletionDate) {
        hasConflict = true;
        conflictDetails = `${depId} の終了日が ${proposalId} の開始日より後`;
      }
    }
  
    // Determine adjustment reason
    let adjustmentReason = '';
    if (adjustedDate.getTime() !== requestedScheduledDate.getTime()) {
      adjustmentReason = dependencyChain.length > 0 ? '依存元の完了を待つため実装予定時期を延期' : '';
    }
  
    return {
      proposal_id: proposalId,
      new_implementation_date: adjustedDate.toISOString(),
      dependent_proposals: dependencyChain,
      schedule_conflict: hasConflict,
      conflict_details: conflictDetails,
      proposalId: proposalId,
      requestedScheduledDate: requestedScheduledDate,
      adjustedScheduledDate: adjustedDate,
      adjustmentReason: adjustmentReason
    };
  }
  return { updateProposalScheduleWithDependencies };
})();
