/* AIVIC_FUNCTION_BUNDLE_START owner=detectCircularDependencies exports=detectCircularDependencies */
const __aivicBundle_112_detectCircularDependencies = (() => {
  function detectCircularDependencies(
    proposals: Array<{
      proposal_id: string;
      proposal_name: string;
      depends_on?: string[];
    }>
  ): { has_cycle: boolean; cycle_path: string[]; validated_at: string } {
    const dependencyMap = new Map<string, string[]>();
    const proposalIds = new Set<string>();
  
    // Build dependency map and validate all proposals exist
    for (const proposal of proposals) {
      proposalIds.add(proposal.proposal_id);
      dependencyMap.set(proposal.proposal_id, proposal.depends_on || []);
    }
  
    // Validate that all dependencies reference existing proposals
    for (const [proposalId, dependencies] of dependencyMap.entries()) {
      for (const dep of dependencies) {
        if (!proposalIds.has(dep)) {
          throw new Error(`提案 ${proposalId} が存在しない提案 ${dep} に依存しています`);
        }
      }
    }
  
    // DFS to detect cycles
    const visited = new Set<string>();
    const recursionStack = new Set<string>();
    let detectedCycle: string[] | null = null;
  
    const dfs = (nodeId: string, path: string[]): boolean => {
      visited.add(nodeId);
      recursionStack.add(nodeId);
      const currentPath = [...path, nodeId];
  
      const dependencies = dependencyMap.get(nodeId) || [];
      for (const dep of dependencies) {
        if (!visited.has(dep)) {
          if (dfs(dep, currentPath)) {
            return true;
          }
        } else if (recursionStack.has(dep)) {
          // Cycle detected
          const cycleStartIndex = currentPath.indexOf(dep);
          detectedCycle = [...currentPath.slice(cycleStartIndex), dep];
          return true;
        }
      }
  
      recursionStack.delete(nodeId);
      return false;
    };
  
    // Check all nodes for cycles
    for (const proposalId of proposalIds) {
      if (!visited.has(proposalId)) {
        if (dfs(proposalId, [])) {
          break;
        }
      }
    }
  
    if (detectedCycle) {
      const cycleString = detectedCycle.join(' → ');
      throw new Error(`循環依存が検出されました: ${cycleString}`);
    }
  
    return {
      has_cycle: false,
      cycle_path: [],
      validated_at: new Date().toISOString()
    };
  }
  return { detectCircularDependencies };
})();
export const detectCircularDependencies = __aivicBundle_112_detectCircularDependencies.detectCircularDependencies;
/* AIVIC_FUNCTION_BUNDLE_END owner=detectCircularDependencies */

/* AIVIC_FUNCTION_BUNDLE_START owner=determineNextValidationTiming exports=determineNextValidationTiming */
const __aivicBundle_113_determineNextValidationTiming = (() => {
  interface DetermineNextValidationTimingInput {
    current_validation_cycle_end_date: Date;
    previous_validation_result_avg_accuracy: number;
    validation_items_completed_count: number;
    validation_items_total_count: number;
    algorithm_improvement_proposals_submitted_count: number;
    prior_month_validation_frequency_days: number;
  }
  
  interface DetermineNextValidationTimingResult {
    next_validation_execution_date: Date;
    validation_frequency_days: number;
    decision_rationale: string;
    validation_criteria_met: boolean;
    all_items_completed: boolean;
    improvement_proposals_count: number;
    scheduler_reflection_status: string;
    decision_timestamp: Date;
  }
  
   function determineNextValidationTiming(
    input: DetermineNextValidationTimingInput
  ): DetermineNextValidationTimingResult {
    const {
      current_validation_cycle_end_date,
      previous_validation_result_avg_accuracy,
      validation_items_completed_count,
      validation_items_total_count,
      algorithm_improvement_proposals_submitted_count,
      prior_month_validation_frequency_days,
    } = input;
  
    const completionRate =
      (validation_items_completed_count / validation_items_total_count) * 100;
    const allItemsCompleted = completionRate === 100;
    const accuracyThresholdMet = previous_validation_result_avg_accuracy >= 70;
    const improvementProposalsExist =
      algorithm_improvement_proposals_submitted_count > 0;
  
    const validationCriteriaMet =
      allItemsCompleted && accuracyThresholdMet && improvementProposalsExist;
  
    let validationFrequencyDays = prior_month_validation_frequency_days;
    let rationale = '';
  
    if (previous_validation_result_avg_accuracy >= 85) {
      validationFrequencyDays = 30;
      rationale = `High accuracy (${previous_validation_result_avg_accuracy}%) maintained. Monthly validation cycle continues.`;
    } else if (previous_validation_result_avg_accuracy >= 75) {
      validationFrequencyDays = 14;
      rationale = `Moderate accuracy (${previous_validation_result_avg_accuracy}%). Bi-weekly validation recommended.`;
    } else {
      validationFrequencyDays = 7;
      rationale = `Lower accuracy (${previous_validation_result_avg_accuracy}%). Weekly validation required for improvement.`;
    }
  
    const nextExecutionDate = new Date(current_validation_cycle_end_date);
    nextExecutionDate.setDate(nextExecutionDate.getDate() + 1);
    nextExecutionDate.setHours(9, 0, 0, 0);
  
    const schedulerReflectionStatus = validationCriteriaMet
      ? 'reflected'
      : 'pending_review';
  
    const decisionTimestamp = new Date();
  
    return {
      next_validation_execution_date: nextExecutionDate,
      validation_frequency_days: validationFrequencyDays,
      decision_rationale: rationale,
      validation_criteria_met: validationCriteriaMet,
      all_items_completed: allItemsCompleted,
      improvement_proposals_count: algorithm_improvement_proposals_submitted_count,
      scheduler_reflection_status: schedulerReflectionStatus,
      decision_timestamp: decisionTimestamp,
    };
  }
  return { determineNextValidationTiming };
})();
