   function calculateNextVerificationTiming(
    input: CalculateNextVerificationTimingInput
  ): CalculateNextVerificationTimingResult {
    // Handle improvement proposal based timing
    if (
      input.improvementProposal &&
      input.previousVerificationDate &&
      input.baseVerificationCycle &&
      input.currentDate
    ) {
      const priority = input.improvementProposal.priority || 'medium';
      const expectedEffect = input.improvementProposal.expectedEffect || 0;
  
      let adjustedCycle = input.baseVerificationCycle;
      let cycleAdjustmentReason = 'standard_cycle';
  
      if (priority === 'high' && expectedEffect >= 0.7) {
        adjustedCycle = 5;
        cycleAdjustmentReason = 'high_priority_proposal';
      } else if (priority === 'medium' && expectedEffect >= 0.4 && expectedEffect < 0.7) {
        adjustedCycle = input.baseVerificationCycle;
        cycleAdjustmentReason = 'standard_cycle';
      } else if (priority === 'low' || expectedEffect < 0.4) {
        adjustedCycle = 10;
        cycleAdjustmentReason = 'low_priority_proposal';
      }
  
      const nextDate = new Date(input.currentDate);
      nextDate.setDate(nextDate.getDate() + adjustedCycle);
  
      return {
        nextVerificationDate: nextDate,
        adjustedCycle,
        cycleAdjustmentReason,
      };
    }
  
    // Handle default frequency based timing
    if (
      input.lastVerificationTime !== undefined &&
      input.currentTime &&
      input.defaultVerificationFrequencyDays !== undefined
    ) {
      let frequencyDays = input.defaultVerificationFrequencyDays;
      let usedDefaultFrequency = false;
      let reason = '';
      let fallbackFrequencyDays: number | undefined;
  
      // Validate lastVerificationTime
      if (input.lastVerificationTime === null) {
        usedDefaultFrequency = true;
        reason = 'デフォルト検証頻度を使用します';
        frequencyDays = input.defaultVerificationFrequencyDays;
      } else if (!(input.lastVerificationTime instanceof Date) || isNaN(input.lastVerificationTime.getTime())) {
        usedDefaultFrequency = true;
        reason = '不正な時刻形式です。デフォルト検証頻度を使用します';
        frequencyDays = input.defaultVerificationFrequencyDays;
      } else if (input.lastVerificationTime.getTime() < input.currentTime.getTime() - 365 * 24 * 60 * 60 * 1000) {
        // Check if verification time is too far in the past (more than 1 year)
        usedDefaultFrequency = true;
        reason = 'デフォルト検証頻度を使用します';
        frequencyDays = input.defaultVerificationFrequencyDays;
      } else if (input.lastVerificationTime > input.currentTime) {
        usedDefaultFrequency = true;
        reason = '経過時間が不正です。デフォルト検証頻度を使用します';
        frequencyDays = input.defaultVerificationFrequencyDays;
      }
  
      // Validate frequency days
      if (frequencyDays <= 0) {
        usedDefaultFrequency = true;
        fallbackFrequencyDays = 30;
        frequencyDays = 30;
      }
  
      const nextTiming = new Date(input.currentTime);
      nextTiming.setDate(nextTiming.getDate() + frequencyDays);
  
      return {
        nextVerificationTiming: nextTiming,
        usedDefaultFrequency,
        reason,
        fallbackFrequencyDays,
      };
    }
  
    // Default fallback
    return {
      nextVerificationDate: new Date(),
      adjustedCycle: 7,
      cycleAdjustmentReason: 'standard_cycle',
      verificationCycle: '7日間',
      triggerCondition: '定期検証',
      isEligible: true,
      recommendedAction: '通常検証実施',
    };
  }
  return { calculateNextVerificationTiming };
