/* AIVIC_FUNCTION_BUNDLE_START owner=decideNextVerificationTiming exports=decideNextVerificationTiming */
const __aivicBundle_115_decideNextVerificationTiming = (() => {
  interface DecideNextVerificationTimingInput {
    lastVerificationDate?: Date;
    verificationCount: number;
    currentFrequencyPerDay: number;
    maxFrequencyPerDay?: number;
    minIntervalDays?: number;
    maxIntervalDays?: number;
  }
  
  interface DecideNextVerificationTimingOutput {
    nextVerificationDate: string;
    decidedFrequencyPerDay: number;
    decidedIntervalDays: number;
    maxFrequencyPerDay: number;
    verificationCycle?: string;
    triggerCondition?: string;
    isEligible?: boolean;
    recommendedAction?: string;
  }
  
   function decideNextVerificationTiming(
    input: DecideNextVerificationTimingInput
  ): DecideNextVerificationTimingOutput {
    const maxFrequencyPerDay = input.maxFrequencyPerDay ?? 1;
    const minIntervalDays = input.minIntervalDays ?? 1;
    
  
    // 検証頻度を段階的に増加させる（最高値に向かって）
    // verificationCount が多いほど、より高い頻度に到達
    const frequencyIncrement = Math.min(
      0.1 * Math.log(input.verificationCount + 1),
      maxFrequencyPerDay
    );
    const decidedFrequencyPerDay = Math.min(
      input.currentFrequencyPerDay + frequencyIncrement,
      maxFrequencyPerDay
    );
  
    // 頻度から間隔を計算（頻度が高いほど間隔は短い）
    // decidedFrequencyPerDay = 1 の場合、間隔は 1 日
    // decidedFrequencyPerDay = 0.5 の場合、間隔は 2 日
    const decidedIntervalDays = Math.max(
      minIntervalDays,
      Math.round(1 / Math.max(decidedFrequencyPerDay, 0.01))
    );
  
    // 次回検証日時を計算
    const lastVerificationDate = input.lastVerificationDate ?? new Date();
    const nextVerificationDateObj = new Date(lastVerificationDate);
    nextVerificationDateObj.setDate(
      nextVerificationDateObj.getDate() + decidedIntervalDays
    );
    const nextVerificationDate = nextVerificationDateObj.toISOString();
  
    return {
      nextVerificationDate,
      decidedFrequencyPerDay,
      decidedIntervalDays,
      maxFrequencyPerDay,
      verificationCycle:
        decidedIntervalDays === 1
          ? '1日'
          : `${decidedIntervalDays}日`,
      triggerCondition: '定期検証',
      isEligible: true,
      recommendedAction: '検証実施',
    };
  }
  return { decideNextVerificationTiming };
})();
export const decideNextVerificationTiming = __aivicBundle_115_decideNextVerificationTiming.decideNextVerificationTiming;
/* AIVIC_FUNCTION_BUNDLE_END owner=decideNextVerificationTiming */

