/* AIVIC_FUNCTION_BUNDLE_START owner=judgeApprovalCriteria exports=judgeApprovalCriteria */
const __aivicBundle_118_judgeApprovalCriteria = (() => {
  interface JudgeApprovalCriteriaReport {
    report_id: string;
    verification_week: string;
    meal_plan_success_rate: number;
    cooking_time_reduction_rate: number;
    user_satisfaction_score: number;
    error_rate: number;
    nutrition_achievement_rate: number;
    [key: string]: any;
  }
  
  interface JudgeApprovalCriteriaApprovalCriteria {
    min_meal_plan_success_rate: number;
    min_cooking_time_reduction_rate: number;
    min_user_satisfaction_score: number;
    max_error_rate: number;
    min_nutrition_achievement_rate: number;
    [key: string]: any;
  }
  
  interface JudgeApprovalCriteriaJudgmentResult {
    approval_status: 'approved' | 'rejected';
    report_id: string;
    rejection_reasons?: string[];
    judgment_timestamp: string;
    [key: string]: any;
  }
  
   function judgeApprovalCriteria(
    report: JudgeApprovalCriteriaReport,
    criteria: JudgeApprovalCriteriaApprovalCriteria
  ): JudgeApprovalCriteriaJudgmentResult {
    if (!String(report.verification_week).trim()) {
      throw new Error('verification_week is required');
    }
  
    const rejectionReasons: string[] = [];
  
    if (report.meal_plan_success_rate < criteria.min_meal_plan_success_rate) {
      rejectionReasons.push('meal_plan_success_rate_below_threshold');
    }
  
    if (report.cooking_time_reduction_rate < criteria.min_cooking_time_reduction_rate) {
      rejectionReasons.push('cooking_time_reduction_rate_below_threshold');
    }
  
    if (report.user_satisfaction_score < criteria.min_user_satisfaction_score) {
      rejectionReasons.push('user_satisfaction_score_below_threshold');
    }
  
    if (report.error_rate > criteria.max_error_rate) {
      rejectionReasons.push('error_rate_exceeds_threshold');
    }
  
    if (report.nutrition_achievement_rate < criteria.min_nutrition_achievement_rate) {
      rejectionReasons.push('nutrition_achievement_rate_below_threshold');
    }
  
    const isApproved = rejectionReasons.length === 0;
    const judgmentTimestamp = new Date().toISOString();
  
    const result: JudgeApprovalCriteriaJudgmentResult = {
      approval_status: isApproved ? 'approved' : 'rejected',
      report_id: report.report_id,
      judgment_timestamp: judgmentTimestamp,
    };
  
    if (!isApproved) {
      result.rejection_reasons = rejectionReasons;
    }
  
    return result;
  }
  return { judgeApprovalCriteria };
})();
export const judgeApprovalCriteria: (...args: any[]) => any = (...args: any[]) => (__aivicBundle_118_judgeApprovalCriteria.judgeApprovalCriteria as (...args: any[]) => any)(...args);
