/* AIVIC_FUNCTION_BUNDLE_START owner=createVerificationReportAndJudge exports=createVerificationReportAndJudge */
const __aivicBundle_119_createVerificationReportAndJudge = (() => {
  interface CreateVerificationReportAndJudgeInput {
    algorithmVersion: string;
    verificationStartDate: Date;
    verificationEndDate: Date;
    mealGenerationSuccessRate: number;
    cookingTimeReductionDegree: number;
    userSatisfactionScore: number;
    passingCriterion: number;
    reportCreationDate: Date;
    reviewerUserId: string;
    businessImpactDescription: string;
    technicalDifficultyLevel: number;
    expectedKPIContribution: number;
  }
  
  interface CreateVerificationReportAndJudgeOutput {
    reportId: string;
    verificationScore: number;
    judgmentResult: 'APPROVED' | 'REJECTED';
    judgmentReason: string;
    createdAt: Date;
    algorithmPerformanceMetrics: {
      successRate: number;
      cookingTimeReductionDegree: number;
      userSatisfactionScore: number;
    };
    algorithmVersion: string;
    reviewerUserId: string;
  }
  
   function createVerificationReportAndJudge(
    input: CreateVerificationReportAndJudgeInput
  ): CreateVerificationReportAndJudgeOutput {
    const reportId = `REPORT-${randomUUID()}`;
    
    const verificationScore = input.mealGenerationSuccessRate;
    
    const isApproved = verificationScore >= input.passingCriterion;
    
    let judgmentReason: string;
    if (verificationScore > input.passingCriterion) {
      judgmentReason = `Score exceeds passing criterion: ${verificationScore} > ${input.passingCriterion}`;
    } else if (verificationScore === input.passingCriterion) {
      judgmentReason = `Score meets boundary criterion exactly: ${verificationScore} = ${input.passingCriterion}`;
    } else {
      judgmentReason = `Score falls below passing criterion: ${verificationScore} < ${input.passingCriterion}`;
    }
    
    return {
      reportId,
      verificationScore,
      judgmentResult: isApproved ? 'APPROVED' : 'REJECTED',
      judgmentReason,
      createdAt: input.reportCreationDate,
      algorithmPerformanceMetrics: {
        successRate: input.mealGenerationSuccessRate,
        cookingTimeReductionDegree: input.cookingTimeReductionDegree,
        userSatisfactionScore: input.userSatisfactionScore,
      },
      algorithmVersion: input.algorithmVersion,
      reviewerUserId: input.reviewerUserId,
    };
  }
  return { createVerificationReportAndJudge };
})();
export const createVerificationReportAndJudge = __aivicBundle_119_createVerificationReportAndJudge.createVerificationReportAndJudge;
