    // 改善率の最小値・最大値
    const improvementRateArray = Object.values(improvementRates);
    const minImprovementRate =
      improvementRateArray.length > 0
        ? Math.min(...improvementRateArray)
        : 0;
    const maxImprovementRate =
      improvementRateArray.length > 0
        ? Math.max(...improvementRateArray)
        : 0;
  
