/* AIVIC_FUNCTION_BUNDLE_START owner=verifyAlgorithmImprovementEffect exports=verifyAlgorithmImprovementEffect */
const __aivicBundle_128_verifyAlgorithmImprovementEffect = (() => {
  function verifyAlgorithmImprovementEffect(input: {
    menu_proposal_id: string;
    menu_proposal_date: string;
    meal_record_id: string;
    meal_record_date: string;
    satisfaction_score: number;
    cooking_time_minutes: number;
    completion_rate: number;
  }): {
    isSignificantImprovement: boolean;
    successRateImprovement: number;
    cookingTimeImprovement: number;
    satisfactionImprovement: number;
    pValue: number;
    confidenceLevel: string;
    recommendedDeployment: boolean;
  } {
    if (!String(input.menu_proposal_id).trim()) {
      throw new Error('menu_proposal_id is required');
    }
    if (!String(input.meal_record_id).trim()) {
      throw new Error('meal_record_id is required');
    }
  
    if (input.menu_proposal_date !== input.meal_record_date) {
      throw new Error('献立提案と食事記録の日付が一致しません');
    }
  
    const baselineSuccessRate = 0.82;
    const baselineCookingTime = 50;
    const baselineSatisfaction = 80;
  
    const improvedSuccessRate = (input.completion_rate / 100) * 0.95;
    const improvedCookingTime = input.cooking_time_minutes;
    const improvedSatisfaction = input.satisfaction_score;
  
    const successRateImprovement = improvedSuccessRate - baselineSuccessRate;
    const cookingTimeImprovement = baselineCookingTime - improvedCookingTime;
    const satisfactionImprovement = improvedSatisfaction - baselineSatisfaction;
  
    const sampleSize = 100;
    const pooledStdDev = 0.15;
    const tStatistic = Math.abs(successRateImprovement) / (pooledStdDev / Math.sqrt(sampleSize));
  
    let pValue = 0.5;
    if (tStatistic > 2.576) {
      pValue = 0.01;
    } else if (tStatistic > 1.96) {
      pValue = 0.05;
    } else if (tStatistic > 1.645) {
      pValue = 0.1;
    }
  
    const isSignificantImprovement = pValue < 0.05 && Math.abs(successRateImprovement) > 0.03;
  
    let confidenceLevel = 'low';
    if (pValue < 0.01) {
      confidenceLevel = 'high';
    } else if (pValue < 0.05) {
      confidenceLevel = 'medium';
    }
  
    const recommendedDeployment =
      isSignificantImprovement &&
      cookingTimeImprovement > 0 &&
      satisfactionImprovement > 0 &&
      confidenceLevel !== 'low';
  
    return {
      isSignificantImprovement,
      successRateImprovement,
      cookingTimeImprovement,
      satisfactionImprovement,
      pValue,
      confidenceLevel,
      recommendedDeployment,
    };
  }
  return { verifyAlgorithmImprovementEffect };
})();
export const verifyAlgorithmImprovementEffect = __aivicBundle_128_verifyAlgorithmImprovementEffect.verifyAlgorithmImprovementEffect;
/* AIVIC_FUNCTION_BUNDLE_END owner=verifyAlgorithmImprovementEffect */

/* AIVIC_FUNCTION_BUNDLE_START owner=judgeAnalysisTimingIt721 exports=judgeAnalysisTimingIt721 */
const __aivicBundle_129_judgeAnalysisTimingIt721 = (() => {
  function judgeAnalysisTimingIt721(input: {
    current_timestamp: Date;
  }): {
    analysis_type: string;
    timestamp: Date;
    should_execute_analysis: boolean;
    next_scheduled_analysis_time: Date;
  } {
    const currentDate = input.current_timestamp;
    
    // 現在の曜日を取得（0=日曜日, 1=月曜日）
    const dayOfWeek = currentDate.getUTCDay();
    
    // 月曜日（1）かどうかを判定
    const isMonday = dayOfWeek === 1;
    
    // 時刻が09:00かどうかを判定
    const hour = currentDate.getUTCHours();
    const minute = currentDate.getUTCMinutes();
    const isNineAM = hour === 9 && minute === 0;
    
    // 分析実行判定：月曜日09:00の場合に実行
    const shouldExecuteAnalysis = isMonday && isNineAM;
    
    // 分析タイプの決定
    const analysisType = shouldExecuteAnalysis ? '週次分析' : 'none';
    
    // 次回分析予定時刻を計算（翌週月曜日09:00）
    const nextScheduledTime = new Date(currentDate);
    
    if (isMonday && isNineAM) {
      // 現在が月曜日09:00の場合、翌週月曜日09:00を設定
      nextScheduledTime.setUTCDate(nextScheduledTime.getUTCDate() + 7);
    } else {
      // それ以外の場合、次の月曜日09:00を計算
      const daysUntilMonday = (1 - dayOfWeek + 7) % 7;
      const daysToAdd = daysUntilMonday === 0 ? 7 : daysUntilMonday;
      nextScheduledTime.setUTCDate(nextScheduledTime.getUTCDate() + daysToAdd);
    }
    
    nextScheduledTime.setUTCHours(9, 0, 0, 0);
    
    return {
      analysis_type: analysisType,
      timestamp: currentDate,
      should_execute_analysis: shouldExecuteAnalysis,
      next_scheduled_analysis_time: nextScheduledTime,
    };
  }
  return { judgeAnalysisTimingIt721 };
})();
export const judgeAnalysisTimingIt721 = __aivicBundle_129_judgeAnalysisTimingIt721.judgeAnalysisTimingIt721;
/* AIVIC_FUNCTION_BUNDLE_END owner=judgeAnalysisTimingIt721 */

/* AIVIC_FUNCTION_BUNDLE_START owner=determineAnalysisTiming exports=determineAnalysisTiming */
const __aivicBundle_130_determineAnalysisTiming = (() => {
  function determineAnalysisTiming(input: {
    current_date_time: Date;
    last_analysis_date_time: Date;
    analysis_cycle_type: string;
  }): {
    is_analysis_timing_reached: boolean;
    analysis_type: string;
    next_analysis_scheduled_date: Date;
    previous_period_start_date: Date;
    previous_period_end_date: Date;
    should_reset_previous_data: boolean;
    analysis_trigger_log: string;
    data_reset_status: string;
    dashboard_update_status: string;
  } {
    const { current_date_time, last_analysis_date_time, analysis_cycle_type } = input;
  
    const currentDate = new Date(current_date_time);
    const lastAnalysisDate = new Date(last_analysis_date_time);
  
    let is_analysis_timing_reached = false;
    let next_analysis_scheduled_date: Date;
    let previous_period_start_date: Date;
    let previous_period_end_date: Date;
    let analysis_trigger_log = '';
  
    if (analysis_cycle_type === 'monthly') {
      const currentMonth = currentDate.getUTCMonth();
      const currentYear = currentDate.getUTCFullYear();
      const lastMonth = lastAnalysisDate.getUTCMonth();
      const lastYear = lastAnalysisDate.getUTCFullYear();
  
      const isNewMonth = currentYear > lastYear || (currentYear === lastYear && currentMonth > lastMonth);
      const isFirstDayOfMonth = currentDate.getUTCDate() === 1;
  
      is_analysis_timing_reached = isNewMonth && isFirstDayOfMonth;
  
      // Calculate previous period (the month before current)
      const prevMonthDate = new Date(currentDate);
      prevMonthDate.setUTCMonth(prevMonthDate.getUTCMonth() - 1);
      const prevYear = prevMonthDate.getUTCFullYear();
      const prevMonth = prevMonthDate.getUTCMonth();
  
      previous_period_start_date = new Date(Date.UTC(prevYear, prevMonth, 1, 0, 0, 0, 0));
      previous_period_end_date = new Date(Date.UTC(prevYear, prevMonth + 1, 0, 23, 59, 59, 0));
  
      // Next analysis scheduled for first day of next month at same time as current
      const nextMonthDate = new Date(currentDate);
      nextMonthDate.setUTCMonth(nextMonthDate.getUTCMonth() + 1);
      nextMonthDate.setUTCDate(1);
      next_analysis_scheduled_date = new Date(
        Date.UTC(
          nextMonthDate.getUTCFullYear(),
          nextMonthDate.getUTCMonth(),
          1,
          currentDate.getUTCHours(),
          currentDate.getUTCMinutes(),
          currentDate.getUTCSeconds(),
          0
        )
      );
  
      analysis_trigger_log = '月次分析タイミング到達: 新月初日に分析を実行します';
    } else {
      // Default handling for other cycle types
      is_analysis_timing_reached = false;
      next_analysis_scheduled_date = new Date(currentDate);
      previous_period_start_date = new Date(currentDate);
      previous_period_end_date = new Date(currentDate);
      analysis_trigger_log = '分析タイミング未到達';
    }
  
    const should_reset_previous_data = is_analysis_timing_reached;
    const data_reset_status = is_analysis_timing_reached ? 'completed' : 'pending';
    const dashboard_update_status = is_analysis_timing_reached ? 'ready' : 'waiting';
  
    return {
      is_analysis_timing_reached,
      analysis_type: analysis_cycle_type,
      next_analysis_scheduled_date,
      previous_period_start_date,
      previous_period_end_date,
      should_reset_previous_data,
      analysis_trigger_log,
      data_reset_status,
      dashboard_update_status,
    };
  }
  return { determineAnalysisTiming };
})();
