const __aivicBundle_131_analyzeWeeklyMetrics = (() => {
  interface AnalyzeWeeklyMetricsInput {
    currentTimeUnixMs: number;
    previousMetricsSnapshot: {
      generationSuccessRate: number;
      cookingTimeReductionDegree: number;
      userSatisfactionScore: number;
      weekStartDate: string;
    };
    algorithmVersionId: string;
    analysisSchedule: {
      targetDayOfWeek: number;
      targetHourUtc: number;
    };
  }
  
  interface AnalyzeWeeklyMetricsOutput {
    shouldExecuteAnalysis: boolean;
    status: 'SKIPPED' | 'EXECUTED';
    skipReason?: string;
    metricsSnapshot?: WeeklyMetricsResult;
    comparisonResult?: {
      successRateImprovement: number;
      cookingTimeReductionImprovement: number;
      satisfactionScoreImprovement: number;
    };
  }
  
   function analyzeWeeklyMetrics(
    input: AnalyzeWeeklyMetricsInput
  ): AnalyzeWeeklyMetricsOutput {
    const currentDate = new Date(input.currentTimeUnixMs);
    const currentDayOfWeek = currentDate.getUTCDay();
    const currentHourUtc = currentDate.getUTCHours();
    const currentMinutesUtc = currentDate.getUTCMinutes();
  
    const targetDayOfWeek = input.analysisSchedule.targetDayOfWeek;
    const targetHourUtc = input.analysisSchedule.targetHourUtc;
  
    const isDayMatched = currentDayOfWeek === targetDayOfWeek;
    const isTimeReached = currentHourUtc > targetHourUtc || 
      (currentHourUtc === targetHourUtc && currentMinutesUtc >= 0);
  
    if (!isDayMatched || !isTimeReached) {
      return {
        shouldExecuteAnalysis: false,
        status: 'SKIPPED',
        skipReason: '時刻未到達またはthreshold条件を満たしていません',
        metricsSnapshot: undefined,
        comparisonResult: undefined,
      };
    }
  
    return {
      shouldExecuteAnalysis: true,
      status: 'EXECUTED',
      metricsSnapshot: {
        weekStartDate: input.previousMetricsSnapshot.weekStartDate,
        weekEndDate: new Date(input.currentTimeUnixMs).toISOString(),
        mealGenerationSuccessRate: input.previousMetricsSnapshot.generationSuccessRate,
        averageCookingTimeReduction: input.previousMetricsSnapshot.cookingTimeReductionDegree,
        averageSatisfactionScore: input.previousMetricsSnapshot.userSatisfactionScore,
        totalMealsEvaluated: 0,
        averageCompletionRate: 0,
      },
      comparisonResult: {
        successRateImprovement: 0,
        cookingTimeReductionImprovement: 0,
        satisfactionScoreImprovement: 0,
      },
    };
  }
  return { analyzeWeeklyMetrics };
})();
