/* AIVIC_FUNCTION_BUNDLE_START owner=calculatePredictionAccuracy exports=calculatePredictionAccuracy */
const __aivicBundle_132_calculatePredictionAccuracy = (() => {
  interface CalculatePredictionAccuracyInput {
    predicted_values?: number[];
    actual_values?: number[];
    category?: string;
    predicted_quantity?: number;
    actual_quantity?: number;
    predicted_demand?: number;
    actual_demand?: number;
  }
  
  interface PredictionAccuracyDashboard {
    accuracy_rate: number;
    deviation_rate: number;
    category_count: number;
    total_records: number;
    generated_at: string;
  }
  
  interface PredictionAccuracyExport {
    accuracy_rate: number;
    deviation_rate: number;
    category_errors: Record<string, number>;
    timestamp: string;
    data_source: string;
  }
  
  interface CalculatePredictionAccuracyOutput {
    accuracy_rate?: number;
    deviation_rate?: number;
    category_errors?: Record<string, number>;
    dashboard_display?: PredictionAccuracyDashboard;
    export_data?: PredictionAccuracyExport;
    overallAccuracy?: number;
    rmse?: number;
    mae?: number;
    mape?: number;
    categoryAccuracy?: Record<string, number>;
    deviationByWeek?: Array<{ week_id: number; deviation_rate: number; external_factors_detected: string[] }>;
    pValue?: number;
  }
  
   function calculatePredictionAccuracy(
    input: Record<string, number[]> | Array<CalculatePredictionAccuracyInput> | any
  ): CalculatePredictionAccuracyOutput | number {
    // Handle case: predicted_values and actual_values as direct arrays
    if (
      input &&
      typeof input === 'object' &&
      !Array.isArray(input) &&
      'predicted_values' in input &&
      'actual_values' in input &&
      Array.isArray(input.predicted_values) &&
      Array.isArray(input.actual_values)
    ) {
      const predicted = input.predicted_values as number[];
      const actual = input.actual_values as number[];
  
      if (predicted.length === 0 || actual.length === 0) {
        return 100;
      }
  
      // Check if arrays are identical
      const isIdentical = predicted.length === actual.length && predicted.every((v, i) => v === actual[i]);
      if (isIdentical) {
        return 100;
      }
  
      // Calculate MAE and MAPE
      let totalAbsError = 0;
      let totalPercentError = 0;
      const minLen = Math.min(predicted.length, actual.length);
  
      for (let i = 0; i < minLen; i++) {
        const absError = Math.abs(predicted[i] - actual[i]);
        totalAbsError += absError;
        if (actual[i] !== 0) {
          totalPercentError += (absError / actual[i]) * 100;
        }
      }
  
      const mae = totalAbsError / minLen;
      
      const avgActual = actual.reduce((a, b) => a + b, 0) / minLen;
      const accuracyRate = Math.max(0, 100 - (mae / avgActual) * 100);
  
      return accuracyRate;
    }
  
    // Handle case: array of category records
    if (Array.isArray(input) && input.length > 0) {
      const records = input as Array<{
        category: string;
        predicted_quantity: number;
        actual_quantity: number;
        predicted_demand: number;
        actual_demand: number;
      }>;
  
      // Group by category
      const categoryData: Record<
        string,
        {
          predicted_quantities: number[];
          actual_quantities: number[];
          predicted_demands: number[];
          actual_demands: number[];
        }
      > = {};
  
      for (const record of records) {
        if (!categoryData[record.category]) {
          categoryData[record.category] = {
            predicted_quantities: [],
            actual_quantities: [],
            predicted_demands: [],
            actual_demands: [],
          };
        }
        categoryData[record.category].predicted_quantities.push(record.predicted_quantity);
        categoryData[record.category].actual_quantities.push(record.actual_quantity);
        categoryData[record.category].predicted_demands.push(record.predicted_demand);
        categoryData[record.category].actual_demands.push(record.actual_demand);
      }
  
      // Calculate quantity-based accuracy (精度率)
      let totalQuantityError = 0;
      let totalActualQuantity = 0;
      const categoryErrors: Record<string, number> = {};
  
      for (const category in categoryData) {
        const data = categoryData[category];
        let categoryQuantityError = 0;
        let categoryActualQuantity = 0;
  
        for (let i = 0; i < data.predicted_quantities.length; i++) {
          const error = Math.abs(data.predicted_quantities[i] - data.actual_quantities[i]);
          categoryQuantityError += error;
          categoryActualQuantity += data.actual_quantities[i];
        }
  
        totalQuantityError += categoryQuantityError;
        totalActualQuantity += categoryActualQuantity;
  
        const categoryErrorRate = (categoryQuantityError / categoryActualQuantity) * 100;
        categoryErrors[category] = categoryErrorRate;
      }
  
      const accuracyRate = 100 - (totalQuantityError / totalActualQuantity) * 100;
  
      // Calculate demand-based deviation (乖離度)
      let totalDemandError = 0;
      let totalActualDemand = 0;
  
      for (const category in categoryData) {
        const data = categoryData[category];
        for (let i = 0; i < data.predicted_demands.length; i++) {
          const error = Math.abs(data.predicted_demands[i] - data.actual_demands[i]);
          totalDemandError += error;
          totalActualDemand += data.actual_demands[i];
        }
      }
  
      const deviationRate = (totalDemandError / totalActualDemand) * 100;
  
      const now = new Date().toISOString();
      const categoryCount = Object.keys(categoryData).length;
      const totalRecords = records.length;
  
      const dashboardDisplay: PredictionAccuracyDashboard = {
        accuracy_rate: accuracyRate,
        deviation_rate: deviationRate,
        category_count: categoryCount,
        total_records: totalRecords,
        generated_at: now,
      };
  
      const exportData: PredictionAccuracyExport = {
        accuracy_rate: accuracyRate,
        deviation_rate: deviationRate,
        category_errors: categoryErrors,
        timestamp: now,
        data_source: '予測精度検証機能',
      };
  
      return {
        accuracy_rate: accuracyRate,
        deviation_rate: deviationRate,
        category_errors: categoryErrors,
        dashboard_display: dashboardDisplay,
        export_data: exportData,
      };
    }
  
    // Handle case: Record<string, number[]> (forecasted/actual by category)
    if (input && typeof input === 'object' && !Array.isArray(input)) {
      const keys = Object.keys(input);
      if (keys.length > 0 && Array.isArray(input[keys[0]])) {
        // Assume it's a Record<string, number[]> format
        // For now, return a default structure
        return {
          overallAccuracy: 0,
          rmse: 0,
          mae: 0,
          mape: 0,
          categoryAccuracy: {},
          pValue: 0,
        };
      }
    }
  
    return {
      overallAccuracy: 0,
      rmse: 0,
      mae: 0,
      mape: 0,
      categoryAccuracy: {},
      pValue: 0,
    };
  }
  return { calculatePredictionAccuracy };
})();
export const calculatePredictionAccuracy: (...args: any[]) => any = (...args: any[]) => (__aivicBundle_132_calculatePredictionAccuracy.calculatePredictionAccuracy as (...args: any[]) => any)(...args);
