/* AIVIC_FUNCTION_BUNDLE_START owner=validatePredictionAccuracy exports=validatePredictionAccuracy */
const __aivicBundle_133_validatePredictionAccuracy = (() => {
  interface ValidatePredictionAccuracyInput {
    accuracyRate: number;
    threshold: number;
    modelId: string;
    evaluationPeriod: string;
    timestamp?: string;
  }
  
  interface ValidatePredictionAccuracyResult {
    requiresImprovement: boolean;
    improvementDecision: string;
    accuracyRate: number;
    threshold: number;
    gap: number;
    displayMessage: string;
    isRecorded: boolean;
    modelId: string;
    evaluationPeriod: string;
    timestamp: string;
  }
  
   function validatePredictionAccuracy(
    input: ValidatePredictionAccuracyInput
  ): ValidatePredictionAccuracyResult {
    if (input.accuracyRate < 0 || input.accuracyRate > 100) {
      throw new Error('精度率は0から100の範囲である必要があります');
    }
  
    if (input.threshold < 0) {
      throw new Error('閾値は0以上である必要があります');
    }
  
    if (!input.modelId || input.modelId.trim() === '') {
      throw new Error('モデルIDは空でない文字列である必要があります');
    }
  
    const gap = input.accuracyRate - input.threshold;
    const requiresImprovement = gap < 0;
    const improvementDecision = requiresImprovement ? '改善要' : '改善不要';
    const displayMessage = requiresImprovement
      ? '精度率が閾値未満のため改善が必要です'
      : '精度率が閾値以上であり改善は不要です';
  
    const timestamp = input.timestamp || new Date().toISOString();
  
    return {
      requiresImprovement,
      improvementDecision,
      accuracyRate: input.accuracyRate,
      threshold: input.threshold,
      gap,
      displayMessage,
      isRecorded: true,
      modelId: input.modelId,
      evaluationPeriod: input.evaluationPeriod,
      timestamp
    };
  }
  return { validatePredictionAccuracy };
})();
export const validatePredictionAccuracy = __aivicBundle_133_validatePredictionAccuracy.validatePredictionAccuracy;
/* AIVIC_FUNCTION_BUNDLE_END owner=validatePredictionAccuracy */

/* AIVIC_FUNCTION_BUNDLE_START owner=verifyForecastAccuracy exports=verifyForecastAccuracy */
const __aivicBundle_134_verifyForecastAccuracy = (() => {
  interface VerifyForecastAccuracyRecord {
    recordId: string;
    forecastValue: number | null;
    actualValue: number | null;
    category: string;
  }
  
  interface VerifyForecastAccuracyResult {
    skippedRecords: string[];
    errorLog: string[];
    verifiedRecords: string[];
    totalProcessed: number;
    totalSkipped: number;
    processCompleted: boolean;
    errorCount: number;
    overallAccuracy?: number;
    categoryAccuracies?: Record<string, number>;
    isAccuracyMet?: boolean;
    deviationAnalysis?: Array<{
      categoryId: string;
      deviation: number;
      deviationPercent: number;
    }>;
    recommendedImprovement?: string;
  }
  
   function verifyForecastAccuracy(
    forecastData: VerifyForecastAccuracyRecord[]
  ): VerifyForecastAccuracyResult {
    const skippedRecords: string[] = [];
    const errorLog: string[] = [];
    const verifiedRecords: string[] = [];
    const deviationByCategory: Record<string, number[]> = {};
    const categoryAccuracies: Record<string, number> = {};
  
    let totalAccuracySum = 0;
    let validRecordCount = 0;
  
    for (const record of forecastData) {
      if (record.forecastValue === null || record.actualValue === null) {
        skippedRecords.push(record.recordId);
        const errorMessage = `null値を検出されました: recordId=${record.recordId}`;
        errorLog.push(errorMessage);
        continue;
      }
  
      verifiedRecords.push(record.recordId);
  
      const deviation = Math.abs(record.forecastValue - record.actualValue);
      const deviationPercent =
        record.actualValue !== 0
          ? (deviation / record.actualValue) * 100
          : deviation > 0
            ? 100
            : 0;
  
      const accuracy = Math.max(0, 1 - deviationPercent / 100);
  
      if (!deviationByCategory[record.category]) {
        deviationByCategory[record.category] = [];
      }
      deviationByCategory[record.category].push(accuracy);
  
      totalAccuracySum += accuracy;
      validRecordCount += 1;
    }
  
    for (const [category, accuracies] of Object.entries(deviationByCategory)) {
      const avgAccuracy =
        accuracies.reduce((sum, acc) => sum + acc, 0) / accuracies.length;
      categoryAccuracies[category] = Math.round(avgAccuracy * 10000) / 10000;
    }
  
    const overallAccuracy =
      validRecordCount > 0
        ? Math.round((totalAccuracySum / validRecordCount) * 10000) / 10000
        : 0;
  
    const deviationAnalysis: Array<{
      categoryId: string;
      deviation: number;
      deviationPercent: number;
    }> = [];
  
    for (const record of forecastData) {
      if (record.forecastValue !== null && record.actualValue !== null) {
        const deviation = Math.abs(record.forecastValue - record.actualValue);
        const deviationPercent =
          record.actualValue !== 0
            ? (deviation / record.actualValue) * 100
            : deviation > 0
              ? 100
              : 0;
  
        deviationAnalysis.push({
          categoryId: record.category,
          deviation: Math.round(deviation * 100) / 100,
          deviationPercent: Math.round(deviationPercent * 100) / 100,
        });
      }
    }
  
    let recommendedImprovement = "maintain_current_model";
    if (overallAccuracy < 0.7) {
      recommendedImprovement = "add_external_factors";
    } else if (overallAccuracy < 0.85) {
      recommendedImprovement = "refine_model_parameters";
    } else if (overallAccuracy >= 0.95) {
      recommendedImprovement = "maintain_current_model";
    }
  
    return {
      skippedRecords,
      errorLog,
      verifiedRecords,
      totalProcessed: forecastData.length,
      totalSkipped: skippedRecords.length,
      processCompleted: true,
      errorCount: errorLog.length,
      overallAccuracy,
      categoryAccuracies,
      isAccuracyMet: overallAccuracy >= 0.9,
      deviationAnalysis,
      recommendedImprovement,
    };
  }
  return { verifyForecastAccuracy };
})();
export const verifyForecastAccuracy = __aivicBundle_134_verifyForecastAccuracy.verifyForecastAccuracy;
/* AIVIC_FUNCTION_BUNDLE_END owner=verifyForecastAccuracy */

/* AIVIC_FUNCTION_BUNDLE_START owner=determineAlgorithmImprovementJudgment exports=determineAlgorithmImprovementJudgment */
const __aivicBundle_135_determineAlgorithmImprovementJudgment = (() => {
  function determineAlgorithmImprovementJudgment(input: {
    algorithmVersionId: string;
    predictionAccuracyThreshold: number;
    currentPredictionAccuracy: number;
    failurePatterns: Array<{
      categoryId: string;
      categoryName: string;
      occurrenceCount: number;
      priority: number;
      impactScore: number;
    }>;
    improvementCandidates: Array<{
      improvementId: string;
      improvementType: string;
      estimatedEffectValue: number;
      implementationDifficulty: number;
      userImpactScore: number;
    }>;
  }): {
    improvementExecutionFlag: boolean;
    targetImprovementFeatures: Array<{
      improvementId: string;
      priority: number;
      improvementContent: string;
      estimatedEffectValue: number;
      implementationDifficulty: number;
      userImpactScore: number;
    }>;
    improvementJudgmentDetail: {
      currentAccuracy: number;
      accuracyThreshold: number;
      accuracyGap: number;
      projectedAccuracyAfterImprovement: number;
      improvementExecutionJustification: string;
    };
  } {
    if (!String(input.algorithmVersionId).trim()) {
      throw new Error('algorithmVersionId is required');
    }
  
    if (!input.failurePatterns || input.failurePatterns.length === 0) {
      throw new Error('failurePatterns is required');
    }
  
    const accuracyGap = input.currentPredictionAccuracy - input.predictionAccuracyThreshold;
    const shouldExecuteImprovement = accuracyGap < 0;
  
    const rankedCandidates = input.improvementCandidates
      .map((candidate) => ({
        ...candidate,
        improvementContent: candidate.improvementType,
        priorityScore:
          candidate.estimatedEffectValue * 0.5 +
          candidate.userImpactScore * 0.35 -
          candidate.implementationDifficulty * 0.15,
      }))
      .sort((a, b) => b.priorityScore - a.priorityScore)
      .slice(0, 3)
      .map((candidate, index) => ({
        improvementId: candidate.improvementId,
        priority: index + 1,
        improvementContent: candidate.improvementContent,
        estimatedEffectValue: candidate.estimatedEffectValue,
        implementationDifficulty: candidate.implementationDifficulty,
        userImpactScore: candidate.userImpactScore,
      }));
  
    const totalExpectedImprovement = rankedCandidates.reduce(
      (sum, candidate) => sum + candidate.estimatedEffectValue,
      0
    );
  
    const projectedAccuracy = input.currentPredictionAccuracy + totalExpectedImprovement;
  
    return {
      improvementExecutionFlag: shouldExecuteImprovement,
      targetImprovementFeatures: rankedCandidates,
      improvementJudgmentDetail: {
        currentAccuracy: input.currentPredictionAccuracy,
        accuracyThreshold: input.predictionAccuracyThreshold,
        accuracyGap: accuracyGap,
        projectedAccuracyAfterImprovement: projectedAccuracy,
        improvementExecutionJustification: shouldExecuteImprovement
          ? 'accuracyBelowThreshold'
          : 'accuracyMeetsThreshold',
      },
    };
  }
  return { determineAlgorithmImprovementJudgment };
})();
export const determineAlgorithmImprovementJudgment = __aivicBundle_135_determineAlgorithmImprovementJudgment.determineAlgorithmImprovementJudgment;
/* AIVIC_FUNCTION_BUNDLE_END owner=determineAlgorithmImprovementJudgment */

/* AIVIC_FUNCTION_BUNDLE_START owner=judgeAlgorithmImprovement exports=judgeAlgorithmImprovement */
const __aivicBundle_136_judgeAlgorithmImprovement = (() => {
  function judgeAlgorithmImprovement(input: any): any {
    // Handle case where input has accuracy and threshold (first test scenario)
    if (input.accuracy !== undefined && input.threshold !== undefined) {
      const accuracy = input.accuracy;
      const threshold = input.threshold;
      
      const accuracyMetThreshold = accuracy >= threshold;
      
      return {
        judgment: accuracyMetThreshold ? '見送り' : '改善必要',
        should_improve: !accuracyMetThreshold,
        accuracy_met_threshold: accuracyMetThreshold,
      };
    }
  
    // Handle case where input is divergence analysis result
    if (input.analysisId !== undefined || input.forecastAccuracy !== undefined) {
      // Check for missing required fields
      const requiredFields = ['analysisId', 'forecastAccuracy', 'actualDemand', 'categoryDivergences'];
      const missingFields = requiredFields.filter(
        field => input[field] === null || input[field] === undefined
      );
  
      if (missingFields.length > 0) {
        return {
          error: true,
          errorMessage: '乖離分析結果が欠損しています。必須フィールドを確認してください。',
          errorCode: 'DIVERGENCE_DATA_MISSING',
          improvementDecision: null,
          recommendedAction: undefined,
          confidenceScore: undefined,
          skipReason: 'MISSING_REQUIRED_FIELDS',
        };
      }
  
      // All required fields are present - execute improvement judgment
      const forecastAccuracy = input.forecastAccuracy;
      const divergenceRate = input.divergenceRate || 0;
      const categoryDivergences = input.categoryDivergences || [];
  
      // Calculate confidence score based on forecast accuracy and divergence
      const confidenceScore = Math.max(0, Math.min(100, forecastAccuracy - divergenceRate));
  
      // Determine improvement decision based on accuracy and divergence
      let improvementDecision = 'monitor';
      if (forecastAccuracy < 85 || divergenceRate > 10) {
        improvementDecision = 'implement';
      } else if (forecastAccuracy >= 90 && divergenceRate <= 5) {
        improvementDecision = 'defer';
      }
  
      // Determine recommended action
      let recommendedAction = 'continue_monitoring';
      if (improvementDecision === 'implement') {
        recommendedAction = 'prioritize_implementation';
      } else if (improvementDecision === 'defer') {
        recommendedAction = 'schedule_for_next_cycle';
      }
  
      return {
        error: false,
        improvementDecision: improvementDecision,
        recommendedAction: recommendedAction,
        confidenceScore: confidenceScore,
        forecastAccuracy: forecastAccuracy,
        divergenceRate: divergenceRate,
        categoryDivergenceCount: categoryDivergences.length,
      };
    }
  
    // Default case for unknown input structure
    return {
      error: true,
      errorMessage: '入力形式が不正です。',
      errorCode: 'INVALID_INPUT_FORMAT',
      improvementDecision: null,
      recommendedAction: undefined,
      confidenceScore: undefined,
    };
  }
  return { judgeAlgorithmImprovement };
})();
export const judgeAlgorithmImprovement = __aivicBundle_136_judgeAlgorithmImprovement.judgeAlgorithmImprovement;
