/* AIVIC_FUNCTION_BUNDLE_START owner=determineAlgorithmImprovement exports=determineAlgorithmImprovement */
const __aivicBundle_137_determineAlgorithmImprovement = (() => {
  function determineAlgorithmImprovement(input: {
    algorithm_version: string;
    prediction_accuracy: number;
    accuracy_threshold: number;
    previous_success_rate: number;
    current_success_rate: number;
    previous_satisfaction_score: number;
    current_satisfaction_score: number;
    previous_cooking_time_reduction: number;
    current_cooking_time_reduction: number;
  }): {
    status_code: number;
    improvement_flag: boolean;
    improvement_reason: string;
    accuracy_match_status: string;
    success_rate_improvement: number;
    satisfaction_score_improvement: number;
    cooking_time_reduction_improvement: number;
    overall_improvement_score: number;
    evaluation_timestamp: string;
    algorithm_version: string;
  } {
    const successRateImprovement =
      input.current_success_rate - input.previous_success_rate;
    const satisfactionImprovement =
      input.current_satisfaction_score - input.previous_satisfaction_score;
    const cookingTimeImprovement =
      input.current_cooking_time_reduction -
      input.previous_cooking_time_reduction;
  
    const accuracyDifference = Math.abs(
      input.prediction_accuracy - input.accuracy_threshold
    );
    const accuracyMatchStatus =
      accuracyDifference < 0.01 ? "threshold_exactly_met" : "threshold_not_met";
  
    const hasImproved =
      successRateImprovement > 0 &&
      satisfactionImprovement > 0 &&
      cookingTimeImprovement > 0 &&
      input.prediction_accuracy >= input.accuracy_threshold;
  
    const successRateWeight = 0.4;
    const satisfactionWeight = 0.35;
    const cookingTimeWeight = 0.25;
  
    const normalizedSuccessRate = Math.min(
      (successRateImprovement / 0.2) * 100,
      100
    );
    const normalizedSatisfaction = Math.min(
      (satisfactionImprovement / 1.0) * 100,
      100
    );
    const normalizedCookingTime = Math.min(
      (cookingTimeImprovement / 0.15) * 100,
      100
    );
  
    const overallImprovementScore =
      normalizedSuccessRate * successRateWeight +
      normalizedSatisfaction * satisfactionWeight +
      normalizedCookingTime * cookingTimeWeight;
  
    const improvementReason = hasImproved
      ? `予測精度が閾値に達成し、成功率が${(successRateImprovement * 100).toFixed(1)}%、満足度が${satisfactionImprovement.toFixed(1)}ポイント、調理時間短縮度が${(cookingTimeImprovement * 100).toFixed(1)}%改善しました。`
      : `改善が不十分です。予測精度: ${input.prediction_accuracy.toFixed(1)}%（閾値: ${input.accuracy_threshold}%）`;
  
    const evaluationTimestamp = new Date().toISOString();
  
    return {
      status_code: 200,
      improvement_flag: hasImproved,
      improvement_reason: improvementReason,
      accuracy_match_status: accuracyMatchStatus,
      success_rate_improvement: successRateImprovement,
      satisfaction_score_improvement: satisfactionImprovement,
      cooking_time_reduction_improvement: cookingTimeImprovement,
      overall_improvement_score: Math.max(
        0,
        Math.min(overallImprovementScore, 100)
      ),
      evaluation_timestamp: evaluationTimestamp,
      algorithm_version: input.algorithm_version,
    };
  }
  return { determineAlgorithmImprovement };
})();
export const determineAlgorithmImprovement = __aivicBundle_137_determineAlgorithmImprovement.determineAlgorithmImprovement;
/* AIVIC_FUNCTION_BUNDLE_END owner=determineAlgorithmImprovement */

