    const weekdayRateVariance = calculateVariance(weekdayRates);
    const weekdayBasketVariance = calculateVariance(weekdayBasketSizes);
    const weekday_score = Math.min(1, (weekdayRateVariance + weekdayBasketVariance) / 2 + 0.5);
  
    // Find dominant weekday
    const weekdayNames = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday'];
    const dominantWeekdayIndex = weekdayRates.indexOf(Math.max(...weekdayRates));
    const dominant_weekday = weekdayNames[dominantWeekdayIndex];
    const weekday_peak_purchase_rate = weekdayRates[dominantWeekdayIndex];
    const weekday_peak_basket_size = weekdayBasketSizes[dominantWeekdayIndex];
  
    // Calculate overall score
    const overall_score = (seasonal_score + weekday_score) / 2;
  
    // Determine approval status
    const approval_status = overall_score >= approval_threshold_score ? 'APPROVED' : 'REJECTED';
  
    // Calculate dates based on analysis_period_days and sample_size for data quality assessment
    const now = new Date();
    const nextReviewDate = new Date(now.getTime() + input.analysis_period_days * 24 * 60 * 60 * 1000);
