/* AIVIC_FUNCTION_BUNDLE_START owner=validatePurchasingTrendApproval exports=validatePurchasingTrendApproval */
const __aivicBundle_140_validatePurchasingTrendApproval = (() => {
  function validatePurchasingTrendApproval(trendData: {
    trend_id: string;
    seasonal_pattern: string;
    discount_rate_threshold: number;
    sales_period_start: Date;
    sales_period_end: Date;
  }): {
    is_approved: boolean;
    approval_result: string;
    message: string;
  } {
    const validationErrors: string[] = [];
    const requiredConditions: Array<{ condition: string; isMet: boolean }> = [];
  
    // Condition 1: sales_period_start must be before sales_period_end
    const periodValid = trendData.sales_period_start < trendData.sales_period_end;
    requiredConditions.push({
      condition: 'sales_period_valid',
      isMet: periodValid,
    });
    if (!periodValid) {
      validationErrors.push('販売期間の開始日が終了日より後である');
    }
  
    // Condition 2: discount_rate_threshold must be positive
    const costPositive = trendData.discount_rate_threshold > 0;
    requiredConditions.push({
      condition: 'discount_rate_positive',
      isMet: costPositive,
    });
    if (!costPositive) {
      validationErrors.push('割引率閾値が正数ではない');
    }
  
    // Condition 3: seasonal_pattern must be non-empty
    const hasPattern =
      trendData.seasonal_pattern &&
      trendData.seasonal_pattern.trim().length > 0;
    requiredConditions.push({
      condition: 'has_seasonal_pattern',
      isMet: hasPattern,
    });
    if (!hasPattern) {
      validationErrors.push('季節パターンが指定されていない');
    }
  
    // Condition 4: trend_id must be non-empty
    const hasTrendId = trendData.trend_id && trendData.trend_id.trim().length > 0;
    requiredConditions.push({
      condition: 'has_trend_id',
      isMet: hasTrendId,
    });
    if (!hasTrendId) {
      validationErrors.push('トレンドIDが指定されていない');
    }
  
    const isValid = validationErrors.length === 0;
    const approvalEligible = isValid;
  
    let message = '';
    if (isValid) {
      message = 'Purchasing trend data is valid and eligible for approval';
    } else {
      message = `Validation failed: ${validationErrors.join('; ')}. Additional data validation required.`;
    }
  
    return {
      is_approved: approvalEligible,
      approval_result: approvalEligible ? 'YES' : 'NO',
      message: message,
    };
  }
  return { validatePurchasingTrendApproval };
})();
export const validatePurchasingTrendApproval = __aivicBundle_140_validatePurchasingTrendApproval.validatePurchasingTrendApproval;
/* AIVIC_FUNCTION_BUNDLE_END owner=validatePurchasingTrendApproval */

/* AIVIC_FUNCTION_BUNDLE_START owner=markPurchasingTrendAsHeld exports=markPurchasingTrendAsHeld */
const __aivicBundle_141_markPurchasingTrendAsHeld = (() => {
  function markPurchasingTrendAsHeld(input: {
    trend_id: string;
    approval_result: string;
    approval_reason: string;
    approval_timestamp: Date | string;
  }): {
    trend_id: string;
    reflection_status: 'HELD';
    is_reflected: false;
    held_timestamp: Date | string;
    held_reason: string;
  } {
    if (!String(input.approval_result).trim()) {
      throw new Error('approval_result is required');
    }
  
    const heldTimestamp = typeof input.approval_timestamp === 'string'
      ? input.approval_timestamp
      : input.approval_timestamp instanceof Date
        ? input.approval_timestamp.toISOString()
        : input.approval_timestamp;
  
    return {
      trend_id: input.trend_id,
      reflection_status: 'HELD',
      is_reflected: false,
      held_timestamp: heldTimestamp,
      held_reason: input.approval_reason,
    };
  }
  return { markPurchasingTrendAsHeld };
})();
