/* AIVIC_FUNCTION_BUNDLE_START owner=getPurchasingTrendStatus exports=getPurchasingTrendStatus */
const __aivicBundle_142_getPurchasingTrendStatus = (() => {
  function getPurchasingTrendStatus(input: { trend_id: string }): {
    trend_id: string;
    reflection_status: 'HELD' | 'PENDING' | 'APPROVED' | 'REJECTED';
    is_reflected: boolean;
    is_pending_approval: boolean;
    last_update_timestamp: string;
    status_message: string;
  } {
    const { trend_id } = input;
  
    const purchasingTrendStore: Record<
      string,
      {
        trend_id: string;
        reflection_status: 'HELD' | 'PENDING' | 'APPROVED' | 'REJECTED';
        is_reflected: boolean;
        last_update_timestamp: string;
        held_reason?: string;
      }
    > = {};
  
    const storedTrend = purchasingTrendStore[trend_id];
  
    if (!storedTrend) {
      return {
        trend_id: trend_id,
        reflection_status: 'PENDING',
        is_reflected: false,
        is_pending_approval: true,
        last_update_timestamp: new Date().toISOString(),
        status_message: 'Pending approval',
      };
    }
  
    const isHeld = storedTrend.reflection_status === 'HELD';
    const isPendingApproval =
      storedTrend.reflection_status === 'PENDING' ||
      storedTrend.reflection_status === 'HELD';
  
    let statusMessage = '';
    if (isHeld) {
      statusMessage = `Trend held: ${storedTrend.held_reason || 'pending review'}`;
    } else if (storedTrend.reflection_status === 'APPROVED') {
      statusMessage = 'Trend approved and reflected';
    } else if (storedTrend.reflection_status === 'REJECTED') {
      statusMessage = 'Trend rejected';
    } else {
      statusMessage = 'Pending approval';
    }
  
    return {
      trend_id: trend_id,
      reflection_status: storedTrend.reflection_status,
      is_reflected: storedTrend.is_reflected,
      is_pending_approval: isPendingApproval,
      last_update_timestamp: storedTrend.last_update_timestamp,
      status_message: statusMessage,
    };
  }
  return { getPurchasingTrendStatus };
})();
export const getPurchasingTrendStatus = __aivicBundle_142_getPurchasingTrendStatus.getPurchasingTrendStatus;
