/* AIVIC_FUNCTION_BUNDLE_START owner=verifyNutritionBalanceWithSlaCheck exports=verifyNutritionBalanceWithSlaCheck */
const __aivicBundle_149_verifyNutritionBalanceWithSlaCheck = (() => {
  const DEFAULT_SLA_THRESHOLD_MS = 24 * 60 * 60 * 1000; // 24 hours in milliseconds
  
  interface VerifyNutritionBalanceWithSlaCheckInput {
    userId: string;
    familyId: string;
    verificationStartTimestamp: number;
    verificationCheckTimestamp: number;
    targetCalories: number;
    actualCalories: number;
    targetProteinGrams: number;
    actualProteinGrams: number;
    targetCarbsGrams: number;
    actualCarbsGrams: number;
    targetFatGrams: number;
    actualFatGrams: number;
    slaTresholdMs: number;
  }
  
  interface VerifyNutritionBalanceWithSlaCheckResult {
    isAlternativeProcessExecuted: boolean;
    isNormalFlowExecuted: boolean;
    verificationStatus: string;
    verificationType: string;
    caloriesAchievementRate: number;
    proteinAchievementRate: number;
    carbsAchievementRate: number;
    fatAchievementRate: number;
    overallNutritionScore: number;
    hasAnomalies: boolean;
    verificationCompletedTimestamp: number;
    processingTimeMs: number;
    detailedNutrientBreakdown: {
      calories: { target: number; actual: number };
      protein: { target: number; actual: number };
      carbs: { target: number; actual: number };
      fat: { target: number; actual: number };
    };
    warnings: string[];
    errors: string[];
  }
  
   function verifyNutritionBalanceWithSlaCheck(
    nutritionData: VerifyNutritionBalanceWithSlaCheckInput
  ): VerifyNutritionBalanceWithSlaCheckResult {
    const processingStartTime = Date.now();
  
    // Validate required inputs
    if (!String(nutritionData.userId).trim()) {
      throw new Error("userId is required");
    }
    if (!String(nutritionData.familyId).trim()) {
      throw new Error("familyId is required");
    }
  
    // Calculate elapsed time from verification start to check
    const elapsedTimeMs =
      nutritionData.verificationCheckTimestamp -
      nutritionData.verificationStartTimestamp;
  
    // Determine if within SLA threshold
    const isWithinSla = elapsedTimeMs <= nutritionData.slaTresholdMs;
  
    // Calculate achievement rates for each nutrient
    const caloriesAchievementRate =
      (nutritionData.actualCalories / nutritionData.targetCalories) * 100;
    const proteinAchievementRate =
      (nutritionData.actualProteinGrams / nutritionData.targetProteinGrams) * 100;
    const carbsAchievementRate =
      (nutritionData.actualCarbsGrams / nutritionData.targetCarbsGrams) * 100;
    const fatAchievementRate =
      (nutritionData.actualFatGrams / nutritionData.targetFatGrams) * 100;
  
    // Calculate overall nutrition score (average of all achievement rates)
    const overallNutritionScore =
      (caloriesAchievementRate +
        proteinAchievementRate +
        carbsAchievementRate +
        fatAchievementRate) /
      4;
  
    // Determine if nutrition balance is achieved (all nutrients >= 90%)
    const nutritionBalanceAchieved =
      caloriesAchievementRate >= 90 &&
      proteinAchievementRate >= 90 &&
      carbsAchievementRate >= 90 &&
      fatAchievementRate >= 90;
  
    // Determine verification flow
    const isNormalFlowExecuted = isWithinSla;
    const isAlternativeProcessExecuted = !isWithinSla;
  
    // Collect warnings and errors
    const warnings: string[] = [];
    const errors: string[] = [];
  
    if (caloriesAchievementRate < 90) {
      warnings.push(
        `Calories achievement rate ${caloriesAchievementRate.toFixed(2)}% is below 90%`
      );
    }
    if (proteinAchievementRate < 90) {
      warnings.push(
        `Protein achievement rate ${proteinAchievementRate.toFixed(2)}% is below 90%`
      );
    }
    if (carbsAchievementRate < 90) {
      warnings.push(
        `Carbs achievement rate ${carbsAchievementRate.toFixed(2)}% is below 90%`
      );
    }
    if (fatAchievementRate < 90) {
      warnings.push(
        `Fat achievement rate ${fatAchievementRate.toFixed(2)}% is below 90%`
      );
    }
  
    if (!isWithinSla) {
      errors.push(
        `Verification exceeded SLA threshold: ${elapsedTimeMs}ms > ${nutritionData.slaTresholdMs}ms`
      );
    }
  
    // Determine overall verification result based on SLA and nutrition balance
    let overallVerificationResult: "pass" | "fail" | "warning" = "pass";
    if (!isWithinSla || !nutritionBalanceAchieved) {
      overallVerificationResult = "fail";
    } else if (warnings.length > 0) {
      overallVerificationResult = "warning";
    }
  
    const processingEndTime = Date.now();
    const processingTimeMs = processingEndTime - processingStartTime;
  
    return {
      isAlternativeProcessExecuted,
      isNormalFlowExecuted,
      verificationStatus: "completed",
      verificationType: isNormalFlowExecuted ? "normal" : "alternative",
      caloriesAchievementRate,
      proteinAchievementRate,
      carbsAchievementRate,
      fatAchievementRate,
      overallNutritionScore,
      hasAnomalies: false,
      verificationCompletedTimestamp: processingEndTime,
      processingTimeMs,
      detailedNutrientBreakdown: {
        calories: {
          target: nutritionData.targetCalories,
          actual: nutritionData.actualCalories,
        },
        protein: {
          target: nutritionData.targetProteinGrams,
          actual: nutritionData.actualProteinGrams,
        },
        carbs: {
          target: nutritionData.targetCarbsGrams,
          actual: nutritionData.actualCarbsGrams,
        },
        fat: {
          target: nutritionData.targetFatGrams,
          actual: nutritionData.actualFatGrams,
        },
      },
      warnings,
      errors,
    };
  }
  return { verifyNutritionBalanceWithSlaCheck };
})();
