/* AIVIC_FUNCTION_BUNDLE_START owner=analyzeMonthlyFoodCostExcess exports=analyzeMonthlyFoodCostExcess */
const __aivicBundle_150_analyzeMonthlyFoodCostExcess = (() => {
  function analyzeMonthlyFoodCostExcess(expenseData: any): any {
    // Handle both snake_case and camelCase input formats
    const month = expenseData.month;
    const budgetLimit = expenseData.budgetLimit ?? expenseData.budget_limit;
    const actualTotal = expenseData.actualExpenseYen ?? expenseData.actual_total ?? expenseData.currentMonthTotal;
    const previousMonthTotal = expenseData.previousMonthActualYen ?? expenseData.previousMonthTotal;
    const foodComposition = expenseData.food_composition;
    const currentMonthPurchases = expenseData.currentMonthPurchases;
    const previousMonthPurchases = expenseData.previousMonthPurchases;
  
    // Detect input format: snake_case with food_composition or camelCase with purchases
    const isSnakeCaseFormat = !!foodComposition;
  
    if (isSnakeCaseFormat) {
      return analyzeWithFoodComposition(
        month,
        budgetLimit,
        actualTotal,
        foodComposition
      );
    } else {
      return analyzeWithPurchases(
        expenseData.userId,
        expenseData.year,
        expenseData.month,
        budgetLimit,
        currentMonthPurchases,
        previousMonthPurchases,
        actualTotal,
        previousMonthTotal
      );
    }
  }
  
  function analyzeWithFoodComposition(
    month: string,
    budgetLimit: number,
    actualTotal: number,
    foodComposition: any[]
  ): any {
    const excessAmount = actualTotal - budgetLimit;
    const excessPercentage = budgetLimit > 0 ? (excessAmount / budgetLimit) * 100 : 0;
  
    const analyzedItems: any[] = [];
    const missingDataInfo: any[] = [];
  
    for (const item of foodComposition) {
      const category = item.category;
      const plannedQuantity = item.planned_quantity ?? 0;
      const actualQuantity = item.actual_quantity ?? 0;
      const unitPrice = item.unit_price;
  
      if (unitPrice === undefined || unitPrice === null) {
        missingDataInfo.push({
          category,
          reason: 'unit_price',
        });
        continue;
      }
  
      const plannedCost = plannedQuantity * unitPrice;
      const actualCost = actualQuantity * unitPrice;
      const excessAmount = actualCost - plannedCost;
  
      analyzedItems.push({
        category,
        planned_cost: plannedCost,
        actual_cost: actualCost,
        excess_amount: excessAmount,
      });
    }
  
    const totalAnalyzedExcess = analyzedItems.reduce(
      (sum, item) => sum + item.excess_amount,
      0
    );
  
    const decompositionCoveragePercent =
      foodComposition.length > 0
        ? Math.round((analyzedItems.length / foodComposition.length) * 10000) / 100
        : 0;
  
    return {
      is_partial: missingDataInfo.length > 0,
      analyzed_items: analyzedItems,
      missing_data_info: missingDataInfo,
      total_analyzed_excess: totalAnalyzedExcess,
      decomposition_coverage_percent: decompositionCoveragePercent,
    };
  }
  
  function analyzeWithPurchases(
    userId: string,
    year: number,
    month: number,
    budgetLimit: number,
    currentMonthPurchases: any[],
    previousMonthPurchases: any[],
    currentMonthTotal: number,
    previousMonthTotal: number
  ): any {
    const excessAmount = currentMonthTotal - budgetLimit;
    const excessPercentage =
      budgetLimit > 0 ? (excessAmount / budgetLimit) * 100 : 0;
  
    // Build a map of previous month purchases for comparison
    const previousMonthMap = new Map<string, any>();
    for (const purchase of previousMonthPurchases) {
      previousMonthMap.set(purchase.foodItemId, purchase);
    }
  
    // Decompose excess into composition and unit price variance
    let ingredientCompositionOverage = 0;
    let unitPriceVarianceOverage = 0;
    const detailedBreakdown: any[] = [];
  
    for (const currentPurchase of currentMonthPurchases) {
      const foodItemId = currentPurchase.foodItemId;
      const previousPurchase = previousMonthMap.get(foodItemId);
  
      if (!previousPurchase) {
        // New item, attribute to composition
        ingredientCompositionOverage += currentPurchase.totalPrice;
        detailedBreakdown.push({
          foodItemId,
          itemName: currentPurchase.itemName,
          contributionAmount: currentPurchase.totalPrice,
          contributionType: 'composition',
        });
        continue;
      }
  
      // Calculate composition effect: quantity change at previous unit price
      const quantityDelta = currentPurchase.quantity - previousPurchase.quantity;
      const compositionEffect = quantityDelta * previousPurchase.unitPrice;
  
      // Calculate unit price effect: price change at current quantity
      const unitPriceDelta = currentPurchase.unitPrice - previousPurchase.unitPrice;
      const unitPriceEffect = currentPurchase.quantity * unitPriceDelta;
  
      if (compositionEffect > 0) {
        ingredientCompositionOverage += compositionEffect;
        detailedBreakdown.push({
          foodItemId,
          itemName: currentPurchase.itemName,
          contributionAmount: compositionEffect,
          contributionType: 'composition',
        });
      }
  
      if (unitPriceEffect > 0) {
        unitPriceVarianceOverage += unitPriceEffect;
        detailedBreakdown.push({
          foodItemId,
          itemName: currentPurchase.itemName,
          contributionAmount: unitPriceEffect,
          contributionType: 'unitPrice',
        });
      }
    }
  
    // Identify top overage ingredients
    const topOverageIngredients = detailedBreakdown
      .sort((a, b) => b.contributionAmount - a.contributionAmount)
      .slice(0, 3)
      .map((item) => ({
        ingredientName: item.itemName,
        overageContribution: item.contributionAmount,
        reason:
          item.contributionType === 'composition'
            ? '購入量増加'
            : '単価上昇',
      }));
  
    // Determine next month priority condition
    let nextMonthPriorityCondition = 'バランス重視';
    if (excessPercentage > 10) {
      nextMonthPriorityCondition = '予算重視';
    } else if (excessPercentage > 5) {
      nextMonthPriorityCondition = 'コスト最適化';
    }
  
    // Calculate recommended budget adjustment
    const recommendedBudgetAdjustment = Math.ceil(
      currentMonthTotal * 1.1
    );
    const adjustmentRationale =
      excessAmount > 0
        ? `前月実績 ${currentMonthTotal}円に基づき、10% のバッファを含めて ${recommendedBudgetAdjustment}円を推奨`
        : '予算内で収まっているため、現在の予算を維持';
  
    // Identify priority items for next month
    const priorityItems = topOverageIngredients.map((item) => {
      const purchase = currentMonthPurchases.find(
        (p) => p.itemName === item.ingredientName
      );
      return purchase?.foodItemId || '';
    });
  
    return {
      excessAmount,
      excessPercentage: Math.round(excessPercentage * 100) / 100,
      ingredientCompositionOverage,
      unitPriceVarianceOverage,
      topOverageIngredients,
      nextMonthPriorityCondition,
      recommendedBudgetAdjustment,
      adjustmentRationale,
      detailedBreakdown,
      analysisDate: new Date().toISOString(),
      analysisStatus: 'completed',
      nextMonthRecommendation: {
        priorityItems,
      },
    };
  }
  return { analyzeMonthlyFoodCostExcess };
})();
export const analyzeMonthlyFoodCostExcess = __aivicBundle_150_analyzeMonthlyFoodCostExcess.analyzeMonthlyFoodCostExcess;
/* AIVIC_FUNCTION_BUNDLE_END owner=analyzeMonthlyFoodCostExcess */

