      input.delay_detected_at.getTime() - input.process_trigger_timestamp.getTime();
    const isDelayed = delayDurationMs > input.sla_threshold_milliseconds;
  
    const fallbackExecutionTimestamp = new Date();
  
    const delayLog = {
      delay_start_time: input.process_trigger_timestamp,
      delay_detected_time: input.delay_detected_at,
      delay_duration_milliseconds: delayDurationMs,
      delay_type: 'process_timeout' as const,
      process_type: input.process_type,
      fallback_result_status: 'completed' as const,
      affected_metrics_count: input.affected_metrics.length,
      affected_metrics: input.affected_metrics,
    };
  
