/* AIVIC_FUNCTION_BUNDLE_START owner=validateMonthlyVerificationTiming exports=validateMonthlyVerificationTiming */
const __aivicBundle_155_validateMonthlyVerificationTiming = (() => {
  function validateMonthlyVerificationTiming(input: any): any {
    const result: any = {
      canExecuteVerification: true,
      statusCode: 'READY_FOR_VERIFICATION',
      skipVerification: false,
      warnings: [],
      missingFields: [],
      invalidFields: [],
      missingFieldCount: 0,
      invalidFieldCount: 0,
      incompleteItemCount: 0,
      notificationMessage: '',
      errorCode: '',
      targetMonth: '',
    };
  
    // Extract target month from recordedAt
    if (input.recordedAt) {
      const date = new Date(input.recordedAt);
      result.targetMonth = `${date.getFullYear()}-${String(date.getMonth() + 1).padStart(2, '0')}`;
    }
  
    const missingFields: string[] = [];
    const invalidFields: string[] = [];
    const warnings: string[] = [];
    let incompleteItemCount = 0;
  
    // Validate menus array
    if (!input.menus || !Array.isArray(input.menus)) {
      warnings.push('メニューデータが存在しません');
      incompleteItemCount++;
    } else if (input.menus.length === 0) {
      warnings.push('メニューデータが空です');
      incompleteItemCount++;
    } else {
      input.menus.forEach((menu: any, idx: number) => {
        if (!menu.generatedAt) {
          missingFields.push(`menus[${idx}].generatedAt`);
        }
        if (menu.satisfactionScore === null || menu.satisfactionScore === undefined) {
          missingFields.push(`menus[${idx}].satisfactionScore`);
        } else if (typeof menu.satisfactionScore !== 'number' || menu.satisfactionScore < 0 || menu.satisfactionScore > 5) {
          invalidFields.push(`menus[${idx}].satisfactionScore`);
        }
      });
    }
  
    // Validate preparations array
    if (input.preparations === null || input.preparations === undefined) {
      warnings.push('準備データが存在しません');
      incompleteItemCount++;
    } else if (Array.isArray(input.preparations)) {
      input.preparations.forEach((prep: any, idx: number) => {
        if (!prep.prepId) {
          missingFields.push(`preparations[${idx}].prepId`);
        }
        if (prep.estimatedTime === null || prep.estimatedTime === undefined) {
          missingFields.push(`preparations[${idx}].estimatedTime`);
        } else if (typeof prep.estimatedTime !== 'number' || prep.estimatedTime < 0) {
          invalidFields.push(`preparations[${idx}].estimatedTime`);
        }
        if (prep.actualTime === null || prep.actualTime === undefined) {
          missingFields.push(`preparations[${idx}].actualTime`);
        } else if (typeof prep.actualTime !== 'number' || prep.actualTime < 0) {
          invalidFields.push(`preparations[${idx}].actualTime`);
        }
      });
    }
  
    // Validate evaluations array
    if (!input.evaluations || !Array.isArray(input.evaluations)) {
      warnings.push('評価データが存在しません');
      incompleteItemCount++;
    } else {
      input.evaluations.forEach((eval_: any, idx: number) => {
        if (eval_.satisfactionScore === null || eval_.satisfactionScore === undefined) {
          missingFields.push(`evaluations[${idx}].satisfactionScore`);
        } else if (typeof eval_.satisfactionScore !== 'number' || eval_.satisfactionScore < 0 || eval_.satisfactionScore > 5) {
          invalidFields.push(`evaluations[${idx}].satisfactionScore`);
        }
        if (eval_.completionRate === null || eval_.completionRate === undefined) {
          missingFields.push(`evaluations[${idx}].completionRate`);
        } else if (typeof eval_.completionRate !== 'number' || eval_.completionRate < 0 || eval_.completionRate > 1) {
          invalidFields.push(`evaluations[${idx}].completionRate`);
        }
      });
    }
  
    // Determine if verification can be executed
    const hasDataIssues = missingFields.length > 0 || invalidFields.length > 0 || incompleteItemCount > 0;
  
    if (hasDataIssues) {
      result.canExecuteVerification = false;
      result.statusCode = 'DATA_INCOMPLETE';
      result.skipVerification = true;
      result.errorCode = 'VERIFY_SKIP_INCOMPLETE_DATA';
  
      // Collect all warnings
      if (missingFields.length > 0) {
        warnings.push(`欠落フィールド: ${missingFields.join(', ')}`);
      }
      if (invalidFields.length > 0) {
        warnings.push(`不正な値: ${invalidFields.join(', ')}`);
      }
  
      result.warnings = warnings;
      result.missingFields = missingFields;
      result.invalidFields = invalidFields;
      result.missingFieldCount = missingFields.length;
      result.invalidFieldCount = invalidFields.length;
      result.incompleteItemCount = incompleteItemCount;
  
      result.notificationMessage = `データが不完全です。検証を実行できません。${warnings.length > 0 ? warnings.join(' ') : ''}`;
    } else {
      result.canExecuteVerification = true;
      result.statusCode = 'READY_FOR_VERIFICATION';
      result.skipVerification = false;
      result.warnings = [];
      result.missingFields = [];
      result.invalidFields = [];
      result.missingFieldCount = 0;
      result.invalidFieldCount = 0;
      result.incompleteItemCount = 0;
      result.notificationMessage = '';
      result.errorCode = '';
    }
  
    return result;
  }
  return { validateMonthlyVerificationTiming };
})();
export const validateMonthlyVerificationTiming = __aivicBundle_155_validateMonthlyVerificationTiming.validateMonthlyVerificationTiming;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateMonthlyVerificationTiming */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculateDemandPredictionAccuracy exports=calculateDemandPredictionAccuracy */
const __aivicBundle_156_calculateDemandPredictionAccuracy = (() => {
  function calculateDemandPredictionAccuracy(
    datasets: Array<{
      categoryId: string;
      categoryName: string;
      predictedValue: number;
      actualValue: number;
    }>
  ): {
    accuracyRate: number;
    deviationRate: number;
    categoryErrors: Array<{
      categoryId: string;
      categoryName: string;
      errorRate: number;
      totalAbsoluteError: number;
      totalActualValue: number;
      dataPointCount: number;
    }>;
    totalDataPoints: number;
    totalAbsoluteError: number;
    totalActualValue: number;
    dashboardDisplay: {
      accuracyPercentage: number;
      deviationPercentage: number;
      categoryBreakdown: Array<{
        categoryId: string;
        categoryName: string;
        errorPercentage: number;
      }>;
    };
    exportData: {
      csvHeaders: string[];
      csvRows: Array<string[]>;
      summaryRow: string[];
    };
  } {
    if (!datasets || datasets.length === 0) {
      return {
        accuracyRate: 100,
        deviationRate: 0,
        categoryErrors: [],
        totalDataPoints: 0,
        totalAbsoluteError: 0,
        totalActualValue: 0,
        dashboardDisplay: {
          accuracyPercentage: 100,
          deviationPercentage: 0,
          categoryBreakdown: [],
        },
        exportData: {
          csvHeaders: [
            'カテゴリID',
            'カテゴリ名',
            'データ件数',
            '絶対誤差合計',
            '実績値合計',
            '誤差率（%）',
          ],
          csvRows: [],
          summaryRow: ['全体', '', '0', '0', '0', '0.00'],
        },
      };
    }
  
    // Group datasets by category
    const categoryMap = new Map<
      string,
      {
        categoryName: string;
        predictions: number[];
        actuals: number[];
      }
    >();
  
    for (const dataset of datasets) {
      if (!categoryMap.has(dataset.categoryId)) {
        categoryMap.set(dataset.categoryId, {
          categoryName: dataset.categoryName,
          predictions: [],
          actuals: [],
        });
      }
      const category = categoryMap.get(dataset.categoryId)!;
      category.predictions.push(dataset.predictedValue);
      category.actuals.push(dataset.actualValue);
    }
  
    // Calculate category-level metrics
    const categoryErrors: Array<{
      categoryId: string;
      categoryName: string;
      errorRate: number;
      totalAbsoluteError: number;
      totalActualValue: number;
      dataPointCount: number;
    }> = [];
  
    let totalAbsoluteError = 0;
    let totalActualValue = 0;
  
    for (const [categoryId, categoryData] of categoryMap.entries()) {
      let categoryAbsoluteError = 0;
      let categoryActualSum = 0;
  
      for (let i = 0; i < categoryData.predictions.length; i++) {
        const error = Math.abs(
          categoryData.predictions[i] - categoryData.actuals[i]
        );
        categoryAbsoluteError += error;
        categoryActualSum += categoryData.actuals[i];
      }
  
      totalAbsoluteError += categoryAbsoluteError;
      totalActualValue += categoryActualSum;
  
      const errorRate =
        categoryActualSum > 0
          ? (categoryAbsoluteError / categoryActualSum) * 100
          : 0;
  
      categoryErrors.push({
        categoryId,
        categoryName: categoryData.categoryName,
        errorRate,
        totalAbsoluteError: categoryAbsoluteError,
        totalActualValue: categoryActualSum,
        dataPointCount: categoryData.predictions.length,
      });
    }
  
    // Calculate overall metrics
    const totalDataPoints = datasets.length;
    const meanAbsoluteError =
      totalDataPoints > 0 ? totalAbsoluteError / totalDataPoints : 0;
    const meanActualValue =
      totalDataPoints > 0 ? totalActualValue / totalDataPoints : 0;
  
    const accuracyRate =
      meanActualValue > 0
        ? Math.max(0, (1 - meanAbsoluteError / meanActualValue) * 100)
        : 100;
  
    const deviationRate =
      totalActualValue > 0 ? (totalAbsoluteError / totalActualValue) * 100 : 0;
  
    // Build dashboard display
    const dashboardDisplay = {
      accuracyPercentage: accuracyRate,
      deviationPercentage: deviationRate,
      categoryBreakdown: categoryErrors.map((cat) => ({
        categoryId: cat.categoryId,
        categoryName: cat.categoryName,
        errorPercentage: cat.errorRate,
      })),
    };
  
    // Build export data (CSV format)
    const csvHeaders = [
      'カテゴリID',
      'カテゴリ名',
      'データ件数',
      '絶対誤差合計',
      '実績値合計',
      '誤差率（%）',
    ];
  
    const csvRows = categoryErrors.map((cat) => [
      cat.categoryId,
      cat.categoryName,
      cat.dataPointCount.toString(),
      cat.totalAbsoluteError.toString(),
      cat.totalActualValue.toString(),
      cat.errorRate.toFixed(2),
    ]);
  
    const summaryRow = [
      '全体',
      '',
      totalDataPoints.toString(),
      totalAbsoluteError.toString(),
      totalActualValue.toString(),
      deviationRate.toFixed(2),
    ];
  
    const exportData = {
      csvHeaders,
      csvRows,
      summaryRow,
    };
  
    return {
      accuracyRate,
      deviationRate,
      categoryErrors,
      totalDataPoints,
      totalAbsoluteError,
      totalActualValue,
      dashboardDisplay,
      exportData,
    };
  }
  return { calculateDemandPredictionAccuracy };
})();
export const calculateDemandPredictionAccuracy = __aivicBundle_156_calculateDemandPredictionAccuracy.calculateDemandPredictionAccuracy;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateDemandPredictionAccuracy */

