      const threshold = input.accuracy_decline_threshold_percent;
  
      const declinePercent = ((previousAccuracy - currentAccuracy) / previousAccuracy) * 100;
      const isDeclineDetected = declinePercent >= threshold;
  
      return {
        is_decline_detected: isDeclineDetected,
        decline_percent: declinePercent,
        meets_alert_threshold: isDeclineDetected
      };
