/* AIVIC_FUNCTION_BUNDLE_START owner=determinePriorityForExternalFactors exports=determinePriorityForExternalFactors */
const __aivicBundle_166_determinePriorityForExternalFactors = (() => {
  interface DeterminePriorityForExternalFactorsInput {
    variableId: string;
    variableName: string;
    correlationCoefficient: number;
    precisionImpactScore: number;
    implementationDifficultyScore: number;
  }
  
  interface PrioritizedVariable {
    variableId: string;
    variableName: string;
    priorityScore: number;
    priorityRank: number;
    precisionImpactScore: number;
    implementationDifficultyScore: number;
  }
  
  interface RoutingListItem {
    variableId: string;
    variableName: string;
    assignedApprover: string;
    approvalLevel: number;
    routingStatus: string;
    routingInitiatedAt: string;
  }
  
  interface DeterminePriorityForExternalFactorsResult {
    prioritizedVariables: PrioritizedVariable[];
    approvalRoutingInitiated: boolean;
    routingList: RoutingListItem[];
    priorityDeterminationCompletedAt: string;
    priorityDeterminationStatus: string;
    totalVariablesProcessed: number;
  }
  
  const approverHierarchy = ['Director', 'Senior Manager', 'Manager', 'Lead'];
  
   function determinePriorityForExternalFactors(
    externalFactorVariables: DeterminePriorityForExternalFactorsInput[]
  ): DeterminePriorityForExternalFactorsResult {
    const now = new Date().toISOString();
  
    // Calculate priority scores using the formula: impact / (1 + difficulty * 0.01)
    const prioritizedVariables = externalFactorVariables.map((variable) => {
      const priorityScore =
        variable.precisionImpactScore /
        (1 + variable.implementationDifficultyScore * 0.01);
  
      return {
        variableId: variable.variableId,
        variableName: variable.variableName,
        priorityScore,
        priorityRank: 0, // Will be assigned after sorting
        precisionImpactScore: variable.precisionImpactScore,
        implementationDifficultyScore: variable.implementationDifficultyScore,
      };
    });
  
    // Sort by priority score descending and assign ranks
    prioritizedVariables.sort((a, b) => b.priorityScore - a.priorityScore);
    prioritizedVariables.forEach((variable, index) => {
      variable.priorityRank = index + 1;
    });
  
    // Create routing list based on priority ranks
    const routingList: RoutingListItem[] = prioritizedVariables.map(
      (variable) => ({
        variableId: variable.variableId,
        variableName: variable.variableName,
        assignedApprover:
          approverHierarchy[variable.priorityRank - 1] || 'Lead',
        approvalLevel: variable.priorityRank,
        routingStatus: 'pending',
        routingInitiatedAt: now,
      })
    );
  
    return {
      prioritizedVariables,
      approvalRoutingInitiated: true,
      routingList,
      priorityDeterminationCompletedAt: now,
      priorityDeterminationStatus: 'completed',
      totalVariablesProcessed: externalFactorVariables.length,
    };
  }
  return { determinePriorityForExternalFactors };
})();
export const determinePriorityForExternalFactors = __aivicBundle_166_determinePriorityForExternalFactors.determinePriorityForExternalFactors;
/* AIVIC_FUNCTION_BUNDLE_END owner=determinePriorityForExternalFactors */

/* AIVIC_FUNCTION_BUNDLE_START owner=evaluateModelImprovementProposalPriority exports=evaluateModelImprovementProposalPriority */
const __aivicBundle_167_evaluateModelImprovementProposalPriority = (() => {
  function evaluateModelImprovementProposalPriority(proposal: any): any {
    const result: any = {
      proposal_id: proposal.proposal_id,
      routing_status: 'PENDING',
      evaluation_timestamp: proposal.proposal_timestamp,
    };
  
    // Check for missing accuracy_impact_rate in external_factor_variables
    if (proposal.external_factor_variables && Array.isArray(proposal.external_factor_variables)) {
      const hasMissingAccuracyImpact = proposal.external_factor_variables.some(
        (variable: any) => variable.accuracy_impact_rate === undefined || variable.accuracy_impact_rate === null
      );
  
      if (hasMissingAccuracyImpact) {
        result.error_message = '外部要因変数の精度影響度データが欠落しています';
        result.routing_status = 'PENDING';
        result.variables_with_priority = undefined;
        return result;
      }
  
      // Calculate priority scores for each variable
      const variablesWithPriority = proposal.external_factor_variables.map((variable: any) => {
        const accuracyWeight = 0.4;
        const correlationWeight = 0.3;
        const significanceWeight = 0.2;
        const difficultyWeight = 0.1;
  
        const normalizedDifficulty = Math.max(0, 100 - (variable.implementation_difficulty_score || 0));
        const priorityScore =
          (variable.accuracy_impact_rate || 0) * 100 * accuracyWeight +
          (variable.correlation_coefficient || 0) * 100 * correlationWeight +
          (variable.statistical_significance || 0) * 100 * significanceWeight +
          normalizedDifficulty * difficultyWeight;
  
        return {
          variable_id: variable.variable_id,
          variable_name: variable.variable_name,
          priority_score: Math.round(priorityScore * 10) / 10,
        };
      });
  
      result.variables_with_priority = variablesWithPriority;
  
      // Calculate overall proposal priority
      const avgAccuracyImpact =
        variablesWithPriority.reduce((sum: number, v: any) => sum + v.priority_score, 0) /
        variablesWithPriority.length;
  
      const avgDifficulty =
        proposal.external_factor_variables.reduce(
          (sum: number, v: any) => sum + (v.implementation_difficulty_score || 0),
          0
        ) / proposal.external_factor_variables.length;
  
      const priorityScore = Math.max(0, Math.min(100, avgAccuracyImpact - avgDifficulty * 0.3));
  
      result.priority_score = Math.round(priorityScore * 10) / 10;
  
      if (priorityScore >= 70) {
        result.routing_status = 'APPROVED';
        result.recommended_action = 'approve';
      } else if (priorityScore >= 40) {
        result.routing_status = 'CONDITIONAL';
        result.recommended_action = 'conditional';
      } else {
        result.routing_status = 'REJECTED';
        result.recommended_action = 'reject';
      }
    }
  
    return result;
  }
  return { evaluateModelImprovementProposalPriority };
})();
