/* AIVIC_FUNCTION_BUNDLE_START owner=judgeModelImprovementProposalVariablePriority exports=judgeModelImprovementProposalVariablePriority */
const __aivicBundle_168_judgeModelImprovementProposalVariablePriority = (() => {
  function judgeModelImprovementProposalVariablePriority(
    variables: Array<{
      variable_id: string;
      variable_name: string;
      priority_score: number;
      usage_frequency: number;
      impact_level: number;
      update_frequency: number;
    }>
  ): Array<{
    variable_id: string;
    variable_name: string;
    priority_score: number;
    usage_frequency: number;
    impact_level: number;
    update_frequency: number;
  }> {
    if (!variables || variables.length === 0) {
      return [];
    }
  
    const sorted = [...variables].sort((a, b) => {
      // Primary: priority_score (descending)
      if (a.priority_score !== b.priority_score) {
        return b.priority_score - a.priority_score;
      }
  
      // Secondary: impact_level (descending)
      if (a.impact_level !== b.impact_level) {
        return b.impact_level - a.impact_level;
      }
  
      // Tertiary: usage_frequency (descending)
      if (a.usage_frequency !== b.usage_frequency) {
        return b.usage_frequency - a.usage_frequency;
      }
  
      // Quaternary: update_frequency (descending)
      if (a.update_frequency !== b.update_frequency) {
        return b.update_frequency - a.update_frequency;
      }
  
      // Fallback: maintain original order by variable_id
      return a.variable_id.localeCompare(b.variable_id);
    });
  
    return sorted;
  }
  return { judgeModelImprovementProposalVariablePriority };
})();
