/* AIVIC_FUNCTION_BUNDLE_START owner=assignExternalDataTrustScore exports=assignExternalDataTrustScore */
const __aivicBundle_170_assignExternalDataTrustScore = (() => {
  function assignExternalDataTrustScore(
    dataSource: any,
    adoptionThreshold: number
  ): any {
    // データソースの信頼度スコア（0-100）を計算
    let trustScore = 0;
  
    // データタイプ別の基本スコア計算
    if (dataSource.data_type === 'weather') {
      // 気象データの信頼度計算
      let baseScore = 50;
  
      // ソースの信頼性
      if (dataSource.source === 'meteorological_agency') {
        baseScore = 80;
      } else if (dataSource.source === 'third_party_vendor') {
        baseScore = 40;
      }
  
      // データ品質フラグの確認
      if (dataSource.data_quality_flags) {
        const flags = dataSource.data_quality_flags;
        
        if (flags.sensor_status === 'operational') {
          baseScore += 5;
        } else if (flags.sensor_status === 'maintenance') {
          baseScore -= 15;
        }
  
        if (flags.calibration_status === 'valid') {
          baseScore += 5;
        } else if (flags.calibration_status === 'expired') {
          baseScore -= 10;
        }
  
        if (flags.missing_values && flags.missing_values > 0) {
          baseScore -= flags.missing_values * 3;
        }
      }
  
      trustScore = Math.max(0, Math.min(100, baseScore));
    } else if (dataSource.data_type === 'event') {
      // イベントデータの信頼度計算
      let baseScore = 50;
  
      // ソースの信頼性
      if (dataSource.source === 'official_calendar') {
        baseScore = 75;
      } else if (dataSource.source === 'user_submission') {
        baseScore = 30;
      }
  
      // 信頼度フラグの確認
      if (dataSource.confidence_source_flags) {
        const flags = dataSource.confidence_source_flags;
  
        if (flags.multi_source_confirmed) {
          baseScore += 5;
        }
  
        if (flags.historical_validation) {
          baseScore += 5;
        }
  
        if (flags.lead_time_days && flags.lead_time_days >= 30) {
          baseScore += 3;
        } else if (flags.lead_time_days && flags.lead_time_days < 7) {
          baseScore -= 5;
        }
      }
  
      // インパクトレベルの考慮
      if (dataSource.expected_impact_level === 'high') {
        baseScore += 3;
      } else if (dataSource.expected_impact_level === 'low') {
        baseScore -= 3;
      }
  
      // カバレッジ範囲の考慮
      if (dataSource.coverage_region === 'nationwide') {
        baseScore += 3;
      } else if (dataSource.coverage_region === 'local') {
        baseScore -= 3;
      }
  
      trustScore = Math.max(0, Math.min(100, baseScore));
    } else if (dataSource.data_type === 'competitor_strategy') {
      // 競合施策データの信頼度計算
      let baseScore = 50;
  
      // ソースの信頼性
      if (dataSource.source === 'competitor_official_site') {
        baseScore = 80;
      } else if (dataSource.source === 'social_media_rumor') {
        baseScore = 25;
      }
  
      // 検証フラグの確認
      if (dataSource.verification_flags) {
        const flags = dataSource.verification_flags;
  
        if (flags.source_verified) {
          baseScore += 5;
        } else {
          baseScore -= 10;
        }
  
        if (flags.price_tracked) {
          baseScore += 3;
        } else {
          baseScore -= 5;
        }
  
        if (flags.inventory_impact_observed) {
          baseScore += 2;
        } else {
          baseScore -= 3;
        }
      }
  
      trustScore = Math.max(0, Math.min(100, baseScore));
    }
  
    // 採用判定
    const adoptionJudgment = trustScore >= adoptionThreshold;
    const adoptionReason = adoptionJudgment
      ? `信頼度スコア(${trustScore})が採用基準(${adoptionThreshold})以上のため採用対象`
      : `信頼度スコア(${trustScore})が採用基準(${adoptionThreshold})未満のため不採用`;
  
    return {
      trust_score: trustScore,
      adoption_judgment: adoptionJudgment,
      adoption_reason: adoptionReason,
      dataSourceId: dataSource.source || 'unknown',
      confidenceLevel: trustScore / 100,
      lastValidatedAt: dataSource.recorded_at || dataSource.scheduled_date || new Date().toISOString(),
      isReliable: adoptionJudgment
    };
  }
  return { assignExternalDataTrustScore };
})();
