    let feasibility = 100;
  
    if (proposal.estimatedImplementationHours !== undefined) {
      // Normalize hours: 0-40 hours = high feasibility, 100+ = low
      const hours = proposal.estimatedImplementationHours;
      feasibility -= Math.min(50, (hours / 100) * 50);
    }
  
    if (proposal.riskLevel) {
      const riskPenalty =
        proposal.riskLevel === 'high'
          ? 30
          : proposal.riskLevel === 'medium'
            ? 15
            : 0;
      feasibility -= riskPenalty;
    }
  
    return Math.min(100, Math.max(0, feasibility));
