/* AIVIC_FUNCTION_BUNDLE_START owner=determineVariablePriorityOrder exports=determineVariablePriorityOrder */
const __aivicBundle_175_determineVariablePriorityOrder = (() => {
  interface DetermineVariablePriorityOrderInput {
    id: string;
    name: string;
    impact: number;
    implementationDifficulty: number;
    registrationOrder: number;
    description?: string;
  }
  
  interface DetermineVariablePriorityOrderOutput {
    id: string;
    priorityRank: number;
    matrixPosition: {
      impact: number;
      implementationDifficulty: number;
    };
    secondaryRankingBasis: string;
  }
  
   function determineVariablePriorityOrder(
    variables: DetermineVariablePriorityOrderInput[]
  ): DetermineVariablePriorityOrderOutput[] {
    if (!variables || variables.length === 0) {
      return [];
    }
  
    // Group variables by matrix position (impact, implementationDifficulty)
    const groupedByMatrix = new Map<
      string,
      DetermineVariablePriorityOrderInput[]
    >();
  
    variables.forEach((variable) => {
      const matrixKey = `${variable.impact}_${variable.implementationDifficulty}`;
      if (!groupedByMatrix.has(matrixKey)) {
        groupedByMatrix.set(matrixKey, []);
      }
      groupedByMatrix.get(matrixKey)!.push(variable);
    });
  
    // Sort groups by matrix position (higher impact first, then lower difficulty first)
    const sortedGroups = Array.from(groupedByMatrix.entries()).sort(
      ([keyA], [keyB]) => {
        const [impactA, diffA] = keyA.split("_").map(Number);
        const [impactB, diffB] = keyB.split("_").map(Number);
  
        if (impactB !== impactA) {
          return impactB - impactA;
        }
        return diffA - diffB;
      }
    );
  
    const results: DetermineVariablePriorityOrderOutput[] = [];
    let globalRank = 1;
  
    // Process each matrix group
    sortedGroups.forEach(([matrixKey, groupVariables]) => {
      const [impact, implementationDifficulty] = matrixKey
        .split("_")
        .map(Number);
  
      // Within the same matrix position, sort by registrationOrder (ascending)
      const sortedByRegistration = groupVariables.sort(
        (a, b) => a.registrationOrder - b.registrationOrder
      );
  
      // Assign priority ranks within this group
      sortedByRegistration.forEach((variable) => {
        results.push({
          id: variable.id,
          priorityRank: globalRank,
          matrixPosition: {
            impact,
            implementationDifficulty,
          },
          secondaryRankingBasis: `registration order: ${variable.registrationOrder}`,
        });
        globalRank++;
      });
    });
  
    return results;
  }
  return { determineVariablePriorityOrder };
})();
export const determineVariablePriorityOrder = __aivicBundle_175_determineVariablePriorityOrder.determineVariablePriorityOrder;
/* AIVIC_FUNCTION_BUNDLE_END owner=determineVariablePriorityOrder */

