/* AIVIC_FUNCTION_BUNDLE_START owner=validateAndCreateRuleSpecVersion exports=validateAndCreateRuleSpecVersion */
const __aivicBundle_180_validateAndCreateRuleSpecVersion = (() => {
  interface ValidateAndCreateRuleSpecVersionInput {
    fileContent: string;
    fileName: string;
    mimeType: string;
  }
  
  interface ValidateAndCreateRuleSpecVersionResult {
    versionId: string;
    versionNumber: number;
    seasonalPattern: string[];
    discountRateThreshold: number;
    salesPeriod: string[];
    lastUpdated: string;
    createdBy: string;
    status: string;
    validationStatus: string;
    httpStatusCode: number;
  }
  
   function validateAndCreateRuleSpecVersion(
    input: ValidateAndCreateRuleSpecVersionInput
  ): ValidateAndCreateRuleSpecVersionResult {
    const { fileContent, fileName, mimeType } = input;
  
    // ファイル形式の検証
    const supportedMimeTypes = ["application/json"];
    const supportedExtensions = [".json"];
  
    if (!supportedMimeTypes.includes(mimeType)) {
      throw new Error(`サポートされていない形式: ${mimeType}`);
    }
  
    const fileExtension = fileName.substring(fileName.lastIndexOf("."));
    if (!supportedExtensions.includes(fileExtension)) {
      throw new Error(`サポートされていない形式: ${fileExtension}`);
    }
  
    // JSON パースの検証
    let parsedContent: any;
    try {
      parsedContent = JSON.parse(fileContent);
    } catch {
      throw new Error(`JSON形式が不正です`);
    }
  
    // 必須フィールドの検証
    const requiredFields = [
      "seasonalPattern",
      "discountRateThreshold",
      "salesPeriod",
    ];
    const missingFields = requiredFields.filter((field) => !(field in parsedContent));
  
    if (missingFields.length > 0) {
      throw new Error(`形式エラー: 必須フィールドが欠落しています`);
    }
  
    // バージョンID生成
    const versionId = randomUUID();
  
    // 戻り値の構築
    const result: ValidateAndCreateRuleSpecVersionResult = {
      versionId,
      versionNumber: parsedContent.versionNumber ?? 1,
      seasonalPattern: parsedContent.seasonalPattern,
      discountRateThreshold: parsedContent.discountRateThreshold,
      salesPeriod: parsedContent.salesPeriod,
      lastUpdated: parsedContent.lastUpdated,
      createdBy: parsedContent.createdBy,
      status: parsedContent.status,
      validationStatus: "passed",
      httpStatusCode: 200,
    };
  
    return result;
  }
  return { validateAndCreateRuleSpecVersion };
})();
export const validateAndCreateRuleSpecVersion = __aivicBundle_180_validateAndCreateRuleSpecVersion.validateAndCreateRuleSpecVersion;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateAndCreateRuleSpecVersion */

/* AIVIC_FUNCTION_BUNDLE_START owner=detectAndResolveRuleVersionConflicts exports=detectAndResolveRuleVersionConflicts */
const __aivicBundle_181_detectAndResolveRuleVersionConflicts = (() => {
  interface DetectAndResolveRuleVersionConflictsInput {
    baseRuleSpecId: string;
    currentVersion: string;
    updateRequests: Array<{
      ruleSpecId: string;
      currentVersion: string;
      newVersion: string;
      ruleContent: Record<string, any>;
      updatedBy: string;
      updatedAt: Date;
      conflictKey: string;
    }>;
    conflictResolutionStrategy: string;
  }
  
  interface GeneratedVersion {
    versionNumber: string;
    sequenceOrder: number;
    conflictFlag: boolean;
    ruleContent: Record<string, any>;
  }
  
  interface ConflictHistoryLogEntry {
    updateRequestId: string;
    versionGenerated: string;
    conflictDetectedAt: Date;
    resolvedVersionNumber: string;
    resolutionStrategy: string;
  }
  
  interface VersionHistoryEntry {
    versionNumber: string;
    hasConflict: boolean;
  }
  
  interface RuleSpecFinalState {
    ruleSpecId: string;
    latestVersion: string;
    totalVersionsGenerated: number;
    allVersionsResolved: boolean;
    versionHistory: VersionHistoryEntry[];
  }
  
  interface DetectAndResolveRuleVersionConflictsResult {
    conflictDetected: boolean;
    conflictCount: number;
    conflictKey: string;
    generatedVersions: GeneratedVersion[];
    conflictHistoryLog: ConflictHistoryLogEntry[];
    conflictResolvedAt: Date;
    ruleSpecFinalState: RuleSpecFinalState;
    allConflictsResolved: boolean;
    resolutionSuccessful: boolean;
  }
  
   function detectAndResolveRuleVersionConflicts(
    input: DetectAndResolveRuleVersionConflictsInput
  ): DetectAndResolveRuleVersionConflictsResult {
    const {
      baseRuleSpecId,
      currentVersion,
      updateRequests,
      conflictResolutionStrategy,
    } = input;
  
    const conflictKey = updateRequests.length > 0
      ? updateRequests[0].conflictKey
      : `${baseRuleSpecId}:${new Date().getTime()}`;
  
    const conflictDetected = updateRequests.length > 1;
    const conflictCount = updateRequests.length;
  
    const generatedVersions: GeneratedVersion[] = [];
    const conflictHistoryLog: ConflictHistoryLogEntry[] = [];
  
    const [majorStr, minorStr] = currentVersion.split('.');
    let major = parseInt(majorStr, 10);
    let minor = parseInt(minorStr || '0', 10);
  
    const resolvedAt = new Date();
  
    updateRequests.forEach((request, index) => {
      minor += 1;
      const newVersionNumber = `${major}.${minor}`;
  
      const generatedVersion: GeneratedVersion = {
        versionNumber: newVersionNumber,
        sequenceOrder: index + 1,
        conflictFlag: true,
        ruleContent: request.ruleContent,
      };
  
      generatedVersions.push(generatedVersion);
  
      const historyEntry: ConflictHistoryLogEntry = {
        updateRequestId: `${request.conflictKey}:${request.updatedBy}`,
        versionGenerated: newVersionNumber,
        conflictDetectedAt: request.updatedAt,
        resolvedVersionNumber: newVersionNumber,
        resolutionStrategy: conflictResolutionStrategy,
      };
  
      conflictHistoryLog.push(historyEntry);
    });
  
    const versionHistory: VersionHistoryEntry[] = [
      {
        versionNumber: currentVersion,
        hasConflict: false,
      },
    ];
  
    generatedVersions.forEach((gv) => {
      versionHistory.push({
        versionNumber: gv.versionNumber,
        hasConflict: gv.conflictFlag,
      });
    });
  
    const ruleSpecFinalState: RuleSpecFinalState = {
      ruleSpecId: baseRuleSpecId,
      latestVersion:
        generatedVersions.length > 0
          ? generatedVersions[generatedVersions.length - 1].versionNumber
          : currentVersion,
      totalVersionsGenerated: generatedVersions.length,
      allVersionsResolved: true,
      versionHistory: versionHistory,
    };
  
    return {
      conflictDetected: conflictDetected,
      conflictCount: conflictCount,
      conflictKey: conflictKey,
      generatedVersions: generatedVersions,
      conflictHistoryLog: conflictHistoryLog,
      conflictResolvedAt: resolvedAt,
      ruleSpecFinalState: ruleSpecFinalState,
      allConflictsResolved: true,
      resolutionSuccessful: true,
    };
  }
  return { detectAndResolveRuleVersionConflicts };
})();
export const detectAndResolveRuleVersionConflicts = __aivicBundle_181_detectAndResolveRuleVersionConflicts.detectAndResolveRuleVersionConflicts;
/* AIVIC_FUNCTION_BUNDLE_END owner=detectAndResolveRuleVersionConflicts */

