const __aivicBundle_182_distributeRuleSpecification = (() => {
  interface DistributeRuleSpecificationInput {
    specificationId?: string;
    specificationTitle?: string;
    specificationVersion?: string;
    createdAt?: Date;
    updatedAt?: Date;
    distributionTargets?: Array<{
      userId?: string;
      userName?: string;
      email?: string;
      role?: string;
    }>;
    distributionSchedule?: {
      scheduledAt?: Date;
      distributionMethod?: string;
      requireConfirmation?: boolean;
    };
    ruleSpecificationId?: string;
    ruleSpecContent?: Record<string, any>;
    distributionTargetList?: Array<any>;
  }
  
  interface DistributeRuleSpecificationResult {
    specificationId?: string;
    distributionId: string;
    distributionStatus: string;
    targetCount: number;
    distributedCount: number;
    confirmedCount: number;
    unconfirmedCount: number;
    scheduledAt?: Date;
    timestamp: string;
  }
  
   function distributeRuleSpecification(
    input: DistributeRuleSpecificationInput
  ): DistributeRuleSpecificationResult {
    // Validate that target list is not empty
    const targets = input.distributionTargets || input.distributionTargetList || [];
    
    if (targets.length === 0) {
      throw new Error("対象者リストが空です");
    }
  
    const distributionId = randomUUID();
    const specificationId =
      input.specificationId || input.ruleSpecificationId || randomUUID();
    const scheduledAt =
      input.distributionSchedule?.scheduledAt || new Date();
    const timestamp = new Date().toISOString();
  
    // Initial state: scheduled, not yet distributed
    const targetCount = targets.length;
    const distributedCount = 0;
    const confirmedCount = 0;
    const unconfirmedCount = targetCount;
    const distributionStatus = "scheduled";
  
    return {
      specificationId,
      distributionId,
      distributionStatus,
      targetCount,
      distributedCount,
      confirmedCount,
      unconfirmedCount,
      scheduledAt,
      timestamp,
    };
  }
  return { distributeRuleSpecification };
})();
