const __aivicBundle_186_calculateDiscountedMenuItemPrice = (() => {
  function calculateDiscountedMenuItemPrice(input: {
    basePrice: number;
    discountRatePercent: number;
  }): {
    discountedPrice: number;
    discountRatePercent: number;
    error?: undefined;
    hasAnomalyFlag: boolean;
    discountAmount: number;
    discountCoefficient: number;
  } {
    const { basePrice, discountRatePercent } = input;
  
    const discountCoefficient = 1 - discountRatePercent / 100;
    const discountedPrice = basePrice * discountCoefficient;
    const discountAmount = basePrice - discountedPrice;
  
    return {
      discountedPrice,
      discountRatePercent,
      error: undefined,
      hasAnomalyFlag: false,
      discountAmount,
      discountCoefficient,
    };
  }
  return { calculateDiscountedMenuItemPrice };
})();
