/* AIVIC_FUNCTION_BUNDLE_START owner=calculateIngredientsSeasonalDiscountPriorityScore exports=calculateIngredientsSeasonalDiscountPriorityScore */
const __aivicBundle_187_calculateIngredientsSeasonalDiscountPriorityScore = (() => {
  interface CalculateIngredientsSeasonalDiscountPriorityScoreInput {
    id: string;
    name: string;
    base_priority: number;
    seasonal_relevance: string;
    seasonal_coefficient: number;
    discount_rate: number;
    is_in_season: boolean;
    nutritional_value: number;
  }
  
  interface ScoredIngredient {
    ingredient_id: string;
    ingredient_name: string;
    seasonal_relevance: string;
    priority_score: number;
  }
  
  interface CalculateIngredientsSeasonalDiscountPriorityScoreResult {
    scored_ingredients: ScoredIngredient[];
    recommended_meal_ingredients: string[];
    total_priority_score: number;
    calculation_timestamp: string;
    applied_season: string;
    ingredient_count: number;
    seasonal_ingredient_count: number;
    average_discount_rate: number;
  }
  
   function calculateIngredientsSeasonalDiscountPriorityScore(
    ingredients: CalculateIngredientsSeasonalDiscountPriorityScoreInput[],
    current_season: string,
    current_date: Date
  ): CalculateIngredientsSeasonalDiscountPriorityScoreResult {
    // Calculate priority score for each ingredient
    // Formula: priority_score = base_priority × seasonal_coefficient × (1 + discount_rate)
    const scored_ingredients: ScoredIngredient[] = ingredients.map((ing) => ({
      ingredient_id: ing.id,
      ingredient_name: ing.name,
      seasonal_relevance: ing.seasonal_relevance,
      priority_score: ing.base_priority * ing.seasonal_coefficient * (1 + ing.discount_rate),
    }));
  
    // Sort by priority_score in descending order
    scored_ingredients.sort((a, b) => b.priority_score - a.priority_score);
  
    // Get top 3 recommended ingredients
    const recommended_meal_ingredients = scored_ingredients
      .slice(0, 3)
      .map((item) => item.ingredient_id);
  
    // Calculate total priority score of top 3
    const total_priority_score = scored_ingredients
      .slice(0, 3)
      .reduce((sum, item) => sum + item.priority_score, 0);
  
    // Count seasonal ingredients (is_in_season = true)
    const seasonal_ingredient_count = ingredients.filter((ing) => ing.is_in_season).length;
  
    // Calculate average discount rate
    const average_discount_rate =
      ingredients.reduce((sum, ing) => sum + ing.discount_rate, 0) / ingredients.length;
  
    return {
      scored_ingredients,
      recommended_meal_ingredients,
      total_priority_score,
      calculation_timestamp: current_date.toISOString(),
      applied_season: current_season,
      ingredient_count: ingredients.length,
      seasonal_ingredient_count,
      average_discount_rate,
    };
  }
  return { calculateIngredientsSeasonalDiscountPriorityScore };
})();
export const calculateIngredientsSeasonalDiscountPriorityScore = __aivicBundle_187_calculateIngredientsSeasonalDiscountPriorityScore.calculateIngredientsSeasonalDiscountPriorityScore;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateIngredientsSeasonalDiscountPriorityScore */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculateSeasonalPatternScore exports=calculateSeasonalPatternScore */
const __aivicBundle_188_calculateSeasonalPatternScore = (() => {
  function calculateSeasonalPatternScore(input: any): number {
    // Handle both function signature styles
    const ruleSpec = input.ruleId !== undefined ? input : input;
    
    // Check if seasonalPatternRules array is provided and empty
    if (input.seasonalPatternRules !== undefined && Array.isArray(input.seasonalPatternRules) && input.seasonalPatternRules.length === 0) {
      throw new Error('季節パターンルールが定義されていません');
    }
    
    // If ruleSpec has ruleId (direct SeasonalRuleSpec input)
    if (ruleSpec.ruleId !== undefined) {
      const applicableMonthsCount = ruleSpec.applicableMonths?.length ?? 0;
      const ingredientCategoriesCount = ruleSpec.ingredientCategories?.length ?? 0;
      const discountPercentage = ruleSpec.discountPercentage ?? 0;
      
      // Calculate base score from applicable months (0-40 points)
      // 3 months = 30, 6 months = 40, 12 months = 0 (too broad)
      let monthScore = 0;
      if (applicableMonthsCount === 3) {
        monthScore = 30;
      } else if (applicableMonthsCount === 6) {
        monthScore = 40;
      } else if (applicableMonthsCount > 6 && applicableMonthsCount < 12) {
        monthScore = 35;
      } else if (applicableMonthsCount === 12) {
        monthScore = 0;
      } else if (applicableMonthsCount > 0) {
        monthScore = Math.min(40, (applicableMonthsCount / 3) * 30);
      }
      
      // Calculate score from ingredient categories diversity (0-35 points)
      let categoryScore = 0;
      if (ingredientCategoriesCount === 0) {
        categoryScore = 0;
      } else if (ingredientCategoriesCount === 1) {
        categoryScore = 15;
      } else if (ingredientCategoriesCount === 2) {
        categoryScore = 25;
      } else {
        categoryScore = 35;
      }
      
      // Calculate score from discount percentage (0-25 points)
      const discountScore = Math.min(25, (discountPercentage / 20) * 25);
      
      // Calculate score from validation status (0-5 points)
      let validationScore = 0;
      if (ruleSpec.validationStatus === 'approved') {
        validationScore = 5;
      } else if (ruleSpec.validationStatus === 'pending') {
        validationScore = 2;
      }
      
      // Total score capped at 100
      const totalScore = Math.min(100, monthScore + categoryScore + discountScore + validationScore);
      
      return Math.round(totalScore);
    }
    
    // If input has ingredientDate and other inventory-related fields
    if (input.ingredientDate !== undefined) {
      const inventoryLevel = input.currentInventoryLevel ?? 0;
      const discountThreshold = input.discountThreshold ?? 0;
      const category = input.ingredientCategory ?? '';
      
      // Base score from inventory level relative to threshold
      let inventoryScore = 0;
      if (inventoryLevel > discountThreshold) {
        inventoryScore = Math.min(40, (inventoryLevel / (discountThreshold * 2)) * 40);
      } else {
        inventoryScore = 20;
      }
      
      // Category diversity score
      const categoryScore = category && category.length > 0 ? 30 : 0;
      
      // Date-based seasonality score
      const date = input.ingredientDate instanceof Date ? input.ingredientDate : new Date(input.ingredientDate);
      const month = date.getMonth() + 1;
      let seasonScore = 0;
      
      // Spring (3-5), Summer (6-8), Fall (9-11), Winter (12, 1-2)
      if ((month >= 3 && month <= 5) || (month >= 6 && month <= 8) || (month >= 9 && month <= 11) || month === 12 || month === 1 || month === 2) {
        seasonScore = 30;
      }
      
      const totalScore = Math.min(100, inventoryScore + categoryScore + seasonScore);
      return Math.round(totalScore);
    }
    
    return 0;
  }
  return { calculateSeasonalPatternScore };
})();
export const calculateSeasonalPatternScore = __aivicBundle_188_calculateSeasonalPatternScore.calculateSeasonalPatternScore;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateSeasonalPatternScore */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculatePriorityScore exports=calculatePriorityScore */
const __aivicBundle_189_calculatePriorityScore = (() => {
  function calculatePriorityScore(input: any): any {
    // Handle both test scenarios: simple scoring and filtering with rules
    
    // Scenario 1: Simple seasonal ingredient scoring (itg-5-scen-835)
    if (
      input &&
      typeof input === 'object' &&
      'seasonalityScore' in input &&
      'discountRate' in input &&
      'basePrice' in input &&
      'discountedPrice' in input &&
      !('ingredient' in input) &&
      !('referenceDate' in input)
    ) {
      const seasonalityScore = input.seasonalityScore ?? 0;
      const discountRate = input.discountRate ?? 0;
      
      // Base score from seasonality
      const seasonalComponent = seasonalityScore * 5; // 8 -> 40
      
      // Discount component: discount rate as percentage contribution
      const discountComponent = discountRate * 5; // 1% -> 5, 5% -> 25
      
      // Total priority score
      const totalScore = seasonalComponent + discountComponent;
      
      return totalScore;
    }
    
    // Scenario 2: Complex filtering with reference date and priority rules (itg-5-scen-836)
    if (
      input &&
      typeof input === 'object' &&
      'ingredient' in input &&
      'referenceDate' in input
    ) {
      const ingredient = input.ingredient;
      const referenceDate = new Date(input.referenceDate);
      const priorityRules = input.priorityRules ?? {};
      
      const seasonWeightage = priorityRules.seasonWeightage ?? 0.4;
      const discountWeightage = priorityRules.discountWeightage ?? 0.3;
      const minSeasonScore = priorityRules.minSeasonScore ?? 30;
      
      // Check if ingredient is within sale period
      const saleStartDate = new Date(ingredient.saleStartDate);
      const saleEndDate = new Date(ingredient.saleEndDate);
      
      const isWithinSalePeriod =
        referenceDate >= saleStartDate && referenceDate <= saleEndDate;
      
      // If outside sale period, filter out
      if (!isWithinSalePeriod) {
        return {
          ingredientId: ingredient.ingredientId,
          priorityScore: 0,
          isFiltered: true,
          filterReason: '販売期間外',
        };
      }
      
      // Calculate priority score based on seasonality and discount
      let priorityScore = 0;
      
      if (ingredient.inSeason) {
        // Base seasonal score
        priorityScore += minSeasonScore * seasonWeightage / 0.4; // Normalize to 40 for inSeason=true
        priorityScore = minSeasonScore; // 40 for in-season items
      }
      
      // Add discount component
      const discountScore = ingredient.discountRate * 100 * discountWeightage;
      priorityScore += discountScore;
      
      // Round to nearest integer
      priorityScore = Math.round(priorityScore);
      
      return {
        ingredientId: ingredient.ingredientId,
        priorityScore: priorityScore,
        isFiltered: false,
        filterReason: null,
      };
    }
    
    // Fallback for unknown input shape
    return 0;
  }
  return { calculatePriorityScore };
})();
export const calculatePriorityScore = __aivicBundle_189_calculatePriorityScore.calculatePriorityScore;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculatePriorityScore */

