/* AIVIC_FUNCTION_BUNDLE_START owner=validateRuleNutritionAlignment exports=validateRuleNutritionAlignment */
const __aivicBundle_196_validateRuleNutritionAlignment = (() => {
  function validateRuleNutritionAlignment(
    currentNutritionStandards: {
      proteinMinGrams?: number;
      proteinMaxGrams?: number;
      fiberMinGrams?: number;
      fiberMaxGrams?: number;
      sodiumMaxMg?: number;
      [key: string]: any;
    },
    newRule: {
      ruleId: string;
      ruleType?: string;
      seasonalPattern?: string;
      includedIngredients?: string[];
      averageSodiumPerServingMg?: number;
      priority?: number;
      appliedFromDate?: string;
      [key: string]: any;
    }
  ): {
    isValid: boolean;
    validationStatus: string;
    conflictDetails: string;
    errorMessage: string;
    notificationGenerated: boolean;
    notificationRecipient: string;
    workflowProgress: string;
    requiresRuleModification: boolean;
    conflictConflictingNutrientName: string;
    conflictCurrentLimitMg: number;
    conflictProposedValueMg: number;
    conflictExceedancePercentage: number;
  } {
    const conflicts: Array<{
      nutrient: string;
      currentLimit: number;
      proposedValue: number;
      exceedancePercentage: number;
    }> = [];
  
    // Check sodium conflict
    if (
      currentNutritionStandards.sodiumMaxMg !== undefined &&
      newRule.averageSodiumPerServingMg !== undefined
    ) {
      const currentLimit = currentNutritionStandards.sodiumMaxMg;
      const proposedValue = newRule.averageSodiumPerServingMg;
  
      if (proposedValue > currentLimit) {
        const exceedancePercentage =
          ((proposedValue - currentLimit) / currentLimit) * 100;
        conflicts.push({
          nutrient: 'sodium',
          currentLimit,
          proposedValue,
          exceedancePercentage,
        });
      }
    }
  
    const isValid = conflicts.length === 0;
    const validationStatus = isValid ? 'passed' : 'failed';
  
    let conflictDetails = '';
    let errorMessage = '';
    let conflictConflictingNutrientName = '';
    let conflictCurrentLimitMg = 0;
    let conflictProposedValueMg = 0;
    let conflictExceedancePercentage = 0;
  
    if (conflicts.length > 0) {
      const primaryConflict = conflicts[0];
      conflictConflictingNutrientName = primaryConflict.nutrient;
      conflictCurrentLimitMg = primaryConflict.currentLimit;
      conflictProposedValueMg = primaryConflict.proposedValue;
      conflictExceedancePercentage = primaryConflict.exceedancePercentage;
  
      conflictDetails = `${primaryConflict.nutrient}が栄養基準と抵触しています。現在の上限: ${primaryConflict.currentLimit}mg、提案値: ${primaryConflict.proposedValue}mg`;
      errorMessage = `ルール「${newRule.ruleId}」が栄養基準と抵触しています。${primaryConflict.nutrient}の値が基準を超えています。`;
    }
  
    return {
      isValid,
      validationStatus,
      conflictDetails,
      errorMessage,
      notificationGenerated: !isValid,
      notificationRecipient: !isValid ? 'development_team' : '',
      workflowProgress: !isValid ? 'blocked_at_validation' : 'passed',
      requiresRuleModification: !isValid,
      conflictConflictingNutrientName,
      conflictCurrentLimitMg,
      conflictProposedValueMg,
      conflictExceedancePercentage,
    };
  }
  return { validateRuleNutritionAlignment };
})();
