/* AIVIC_FUNCTION_BUNDLE_START owner=validateMenuRuleConsistency exports=validateMenuRuleConsistency */
const __aivicBundle_198_validateMenuRuleConsistency = (() => {
  interface ValidateMenuRuleConsistencyInput {
    pastMenuProposals: Array<{
      menuId: string;
      proposalDate: string;
      ingredients: Array<{
        ingredientId: string;
        name: string;
        category: string;
        quantity: number;
      }>;
      cookingTimeMinutes: number;
      nutritionalScore: number;
      seasonalFactor: string;
      discountApplied: boolean;
    }>;
    newRule: {
      ruleId: string;
      seasonalPattern?: {
        requiredSeasonalIngredients?: string[];
        discountThreshold?: number;
        prohibitedSeasonalCombination?: string[];
      };
      cookingTimeConstraint?: {
        maxMinutes?: number;
        minMinutes?: number;
      };
      nutritionConstraint?: {
        minScore?: number;
        maxScore?: number;
      };
    };
    validationScope: string;
  }
  
  interface DetailedInconsistency {
    menuId: string;
    violationType: string;
    expectedValue: number;
    actualValue: number;
    ruleSectionAffected: string;
    severity: "critical" | "high" | "medium" | "low";
  }
  
  interface InconsistencySummary {
    totalInconsistencies: number;
    categoryBreakdown: {
      cookingTimeViolation: number;
      nutritionalViolation: number;
      seasonalConflict: number;
    };
    affectedMenuIds: string[];
  }
  
  interface DevelopmentTeamNotification {
    notificationId: string;
    recipientTeam: string;
    notificationType: string;
    attachmentFormat: string;
    sentAt: string;
    status: string;
  }
  
  interface ValidateMenuRuleConsistencyResult {
    validationId: string;
    ruleId: string;
    totalMenusValidated: number;
    inconsistencyDetected: boolean;
    inconsistencySummary: InconsistencySummary;
    detailedInconsistencyList: DetailedInconsistency[];
    developmentTeamNotification: DevelopmentTeamNotification;
  }
  
   function validateMenuRuleConsistency(
    input: ValidateMenuRuleConsistencyInput
  ): ValidateMenuRuleConsistencyResult {
    if (
      input.validationScope === undefined ||
      input.validationScope === null ||
      String(input.validationScope).trim() === ""
    ) {
      throw new Error("validationScope is required");
    }
  
    const validationId = randomUUID();
    const sentAt = new Date().toISOString();
  
    const pastMenuProposals = input.pastMenuProposals || [];
    const newRule = input.newRule || ({} as NonNullable<typeof input.newRule>);
    const ruleId = newRule.ruleId || "";
    const validationScope = input.validationScope;
  
    const cookingTimeConstraint = newRule.cookingTimeConstraint || ({} as NonNullable<typeof newRule.cookingTimeConstraint>);
    const nutritionConstraint = newRule.nutritionConstraint || ({} as NonNullable<typeof newRule.nutritionConstraint>);
    const seasonalPattern = newRule.seasonalPattern || ({} as NonNullable<typeof newRule.seasonalPattern>);
  
    const maxCookingTime = cookingTimeConstraint.maxMinutes;
    const minCookingTime = cookingTimeConstraint.minMinutes;
    const minNutritionScore = nutritionConstraint.minScore;
    const maxNutritionScore = nutritionConstraint.maxScore;
    const prohibitedSeasonalCombination =
      seasonalPattern.prohibitedSeasonalCombination || [];
  
    const detailedInconsistencyList: DetailedInconsistency[] = [];
    const affectedMenuIds: Set<string> = new Set();
  
    let cookingTimeViolationCount = 0;
    let nutritionalViolationCount = 0;
    let seasonalConflictCount = 0;
  
    const isFullDetection = validationScope === "full_inconsistency_detection";
  
    for (const menu of pastMenuProposals) {
      let hasInconsistency = false;
  
      if (isFullDetection) {
        if (
          maxCookingTime !== undefined &&
          menu.cookingTimeMinutes > maxCookingTime
        ) {
          detailedInconsistencyList.push({
            menuId: menu.menuId,
            violationType: "cookingTimeViolation",
            expectedValue: maxCookingTime,
            actualValue: menu.cookingTimeMinutes,
            ruleSectionAffected: "cookingTimeConstraint",
            severity: "high",
          });
          cookingTimeViolationCount++;
          hasInconsistency = true;
        }
  
        if (
          minCookingTime !== undefined &&
          menu.cookingTimeMinutes < minCookingTime
        ) {
          detailedInconsistencyList.push({
            menuId: menu.menuId,
            violationType: "cookingTimeViolation",
            expectedValue: minCookingTime,
            actualValue: menu.cookingTimeMinutes,
            ruleSectionAffected: "cookingTimeConstraint",
            severity: "medium",
          });
          cookingTimeViolationCount++;
          hasInconsistency = true;
        }
  
        if (
          minNutritionScore !== undefined &&
          menu.nutritionalScore < minNutritionScore
        ) {
          detailedInconsistencyList.push({
            menuId: menu.menuId,
            violationType: "nutritionalViolation",
            expectedValue: minNutritionScore,
            actualValue: menu.nutritionalScore,
            ruleSectionAffected: "nutritionConstraint",
            severity: "high",
          });
          nutritionalViolationCount++;
          hasInconsistency = true;
        }
  
        if (
          maxNutritionScore !== undefined &&
          menu.nutritionalScore > maxNutritionScore
        ) {
          detailedInconsistencyList.push({
            menuId: menu.menuId,
            violationType: "nutritionalViolation",
            expectedValue: maxNutritionScore,
            actualValue: menu.nutritionalScore,
            ruleSectionAffected: "nutritionConstraint",
            severity: "medium",
          });
          nutritionalViolationCount++;
          hasInconsistency = true;
        }
  
        if (
          prohibitedSeasonalCombination.length > 0 &&
          prohibitedSeasonalCombination.includes(menu.seasonalFactor)
        ) {
          detailedInconsistencyList.push({
            menuId: menu.menuId,
            violationType: "seasonalConflict",
            expectedValue: 0,
            actualValue: 1,
            ruleSectionAffected: "seasonalPattern",
            severity: "critical",
          });
          seasonalConflictCount++;
          hasInconsistency = true;
        }
      }
  
      if (hasInconsistency) {
        affectedMenuIds.add(menu.menuId);
      }
    }
  
    const totalInconsistencies =
      cookingTimeViolationCount + nutritionalViolationCount + seasonalConflictCount;
    const inconsistencyDetected = totalInconsistencies > 0;
  
    const inconsistencySummary: InconsistencySummary = {
      totalInconsistencies,
      categoryBreakdown: {
        cookingTimeViolation: cookingTimeViolationCount,
        nutritionalViolation: nutritionalViolationCount,
        seasonalConflict: seasonalConflictCount,
      },
      affectedMenuIds: Array.from(affectedMenuIds),
    };
  
    const developmentTeamNotification: DevelopmentTeamNotification = {
      notificationId: randomUUID(),
      recipientTeam: "development_team",
      notificationType: "rule_consistency_violation",
      attachmentFormat: "csv",
      sentAt,
      status: "sent",
    };
  
    return {
      validationId,
      ruleId,
      totalMenusValidated: pastMenuProposals.length,
      inconsistencyDetected,
      inconsistencySummary,
      detailedInconsistencyList,
      developmentTeamNotification,
    };
  }
  return { validateMenuRuleConsistency };
})();
