/* AIVIC_FUNCTION_BUNDLE_START owner=confirmAlgorithmReviewMeetingAttendees exports=confirmAlgorithmReviewMeetingAttendees */
const __aivicBundle_199_confirmAlgorithmReviewMeetingAttendees = (() => {
  function confirmAlgorithmReviewMeetingAttendees(input: {
    scheduled_date_time: Date;
    current_date_time: Date;
    meeting_participants: Array<{
      participant_id: string;
      participant_name: string;
      role: string;
      expected_attendance: boolean;
    }>;
    substitute_mapping: Record<
      string,
      {
        substitute_id: string;
        substitute_name: string;
        substitute_role: string;
      }
    >;
  }): {
    meeting_confirmed: boolean;
    scheduled_datetime_reached: boolean;
    total_participants: number;
    expected_attendance_count: number;
    absent_count: number;
    confirmed_attendees: Array<{
      participant_id: string;
      participant_name: string;
      role: string;
      confirmed_status: string;
    }>;
    absent_with_substitutes: Array<{
      absent_participant_id: string;
      absent_participant_name: string;
      absent_role: string;
      substitute_id: string;
      substitute_name: string;
      substitute_role: string;
      substitute_assigned: boolean;
    }>;
    final_meeting_participants: Array<{
      participant_id: string;
      participant_name: string;
      role: string;
      attendance_type: string;
      represents_participant_id?: string;
    }>;
    notification_required: boolean;
    notification_message: string;
  } {
    const {
      scheduled_date_time,
      current_date_time,
      meeting_participants,
      substitute_mapping,
    } = input;
  
    // Check if scheduled datetime has been reached
    const scheduled_datetime_reached =
      current_date_time >= scheduled_date_time;
  
    // Separate confirmed attendees and absent participants
    const confirmed_attendees = meeting_participants
      .filter((p) => p.expected_attendance)
      .map((p) => ({
        participant_id: p.participant_id,
        participant_name: p.participant_name,
        role: p.role,
        confirmed_status: 'confirmed',
      }));
  
    const absent_participants = meeting_participants.filter(
      (p) => !p.expected_attendance
    );
  
    // Build absent_with_substitutes list
    const absent_with_substitutes = absent_participants
      .filter((p) => substitute_mapping[p.participant_id])
      .map((p) => {
        const substitute = substitute_mapping[p.participant_id];
        return {
          absent_participant_id: p.participant_id,
          absent_participant_name: p.participant_name,
          absent_role: p.role,
          substitute_id: substitute.substitute_id,
          substitute_name: substitute.substitute_name,
          substitute_role: substitute.substitute_role,
          substitute_assigned: true,
        };
      });
  
    // Build final meeting participants list
    const final_meeting_participants: Array<{
      participant_id: string;
      participant_name: string;
      role: string;
      attendance_type: string;
      represents_participant_id?: string;
    }> = [];
  
    // Add confirmed attendees
    confirmed_attendees.forEach((attendee) => {
      final_meeting_participants.push({
        participant_id: attendee.participant_id,
        participant_name: attendee.participant_name,
        role: attendee.role,
        attendance_type: 'direct',
      });
    });
  
    // Add substitutes for absent participants
    absent_with_substitutes.forEach((absence) => {
      final_meeting_participants.push({
        participant_id: absence.substitute_id,
        participant_name: absence.substitute_name,
        role: absence.substitute_role,
        attendance_type: 'substitute',
        represents_participant_id: absence.absent_participant_id,
      });
    });
  
    // Determine notification message
    let notification_message = '';
    if (absent_with_substitutes.length > 0) {
      const firstSubstitute = absent_with_substitutes[0];
      notification_message = `会議参加者リスト確定: ${firstSubstitute.substitute_id}(${firstSubstitute.substitute_name})が ${firstSubstitute.absent_participant_id}の代理参加者として割り当てられました。`;
    }
  
    return {
      meeting_confirmed: scheduled_datetime_reached,
      scheduled_datetime_reached,
      total_participants: meeting_participants.length,
      expected_attendance_count: confirmed_attendees.length,
      absent_count: absent_participants.length,
      confirmed_attendees,
      absent_with_substitutes,
      final_meeting_participants,
      notification_required: absent_with_substitutes.length > 0,
      notification_message,
    };
  }
  return { confirmAlgorithmReviewMeetingAttendees };
})();
export const confirmAlgorithmReviewMeetingAttendees = __aivicBundle_199_confirmAlgorithmReviewMeetingAttendees.confirmAlgorithmReviewMeetingAttendees;
/* AIVIC_FUNCTION_BUNDLE_END owner=confirmAlgorithmReviewMeetingAttendees */

/* AIVIC_FUNCTION_BUNDLE_START owner=confirmMeetingAttendance exports=confirmMeetingAttendance */
const __aivicBundle_200_confirmMeetingAttendance = (() => {
  function confirmMeetingAttendance(input: {
    meeting_id: string;
    scheduled_start_time: Date;
    confirmation_timeout_seconds: number;
    confirmation_deadline: Date;
    participants: Array<{
      participant_id: string;
      participant_name: string;
      email: string;
      confirmation_status: string;
      confirmation_responded_at: Date | null;
    }>;
    confirmation_notification_sent_at: Date;
    current_time_at_timeout: Date;
  }): {
    error_occurred: boolean;
    error_type?: string;
    error_message?: string;
    timeout_occurred_at?: Date;
    meeting_start_status: string;
    requires_manual_intervention: boolean;
    admin_notification_generated: boolean;
    admin_notification_content?: string;
    participants_confirmation_count: number;
    participants_pending_count: number;
    error_log_recorded: boolean;
    error_log_details?: {
      meeting_id: string;
      error_type: string;
      error_timestamp?: string;
      timeout_seconds?: number;
      participants_pending?: number;
    };
  } {
    if (!input.confirmation_deadline) {
      throw new Error('confirmation_deadline is required');
    }
  
    const elapsedSeconds = Math.floor(
      (input.current_time_at_timeout.getTime() - input.confirmation_notification_sent_at.getTime()) / 1000
    );
  
    const isTimeoutOccurred = elapsedSeconds >= input.confirmation_timeout_seconds;
  
    const confirmedCount = input.participants.filter(
      (p) => p.confirmation_status === 'confirmed'
    ).length;
    const pendingCount = input.participants.filter(
      (p) => p.confirmation_status === 'pending'
    ).length;
  
    const isDeadlineExceeded = input.current_time_at_timeout > input.confirmation_deadline;
  
    if (isTimeoutOccurred && pendingCount > 0) {
      const errorMessage = `会議 ${input.meeting_id} の参加者確認がタイムアウトしました。${pendingCount} 名の参加者からの応答がありません。`;
      const adminNotificationContent = `【重要】会議確認タイムアウト通知: 会議 ${input.meeting_id} (予定開始: ${input.scheduled_start_time.toISOString()}) の参加者確認が ${input.confirmation_timeout_seconds} 秒以内に完了しませんでした。`;
  
      return {
        error_occurred: true,
        error_type: 'confirmation_timeout',
        error_message: errorMessage,
        timeout_occurred_at: input.current_time_at_timeout,
        meeting_start_status: isDeadlineExceeded ? 'delayed' : 'delayed',
        requires_manual_intervention: true,
        admin_notification_generated: true,
        admin_notification_content: adminNotificationContent,
        participants_confirmation_count: confirmedCount,
        participants_pending_count: pendingCount,
        error_log_recorded: true,
        error_log_details: {
          meeting_id: input.meeting_id,
          error_type: 'confirmation_timeout',
          error_timestamp: input.current_time_at_timeout.toISOString(),
          timeout_seconds: input.confirmation_timeout_seconds,
          participants_pending: pendingCount,
        },
      };
    }
  
    return {
      error_occurred: false,
      meeting_start_status: 'on_schedule',
      requires_manual_intervention: false,
      admin_notification_generated: false,
      participants_confirmation_count: confirmedCount,
      participants_pending_count: pendingCount,
      error_log_recorded: false,
    };
  }
  return { confirmMeetingAttendance };
})();
export const confirmMeetingAttendance = __aivicBundle_200_confirmMeetingAttendance.confirmMeetingAttendance;
/* AIVIC_FUNCTION_BUNDLE_END owner=confirmMeetingAttendance */

