/* AIVIC_FUNCTION_BUNDLE_START owner=validateAlgorithmReviewMeetingParticipants exports=validateAlgorithmReviewMeetingParticipants */
const __aivicBundle_202_validateAlgorithmReviewMeetingParticipants = (() => {
  function validateAlgorithmReviewMeetingParticipants(input: {
    meetingId: string;
    scheduledStartTime: Date;
    currentTime: Date;
    participantList: string[];
    meetingStatus: string;
  }): {
    meetingId: string;
    isValidated: boolean;
    meetingStatus: string;
    participantCount: number;
    startedAt: Date | null;
    errorMessage: string | null;
  } {
    const { meetingId, scheduledStartTime, currentTime, participantList, meetingStatus } = input;
  
    // Validate that participant list is not empty
    if (!participantList || participantList.length === 0) {
      throw new Error('会議開始には最低1名の参加者が必要です');
    }
  
    // Check if current time has reached scheduled start time
    if (currentTime < scheduledStartTime) {
      return {
        meetingId,
        isValidated: false,
        meetingStatus,
        participantCount: participantList.length,
        startedAt: null,
        errorMessage: 'Meeting start time has not been reached',
      };
    }
  
    // Meeting can start: participants present and time reached
    return {
      meetingId,
      isValidated: true,
      meetingStatus: 'active',
      participantCount: participantList.length,
      startedAt: new Date(scheduledStartTime),
      errorMessage: null,
    };
  }
  return { validateAlgorithmReviewMeetingParticipants };
})();
export const validateAlgorithmReviewMeetingParticipants = __aivicBundle_202_validateAlgorithmReviewMeetingParticipants.validateAlgorithmReviewMeetingParticipants;
