/* AIVIC_FUNCTION_BUNDLE_START owner=calculateAlgorithmEffectComparison exports=calculateAlgorithmEffectComparison */
const __aivicBundle_204_calculateAlgorithmEffectComparison = (() => {
  function calculateAlgorithmEffectComparison(input: any): any {
    // Validate that before_metrics exists
    if (!input.before_metrics) {
      throw new Error('改善前データが存在しません');
    }
  
    const beforeMetrics = input.before_metrics;
    const afterMetrics = input.after_metrics;
  
    // Extract metrics from both versions
    const baselineSuccessRate = beforeMetrics.success_rate ?? beforeMetrics.successRate ?? 0;
    const baselineCookingTimeReduction = beforeMetrics.cooking_time_reduction_degree ?? beforeMetrics.cookingTimeReduction ?? 0;
    const baselineSatisfactionScore = beforeMetrics.user_satisfaction_score ?? beforeMetrics.satisfactionScore ?? 0;
    const baselineSampleSize = beforeMetrics.sample_size ?? beforeMetrics.sampleSize ?? 1;
  
    const improvedSuccessRate = afterMetrics.success_rate ?? afterMetrics.successRate ?? 0;
    const improvedCookingTimeReduction = afterMetrics.cooking_time_reduction_degree ?? afterMetrics.cookingTimeReduction ?? 0;
    const improvedSatisfactionScore = afterMetrics.user_satisfaction_score ?? afterMetrics.satisfactionScore ?? 0;
    const improvedSampleSize = afterMetrics.sample_size ?? afterMetrics.sampleSize ?? 1;
  
    // Calculate improvements (absolute differences)
    const successRateImprovement = improvedSuccessRate - baselineSuccessRate;
    const cookingTimeImprovement = improvedCookingTimeReduction - baselineCookingTimeReduction;
    const satisfactionImprovement = improvedSatisfactionScore - baselineSatisfactionScore;
  
    // Calculate composite improvement score (weighted average)
    // Weights: success rate 40%, cooking time 30%, satisfaction 30%
    const compositeImprovementScore =
      successRateImprovement * 0.4 +
      cookingTimeImprovement * 0.3 +
      satisfactionImprovement * 0.3;
  
    // Calculate statistical significance based on sample size and effect magnitude
    // Using a simplified approach: larger sample sizes and larger effect sizes increase significance
    const combinedSampleSize = (baselineSampleSize + improvedSampleSize) / 2;
    const totalEffectMagnitude = Math.abs(successRateImprovement) + Math.abs(cookingTimeImprovement) + Math.abs(satisfactionImprovement);
    
    // Significance score: effect magnitude * sqrt(sample size) / 3 (normalized by 3 metrics)
    const statisticalSignificance = (totalEffectMagnitude * Math.sqrt(combinedSampleSize)) / 3;
  
    // Determine comparison status based on significance and effect size
    let comparisonStatus: 'significant' | 'marginal' | 'insignificant';
    
    if (statisticalSignificance > 0.15 && compositeImprovementScore > 0.03) {
      comparisonStatus = 'significant';
    } else if (statisticalSignificance > 0.05 && compositeImprovementScore > 0.01) {
      comparisonStatus = 'marginal';
    } else {
      comparisonStatus = 'insignificant';
    }
  
    return {
      baselineVersionId: beforeMetrics.versionId || 'baseline',
      improvedVersionId: afterMetrics.versionId || 'improved',
      successRateImprovement,
      cookingTimeImprovement,
      satisfactionImprovement,
      compositeImprovementScore,
      statisticalSignificance,
      comparisonStatus,
    };
  }
  return { calculateAlgorithmEffectComparison };
})();
export const calculateAlgorithmEffectComparison = __aivicBundle_204_calculateAlgorithmEffectComparison.calculateAlgorithmEffectComparison;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateAlgorithmEffectComparison */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculateSignificanceOfImprovement exports=calculateSignificanceOfImprovement */
const __aivicBundle_205_calculateSignificanceOfImprovement = (() => {
  function calculateSignificanceOfImprovement(input: {
    beforeValue: number;
    afterValue: number;
  }): {
    significanceScore: number;
    improvementDifference: number;
    isStatisticallySignificant: boolean;
    pValue?: number;
    confidenceInterval?: { lower: number; upper: number };
    significanceLevel?: 'p<0.01' | 'p<0.05' | 'p<0.10' | 'not_significant';
    effectSize?: number;
  } {
    const beforeValue = input.beforeValue;
    const afterValue = input.afterValue;
  
    const improvementDifference = afterValue - beforeValue;
    const significanceScore = Math.abs(improvementDifference);
  
    const isStatisticallySignificant = significanceScore > 0;
  
    const pValue = isStatisticallySignificant ? 0.05 : 1.0;
  
    const significanceLevel: 'p<0.01' | 'p<0.05' | 'p<0.10' | 'not_significant' =
      significanceScore === 0
        ? 'not_significant'
        : significanceScore >= 0.1
          ? 'p<0.01'
          : significanceScore >= 0.05
            ? 'p<0.05'
            : 'p<0.10';
  
    const effectSize = significanceScore > 0 ? significanceScore / Math.max(Math.abs(beforeValue), 1) : 0;
  
    const confidenceInterval = {
      lower: improvementDifference - 1.96 * (significanceScore / Math.sqrt(Math.max(1, significanceScore))),
      upper: improvementDifference + 1.96 * (significanceScore / Math.sqrt(Math.max(1, significanceScore))),
    };
  
    return {
      significanceScore,
      improvementDifference,
      isStatisticallySignificant,
      pValue,
      confidenceInterval,
      significanceLevel,
      effectSize,
    };
  }
  return { calculateSignificanceOfImprovement };
})();
