      const avgSuccessRate =
        weekValues.reduce((sum, w) => sum + w.successRate, 0) / weekValues.length;
      const avgCookingTimeReduction =
        weekValues.reduce((sum, w) => sum + w.cookingTimeReduction, 0) / weekValues.length;
      const avgSatisfactionScore =
        weekValues.reduce((sum, w) => sum + w.satisfactionScore, 0) / weekValues.length;
  
