/* AIVIC_FUNCTION_BUNDLE_START owner=confirmWeeklyReviewAttendance exports=confirmWeeklyReviewAttendance */
const __aivicBundle_207_confirmWeeklyReviewAttendance = (() => {
  function confirmWeeklyReviewAttendance(input: {
    meeting_schedule_id: string;
    scheduled_time: Date;
    is_recurring_weekly_monday: boolean;
    participants: Array<{
      participant_id: string;
      participant_name: string;
      is_planned_to_attend: boolean;
      delegate_participant_id?: string;
      delegate_name?: string;
    }>;
    current_time: Date;
  }): {
    meeting_schedule_id: string;
    scheduled_time?: Date;
    attendance_confirmation_status: 'completed' | 'pending' | 'outside_window';
    confirmed_participant_count: number;
    total_participant_count: number;
    confirmation_percentage: number;
    system_event_recorded: boolean;
    event_log_entry_type?: string;
    confirmation_timestamp?: Date;
    timing_valid?: boolean;
    has_delegates?: boolean;
    event_timestamp?: Date;
    event_details_meeting_id?: string;
    event_details_confirmed_count?: number;
  } {
    if (!input.participants || input.participants.length === 0) {
      throw new Error('参加予定者が指定されていません');
    }
  
    const { meeting_schedule_id, scheduled_time, participants, current_time, is_recurring_weekly_monday } = input;
  
    const totalParticipants = participants.length;
  
    // Count confirmed participants (planned to attend or delegates)
    let confirmedCount = 0;
    let hasDelegates = false;
  
    for (const participant of participants) {
      if (participant.is_planned_to_attend) {
        confirmedCount++;
      } else if (participant.delegate_participant_id && participant.delegate_name) {
        confirmedCount++;
        hasDelegates = true;
      }
    }
  
    const confirmationPercentage = Math.round(
      (confirmedCount / totalParticipants) * 100
    );
  
    // Check if current_time is within the scheduled time window (09:00 exactly for weekly Monday)
    const scheduledHour = scheduled_time.getUTCHours();
    const scheduledMinute = scheduled_time.getUTCMinutes();
    const currentHour = current_time.getUTCHours();
    const currentMinute = current_time.getUTCMinutes();
  
    const isWithinWindow =
      currentHour === scheduledHour && currentMinute === scheduledMinute;
  
    // Validate that is_recurring_weekly_monday is true when within window
    const isValidRecurringWeekly = is_recurring_weekly_monday === true;
  
    let attendanceConfirmationStatus: 'completed' | 'pending' | 'outside_window';
    let systemEventRecorded = false;
    let eventLogEntryType: string | undefined;
  
    if (!isWithinWindow) {
      attendanceConfirmationStatus = 'outside_window';
      systemEventRecorded = false;
    } else if (isValidRecurringWeekly && confirmationPercentage === 100) {
      attendanceConfirmationStatus = 'completed';
      systemEventRecorded = true;
      eventLogEntryType = 'attendance_confirmation_completed';
    } else {
      attendanceConfirmationStatus = 'pending';
      systemEventRecorded = false;
    }
  
    const result: {
      meeting_schedule_id: string;
      scheduled_time?: Date;
      attendance_confirmation_status: 'completed' | 'pending' | 'outside_window';
      confirmed_participant_count: number;
      total_participant_count: number;
      confirmation_percentage: number;
      system_event_recorded: boolean;
      event_log_entry_type?: string;
      confirmation_timestamp?: Date;
      timing_valid?: boolean;
      has_delegates?: boolean;
      event_timestamp?: Date;
      event_details_meeting_id?: string;
      event_details_confirmed_count?: number;
    } = {
      meeting_schedule_id,
      attendance_confirmation_status: attendanceConfirmationStatus,
      confirmed_participant_count: confirmedCount,
      total_participant_count: totalParticipants,
      confirmation_percentage: confirmationPercentage,
      system_event_recorded: systemEventRecorded,
    };
  
    if (eventLogEntryType) {
      result.event_log_entry_type = eventLogEntryType;
    }
  
    if (systemEventRecorded) {
      result.confirmation_timestamp = scheduled_time;
      result.event_timestamp = current_time;
      result.event_details_meeting_id = meeting_schedule_id;
      result.event_details_confirmed_count = confirmedCount;
    }
  
    if (hasDelegates) {
      result.has_delegates = true;
    }
  
    result.timing_valid = isWithinWindow;
  
    return result;
  }
  return { confirmWeeklyReviewAttendance };
})();
