/* AIVIC_FUNCTION_BUNDLE_START owner=detectAndExcludeAnomalies exports=detectAndExcludeAnomalies */
const __aivicBundle_223_detectAndExcludeAnomalies = (() => {
  function detectAndExcludeAnomalies(
    evaluationDataset: any[]
  ): {
    valid_records: any[];
    anomaly_count: number;
    quality_verified: boolean;
  } {
    if (!Array.isArray(evaluationDataset) || evaluationDataset.length === 0) {
      return {
        valid_records: [],
        anomaly_count: 0,
        quality_verified: true,
      };
    }
  
    const validRecords: any[] = [];
    const excludedRecordIds: string[] = [];
    let anomalyCount = 0;
  
    for (const record of evaluationDataset) {
      const hasAnomalies = detectRecordAnomalies(record);
  
      if (hasAnomalies.hasMissingOrNull) {
        if (hasAnomalies.missingFields.length > 0) {
          throw new Error(`欠損値が検出されました: ${hasAnomalies.missingFields.join(', ')}`);
        }
        if (hasAnomalies.nullFields.length > 0) {
          throw new Error(`null値が検出されました: ${hasAnomalies.nullFields.join(', ')}`);
        }
      }
  
      if (hasAnomalies.hasOutlier) {
        anomalyCount++;
        if (record.recordId || record.user_id) {
          excludedRecordIds.push(record.recordId || record.user_id);
        }
      } else {
        validRecords.push(record);
      }
    }
  
    if (validRecords.length === 0 && anomalyCount === 0) {
      throw new Error('分析に必要な有効なデータが不足しています');
    }
  
    return {
      valid_records: validRecords,
      anomaly_count: anomalyCount,
      quality_verified: true,
    };
  }
  
  interface AnomalyCheckResult {
    hasMissingOrNull: boolean;
    hasOutlier: boolean;
    missingFields: string[];
    nullFields: string[];
  }
  
  function detectRecordAnomalies(record: any): AnomalyCheckResult {
    const missingFields: string[] = [];
    const nullFields: string[] = [];
    let hasOutlier = false;
  
    const numericFields = [
      'generation_success_rate',
      'cooking_time_reduction_degree',
      'user_satisfaction_score',
      'successRate',
      'cookingTimeReduction',
      'satisfactionScore',
    ];
  
    const stringFields = ['user_id', 'userId', 'week'];
  
    for (const field of numericFields) {
      if (field in record) {
        const value = record[field];
  
        if (value === undefined) {
          missingFields.push(field);
        } else if (value === null) {
          nullFields.push(field);
        } else if (typeof value === 'number') {
          if (isNaN(value)) {
            missingFields.push(field);
          } else if (
            field === 'generation_success_rate' ||
            field === 'successRate'
          ) {
            if (value < 0 || value > 100) {
              hasOutlier = true;
            }
          } else if (
            field === 'cooking_time_reduction_degree' ||
            field === 'cookingTimeReduction'
          ) {
            if (value < 0) {
              hasOutlier = true;
            }
          } else if (
            field === 'user_satisfaction_score' ||
            field === 'satisfactionScore'
          ) {
            if (value < 0 || value > 5) {
              hasOutlier = true;
            }
          }
        }
      }
    }
  
    for (const field of stringFields) {
      if (field in record) {
        const value = record[field];
        if (value === undefined) {
          missingFields.push(field);
        } else if (value === null) {
          nullFields.push(field);
        }
      }
    }
  
    return {
      hasMissingOrNull: missingFields.length > 0 || nullFields.length > 0,
      hasOutlier,
      missingFields,
      nullFields,
    };
  }
  return { detectAndExcludeAnomalies };
})();
export const detectAndExcludeAnomalies = __aivicBundle_223_detectAndExcludeAnomalies.detectAndExcludeAnomalies;
/* AIVIC_FUNCTION_BUNDLE_END owner=detectAndExcludeAnomalies */

/* AIVIC_FUNCTION_BUNDLE_START owner=detectAndExcludeMissingValues exports=detectAndExcludeMissingValues */
const __aivicBundle_224_detectAndExcludeMissingValues = (() => {
  function detectAndExcludeMissingValues(
    feedbackRecords: any
  ): {
    missingValuePercentage: number;
    isExcluded: boolean;
    correctionApplied: boolean;
    correctionMethod?: string;
    processedRecordCount: number;
    excludeReason?: string;
    log: string;
    processingFlag: string;
  } {
    // Handle both array of feedback records and array of user data
    const records = Array.isArray(feedbackRecords) ? feedbackRecords : [];
    
    if (records.length === 0) {
      return {
        missingValuePercentage: 0,
        isExcluded: false,
        correctionApplied: false,
        processedRecordCount: 0,
        log: '0 percent no exclusion',
        processingFlag: 'processed_without_correction',
      };
    }
  
    // Detect missing values based on record structure
    let missingCount = 0;
    const recordsWithMissing: Array<{ index: number; record: any; hasMissing: boolean }> = [];
  
    records.forEach((record, index) => {
      // Check for feedback record structure (satisfactionScore, completionRate, requestText)
      const isFeedbackRecord = 'feedbackId' in record || 'mealId' in record;
      
      let hasMissing = false;
      if (isFeedbackRecord) {
        hasMissing =
          record.satisfactionScore === undefined ||
          record.satisfactionScore === null ||
          record.completionRate === undefined ||
          record.completionRate === null ||
          record.requestText === undefined ||
          record.requestText === null;
      } else {
        // Check for user data structure (menuGenerationSuccessRate, etc.)
        hasMissing = record.menuGenerationSuccessRate === null || record.menuGenerationSuccessRate === undefined;
      }
  
      if (hasMissing) {
        missingCount++;
      }
      recordsWithMissing.push({ index, record, hasMissing });
    });
  
    const missingValuePercentage = Math.round((missingCount / records.length) * 100);
  
    // Determine processing based on missing value percentage threshold
    const CORRECTION_THRESHOLD = 5; // 5% - apply correction
    const EXCLUSION_THRESHOLD = 10; // 10% - exclude dataset
  
    let isExcluded = false;
    let correctionApplied = false;
    let correctionMethod: string | undefined;
    let processedRecordCount = records.length;
    let excludeReason: string | undefined;
    let processingFlag: string;
    let log: string;
  
    if (missingValuePercentage > EXCLUSION_THRESHOLD) {
      // Exclude entire dataset
      isExcluded = true;
      correctionApplied = false;
      processedRecordCount = 0;
      excludeReason = 'missing_value_percentage_exceeds_threshold';
      processingFlag = 'excluded_due_to_high_missing_rate';
      log = `${missingValuePercentage} percent excluded`;
    } else if (missingValuePercentage >= CORRECTION_THRESHOLD) {
      // Apply correction (mean imputation)
      correctionApplied = true;
      correctionMethod = 'mean_imputation';
      processedRecordCount = records.length - missingCount;
      processingFlag = 'processed_with_correction';
      log = `${missingValuePercentage} percent correction applied`;
    } else {
      // No correction needed
      correctionApplied = false;
      processedRecordCount = records.length;
      processingFlag = 'processed_without_correction';
      log = `${missingValuePercentage} percent no exclusion`;
    }
  
    return {
      missingValuePercentage,
      isExcluded,
      correctionApplied,
      correctionMethod,
      processedRecordCount,
      excludeReason,
      log,
      processingFlag,
    };
  }
  return { detectAndExcludeMissingValues };
})();
export const detectAndExcludeMissingValues = __aivicBundle_224_detectAndExcludeMissingValues.detectAndExcludeMissingValues;
/* AIVIC_FUNCTION_BUNDLE_END owner=detectAndExcludeMissingValues */

/* AIVIC_FUNCTION_BUNDLE_START owner=generateImprovementProposals exports=generateImprovementProposals */
const __aivicBundle_225_generateImprovementProposals = (() => {
  interface GenerateImprovementProposalsInput {
    pattern_id: string;
    failure_category: string;
    occurrence_count: number;
    affected_segments: string[];
    severity_score: number;
  }
  
  interface GenerateImprovementProposalsOutput {
    proposal_id: string;
    proposal_type: 'アルゴリズム修正' | 'パラメータ調整' | '新機能';
    linked_failure_patterns: string[];
    target_constraint_category: string;
    description: string;
    implementation_difficulty: 'easy' | 'medium' | 'hard';
    expected_impact_score: number;
  }
  
   function generateImprovementProposals(
    failurePatterns: GenerateImprovementProposalsInput[]
  ): GenerateImprovementProposalsOutput[] {
    if (!failurePatterns || failurePatterns.length === 0) {
      return [];
    }
  
    const proposals: GenerateImprovementProposalsOutput[] = [];
    
    
  
    const categoryConstraintMap: Record<string, { supported: boolean; quality: number }> = {
      '栄養バランス不適切': { supported: true, quality: 0.65 },
      '家族好み未反映': { supported: true, quality: 0.72 },
      '調理時間超過': { supported: true, quality: 0.78 },
      '食材制限漏れ': { supported: true, quality: 0.85 },
      '予算制約超過': { supported: true, quality: 0.70 }
    };
  
    for (const pattern of failurePatterns) {
      const category = pattern.failure_category;
      const constraintInfo = categoryConstraintMap[category] || { supported: false, quality: 0 };
  
      let proposalType: 'アルゴリズム修正' | 'パラメータ調整' | '新機能';
  
      if (!constraintInfo.supported) {
        proposalType = '新機能';
      } else if (constraintInfo.quality < 0.8) {
        proposalType = pattern.severity_score > 7.0 ? 'アルゴリズム修正' : 'パラメータ調整';
      } else {
        proposalType = 'パラメータ調整';
      }
  
      const difficulty = evaluateDifficulty(proposalType, category);
      const expectedScore = (pattern.occurrence_count * 0.6 + pattern.severity_score * 0.4) * 10;
  
      const description = generateDescription(proposalType, category, pattern);
  
      proposals.push({
        proposal_id: randomUUID(),
        proposal_type: proposalType,
        linked_failure_patterns: [pattern.pattern_id],
        target_constraint_category: category,
        description: description,
        implementation_difficulty: difficulty,
        expected_impact_score: Math.min(100, Math.max(0, expectedScore))
      });
    }
  
    return proposals;
  }
  
  function evaluateDifficulty(
    proposalType: string,
    category: string
  ): 'easy' | 'medium' | 'hard' {
    if (proposalType === 'パラメータ調整') {
      return 'easy';
    }
    if (proposalType === 'アルゴリズム修正') {
      if (category === '栄養バランス不適切' || category === '予算制約超過') {
        return 'medium';
      }
      return 'hard';
    }
    return 'hard';
  }
  
  function generateDescription(
    proposalType: string,
    category: string,
    pattern: GenerateImprovementProposalsInput
  ): string {
    const affectedCount = pattern.affected_segments.length;
    const occurrenceText = `${pattern.occurrence_count}件の発生`;
    const segmentText = `${affectedCount}個のセグメント`;
  
    if (proposalType === 'アルゴリズム修正') {
      return `${category}に対応するアルゴリズムの根本的な修正。${occurrenceText}、${segmentText}に影響。`;
    }
    if (proposalType === 'パラメータ調整') {
      return `${category}に対応するパラメータの調整。${occurrenceText}、${segmentText}に影響。`;
    }
    return `${category}に対応する新機能の追加。${occurrenceText}、${segmentText}に影響。`;
  }
  return { generateImprovementProposals };
})();
export const generateImprovementProposals = __aivicBundle_225_generateImprovementProposals.generateImprovementProposals;
/* AIVIC_FUNCTION_BUNDLE_END owner=generateImprovementProposals */

/* AIVIC_FUNCTION_BUNDLE_START owner=linkFailurePatternsToImprovementProposals exports=linkFailurePatternsToImprovementProposals */
const __aivicBundle_226_linkFailurePatternsToImprovementProposals = (() => {
  interface LinkFailurePatternsInput {
    failurePatterns: Array<{
      id?: string;
      patternId?: string;
      code?: string;
      message?: string;
      occurrenceDate?: Date;
      category?: string;
      frequency?: number;
      userId?: string;
      impactScore?: number;
      affectedUserCount?: number;
      exampleLogs?: string[];
    }>;
    improvementProposals: Array<{
      id?: string;
      proposalId?: string;
      type?: string;
      title?: string;
      description?: string;
      kpiContribution?: number;
      implementationDifficulty?: number;
      userImpact?: number;
      targetFailurePatternIds?: string[];
      priority?: number;
      createdDate?: Date;
      createdBy?: string;
      addressedFailurePatterns?: string[];
      expectedAccuracyImprovement?: number;
      expectedSatisfactionLift?: number;
      estimatedImplementationHours?: number;
      implementationRiskLevel?: string;
      priorityScore?: number;
      recommendedDeploymentPhase?: string;
    }>;
    linkTimestamp: Date;
    linkedBy: string;
  }
  
  interface LinkFailurePatternsOutput {
    success: boolean;
    totalLinksCreated: number;
    failurePatternsProcessed: number;
    improvementProposalsProcessed: number;
    linkedProposals?: Array<{
      proposalId: string;
      linkedPatternIds: string[];
      coveragePercentage: number;
    }>;
    unlinkedPatterns?: string[];
    linkingReport?: string;
    mappingRecords?: Array<{
      failurePatternId: string;
      failureCode?: string;
      failureCategory?: string;
      linkedProposalIds: string[];
      proposalTypes?: string[];
      linkTimestamp: string;
      linkedBy: string;
      linkChangeHistory?: Array<{
        action: string;
        timestamp: string;
        actor: string;
      }>;
    }>;
    traceabilityStatus?: string;
    totalMappings?: number;
  }
  
   function linkFailurePatternsToImprovementProposals(
    input: LinkFailurePatternsInput
  ): LinkFailurePatternsOutput {
    const {
      failurePatterns,
      improvementProposals,
      linkTimestamp,
      linkedBy,
    } = input;
  
    const linkTimestampStr = linkTimestamp.toISOString();
    const mappingRecords: LinkFailurePatternsOutput['mappingRecords'] = [];
    const linkedProposalsMap = new Map<
      string,
      { linkedPatternIds: string[]; proposalTypes: string[] }
    >();
    const linkedPatternIds = new Set<string>();
  
    // Initialize proposal tracking
    improvementProposals.forEach((proposal) => {
      const proposalId = proposal.id || proposal.proposalId || '';
      if (proposalId) {
        linkedProposalsMap.set(proposalId, {
          linkedPatternIds: [],
          proposalTypes: [],
        });
      }
    });
  
    // Link failure patterns to improvement proposals
    failurePatterns.forEach((pattern) => {
      const patternId = pattern.id || pattern.patternId || '';
      const patternCode = pattern.code || '';
      const patternCategory = pattern.category || '';
  
      let linkedProposalIds: string[] = [];
      let proposalTypes: string[] = [];
  
      // Find matching proposals
      improvementProposals.forEach((proposal) => {
        const proposalId = proposal.id || proposal.proposalId || '';
        const targetPatterns =
          proposal.targetFailurePatternIds ||
          proposal.addressedFailurePatterns ||
          [];
  
        if (
          proposalId &&
          (targetPatterns.includes(patternId) ||
            targetPatterns.includes(patternCode))
        ) {
          linkedProposalIds.push(proposalId);
          proposalTypes.push(proposal.type || '');
  
          const tracking = linkedProposalsMap.get(proposalId);
          if (tracking) {
            tracking.linkedPatternIds.push(patternId);
            if (proposal.type && !tracking.proposalTypes.includes(proposal.type)) {
              tracking.proposalTypes.push(proposal.type);
            }
          }
  
          linkedPatternIds.add(patternId);
        }
      });
  
      // Create mapping record
      if (patternId) {
        mappingRecords.push({
          failurePatternId: patternId,
          failureCode: patternCode,
          failureCategory: patternCategory,
          linkedProposalIds,
          proposalTypes,
          linkTimestamp: linkTimestampStr,
          linkedBy,
          linkChangeHistory: [
            {
              action: 'link_created',
              timestamp: linkTimestampStr,
              actor: linkedBy,
            },
          ],
        });
      }
    });
  
    // Build linked proposals array
    const linkedProposalsArray: Array<{
      proposalId: string;
      linkedPatternIds: string[];
      coveragePercentage: number;
    }> = [];
  
    linkedProposalsMap.forEach((tracking, proposalId) => {
      const totalPatterns = failurePatterns.length;
      const coveragePercentage =
        totalPatterns > 0
          ? Math.round((tracking.linkedPatternIds.length / totalPatterns) * 100)
          : 0;
  
      linkedProposalsArray.push({
        proposalId,
        linkedPatternIds: tracking.linkedPatternIds,
        coveragePercentage,
      });
    });
  
    // Identify unlinked patterns
    const unlinkedPatternIds: string[] = [];
    failurePatterns.forEach((pattern) => {
      const patternId = pattern.id || pattern.patternId || '';
      if (patternId && !linkedPatternIds.has(patternId)) {
        unlinkedPatternIds.push(patternId);
      }
    });
  
    const totalLinksCreated = mappingRecords.reduce(
      (sum, record) => sum + record.linkedProposalIds.length,
      0
    );
  
    return {
      success: true,
      totalLinksCreated,
      failurePatternsProcessed: failurePatterns.length,
      improvementProposalsProcessed: improvementProposals.length,
      linkedProposals: linkedProposalsArray,
      unlinkedPatterns: unlinkedPatternIds,
      linkingReport: `Linked ${totalLinksCreated} failure patterns to ${linkedProposalsArray.length} improvement proposals. ${unlinkedPatternIds.length} patterns remain unlinked.`,
      mappingRecords,
      traceabilityStatus: unlinkedPatternIds.length === 0 ? '完全' : '部分',
      totalMappings: mappingRecords.length,
    };
  }
  return { linkFailurePatternsToImprovementProposals };
})();
export const linkFailurePatternsToImprovementProposals = __aivicBundle_226_linkFailurePatternsToImprovementProposals.linkFailurePatternsToImprovementProposals;
/* AIVIC_FUNCTION_BUNDLE_END owner=linkFailurePatternsToImprovementProposals */

