/* AIVIC_FUNCTION_BUNDLE_START owner=classifyImprovementProposal exports=classifyImprovementProposal */
const __aivicBundle_230_classifyImprovementProposal = (() => {
  function classifyImprovementProposal(proposal: {
    proposal_id: string;
    proposal_type: string | null;
    description: string;
    failure_pattern_id: string;
    business_value_score: number;
    technical_difficulty_score: number;
    user_impact_score: number;
  }): {
    proposal_id: string;
    proposal_type: string | null;
    classification_status: string;
    failure_pattern_id: string;
    classified_at: string;
    total_priority_score: number;
  } {
    if (
      !proposal.description ||
      String(proposal.description).trim() === ''
    ) {
      throw new Error('description is required');
    }
  
    const validTypes = ['performance_improvement', 'bug_fix', 'feature_addition'];
  
    if (
      !proposal.proposal_type ||
      proposal.proposal_type.trim() === '' ||
      !validTypes.includes(proposal.proposal_type)
    ) {
      throw new Error(
        '有効なタイプではありません。proposal_type は performance_improvement, bug_fix, または feature_addition である必要があります。'
      );
    }
  
    const businessValueWeight = 0.4;
    const userImpactWeight = 0.4;
    const technicalDifficultyWeight = 0.2;
  
    const totalPriorityScore =
      proposal.business_value_score * businessValueWeight +
      proposal.user_impact_score * userImpactWeight +
      (100 - proposal.technical_difficulty_score) * technicalDifficultyWeight;
  
    const roundedScore = Math.round(totalPriorityScore * 100) / 100;
  
    return {
      proposal_id: proposal.proposal_id,
      proposal_type: proposal.proposal_type,
      classification_status: 'classified',
      failure_pattern_id: proposal.failure_pattern_id,
      classified_at: new Date().toISOString(),
      total_priority_score: roundedScore,
    };
  }
  return { classifyImprovementProposal };
})();
export const classifyImprovementProposal = __aivicBundle_230_classifyImprovementProposal.classifyImprovementProposal;
/* AIVIC_FUNCTION_BUNDLE_END owner=classifyImprovementProposal */

/* AIVIC_FUNCTION_BUNDLE_START owner=aggregateFailurePatternsToPropsal exports=aggregateFailurePatternsToPropsal */
const __aivicBundle_231_aggregateFailurePatternsToPropsal = (() => {
  function aggregateFailurePatternsToPropsal(input: any) {
    const {
      improvement_proposal_id,
      failure_patterns,
      proposal_title,
      proposal_priority,
    } = input;
  
    // failure_patterns を impact_level の降順でソート
    const sortedPatterns = [...failure_patterns].sort(
      (a, b) => b.impact_level - a.impact_level
    );
  
    // 集約統計の計算
    const total_occurrences = failure_patterns.reduce(
      (sum: number, fp: any) => sum + fp.occurrence_count,
      0
    );
  
    const average_impact_level =
      failure_patterns.reduce((sum: number, fp: any) => sum + fp.impact_level, 0) /
      failure_patterns.length;
  
    // 最新の発生日時を取得
    const dates = failure_patterns.map((fp: any) => new Date(fp.occurrence_date));
    const latest_date = new Date(
      Math.max(...dates.map((d: Date) => d.getTime()))
    ).toISOString();
  
    return {
      improvement_proposal_id,
      aggregated_failure_patterns: sortedPatterns,
      total_occurrences,
      average_impact_level,
      proposal_priority,
      proposal_title,
      aggregation_timestamp: new Date().toISOString(),
      latest_occurrence_date: latest_date.split("T")[0],
    };
  }
  return { aggregateFailurePatternsToPropsal };
})();
export const aggregateFailurePatternsToPropsal = __aivicBundle_231_aggregateFailurePatternsToPropsal.aggregateFailurePatternsToPropsal;
/* AIVIC_FUNCTION_BUNDLE_END owner=aggregateFailurePatternsToPropsal */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculatePriorityScoreAndRank exports=calculatePriorityScoreAndRank */
const __aivicBundle_232_calculatePriorityScoreAndRank = (() => {
  function calculatePriorityScoreAndRank(proposals: any[]): any[] {
    if (!proposals || proposals.length === 0) {
      return [];
    }
  
    const scoredProposals = proposals.map((proposal) => {
      const kpiContribution = proposal.kpi_contribution ?? 0;
      const implementationDifficulty = proposal.implementation_difficulty ?? 0;
      const userImpact = proposal.user_impact ?? 0;
  
      const totalScore =
        kpiContribution * 0.4 +
        userImpact * 0.4 +
        (100 - implementationDifficulty) * 0.2;
  
      return {
        id: proposal.id,
        name: proposal.name,
        kpi_contribution: kpiContribution,
        implementation_difficulty: implementationDifficulty,
        user_impact: userImpact,
        total_score: totalScore,
      };
    });
  
    const sortedProposals = scoredProposals.sort(
      (a, b) => b.total_score - a.total_score
    );
  
    const rankedProposals = sortedProposals.map((proposal, index) => {
      let priorityRank: string;
      if (index === 0) {
        priorityRank = 'High';
      } else if (index === sortedProposals.length - 1) {
        priorityRank = 'Low';
      } else {
        priorityRank = 'Medium';
      }
  
      return {
        id: proposal.id,
        name: proposal.name,
        kpi_contribution: proposal.kpi_contribution,
        implementation_difficulty: proposal.implementation_difficulty,
        user_impact: proposal.user_impact,
        total_score: proposal.total_score,
        priority_rank: priorityRank,
      };
    });
  
    return rankedProposals;
  }
  return { calculatePriorityScoreAndRank };
})();
export const calculatePriorityScoreAndRank = __aivicBundle_232_calculatePriorityScoreAndRank.calculatePriorityScoreAndRank;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculatePriorityScoreAndRank */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculateImprovementProposalPriority exports=calculateImprovementProposalPriority */
const __aivicBundle_233_calculateImprovementProposalPriority = (() => {
  function calculateImprovementProposalPriority(
    proposals: Array<{
      proposal_id: string;
      business_value_score: number | null;
      technical_difficulty_score: number;
      user_impact_score: number;
    }>
  ): Array<{
    proposal_id: string;
    total_priority_score: number;
    priority_rank: "高" | "中" | "低";
  }> {
    if (!Array.isArray(proposals) || proposals.length === 0) {
      throw new Error("提案リストが空です");
    }
  
    for (const proposal of proposals) {
      if (
        proposal.business_value_score === null ||
        proposal.business_value_score === 0 ||
        proposal.business_value_score === undefined
      ) {
        throw new Error("評価値が無効です。全ての提案に有効な評価値が必要です。");
      }
    }
  
    const scoredProposals = proposals.map((proposal) => {
      const businessValueWeight = 0.4;
      const userImpactWeight = 0.35;
      const technicalDifficultyWeight = 0.25;
  
      const normalizedTechnicalDifficulty =
        100 - proposal.technical_difficulty_score;
  
      const totalPriorityScore =
        proposal.business_value_score * businessValueWeight +
        proposal.user_impact_score * userImpactWeight +
        normalizedTechnicalDifficulty * technicalDifficultyWeight;
  
      const clampedScore = Math.max(0, Math.min(100, totalPriorityScore));
  
      let priorityRank: "高" | "中" | "低";
      if (clampedScore >= 70) {
        priorityRank = "高";
      } else if (clampedScore >= 40) {
        priorityRank = "中";
      } else {
        priorityRank = "低";
      }
  
      return {
        proposal_id: proposal.proposal_id,
        total_priority_score: clampedScore,
        priority_rank: priorityRank,
      };
    });
  
    scoredProposals.sort(
      (a, b) => b.total_priority_score - a.total_priority_score
    );
  
    return scoredProposals;
  }
  return { calculateImprovementProposalPriority };
})();
export const calculateImprovementProposalPriority = __aivicBundle_233_calculateImprovementProposalPriority.calculateImprovementProposalPriority;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateImprovementProposalPriority */

/* AIVIC_FUNCTION_BUNDLE_START owner=rankImprovementProposalsByScore exports=rankImprovementProposalsByScore */
const __aivicBundle_234_rankImprovementProposalsByScore = (() => {
  function rankImprovementProposalsByScore(
    proposals: Array<{
      proposalId: string;
      title: string;
      businessValue: number;
      technicalDifficulty: number;
      userImpactScore: number;
      expectedAccuracyImprovement?: number;
      expectedSatisfactionLift?: number;
      estimatedImplementationHours?: number;
      implementationRiskLevel?: 'low' | 'medium' | 'high';
      addressedFailurePatterns?: string[];
      recommendedDeploymentPhase?: 'immediate' | 'next_sprint' | 'backlog';
    }>
  ): Array<{
    proposalId: string;
    title: string;
    businessValue: number;
    technicalDifficulty: number;
    userImpactScore: number;
    totalScore: number;
    priorityRank: number;
    expectedAccuracyImprovement?: number;
    expectedSatisfactionLift?: number;
    estimatedImplementationHours?: number;
    implementationRiskLevel?: 'low' | 'medium' | 'high';
    addressedFailurePatterns?: string[];
    recommendedDeploymentPhase?: 'immediate' | 'next_sprint' | 'backlog';
  }> {
    const proposalsWithScores = proposals.map((proposal) => {
      const totalScore =
        proposal.businessValue * 10 +
        (10 - proposal.technicalDifficulty) * 5 +
        proposal.userImpactScore * 5;
  
      return {
        ...proposal,
        totalScore,
      };
    });
  
    proposalsWithScores.sort((a, b) => {
      if (b.totalScore !== a.totalScore) {
        return b.totalScore - a.totalScore;
      }
  
      const aExpectedImprovement = a.expectedAccuracyImprovement ?? 0;
      const bExpectedImprovement = b.expectedAccuracyImprovement ?? 0;
      return bExpectedImprovement - aExpectedImprovement;
    });
  
    const rankedProposals = proposalsWithScores.map((proposal, index) => {
      let priorityRank = 1;
      if (index > 0) {
        const prevProposal = proposalsWithScores[index - 1];
        if (proposal.totalScore === prevProposal.totalScore) {
          const prevRanked = rankedProposals[index - 1];
          priorityRank = prevRanked.priorityRank;
        } else {
          priorityRank = index + 1;
        }
      }
  
      return {
        ...proposal,
        priorityRank,
      };
    });
  
    return rankedProposals;
  }
  return { rankImprovementProposalsByScore };
})();
export const rankImprovementProposalsByScore = __aivicBundle_234_rankImprovementProposalsByScore.rankImprovementProposalsByScore;
/* AIVIC_FUNCTION_BUNDLE_END owner=rankImprovementProposalsByScore */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculateWeightedPriorityScore exports=calculateWeightedPriorityScore */
const __aivicBundle_235_calculateWeightedPriorityScore = (() => {
  function calculateWeightedPriorityScore(
    effectivenessScore: number,
    feasibilityScore: number,
    costScore: number,
    effectivenessWeight: number,
    feasibilityWeight: number,
    costWeight: number
  ): number {
    const weightedScore =
      effectivenessScore * effectivenessWeight +
      feasibilityScore * feasibilityWeight +
      costScore * costWeight;
  
    return Math.round(weightedScore * 10) / 10;
  }
  return { calculateWeightedPriorityScore };
})();
