/* AIVIC_FUNCTION_BUNDLE_START owner=defineSegmentClassificationCriteria exports=defineSegmentClassificationCriteria */
const __aivicBundle_238_defineSegmentClassificationCriteria = (() => {
  function defineSegmentClassificationCriteria(segmentationData: {
    ageRanges: Array<{ minAge: number; maxAge: number; label: string }> | string[];
    familyCompositionTypes: string[];
    dietaryRestrictionHasTypes: boolean[];
  }): {
    isValid: boolean;
    errorMessage?: string;
    segments?: Array<{
      segmentId: string;
      criteria: {
        ageRange?: string;
        familyComposition?: string;
        dietaryRestrictionPresence?: boolean;
      };
    }>;
  } {
    const { ageRanges, familyCompositionTypes, dietaryRestrictionHasTypes } = segmentationData;
  
    // Normalize ageRanges to array of objects with minAge, maxAge, label
    let normalizedAgeRanges: Array<{ minAge: number; maxAge: number; label: string }> = [];
    
    if (Array.isArray(ageRanges) && ageRanges.length > 0) {
      if (typeof ageRanges[0] === 'object' && 'minAge' in ageRanges[0]) {
        normalizedAgeRanges = ageRanges as Array<{ minAge: number; maxAge: number; label: string }>;
      } else if (typeof ageRanges[0] === 'string') {
        normalizedAgeRanges = (ageRanges as string[]).map((label, idx) => ({
          minAge: idx * 10,
          maxAge: (idx + 1) * 10,
          label
        }));
      }
    }
  
    // Check for overlapping age ranges
    const overlapDetected = checkAgeRangeOverlap(normalizedAgeRanges);
    if (overlapDetected) {
      return {
        isValid: false,
        errorMessage: "分類範囲が重複しています。年代範囲の定義を確認してください。"
      };
    }
  
    // Generate all segment combinations
    const segments: Array<{
      segmentId: string;
      criteria: {
        ageRange?: string;
        familyComposition?: string;
        dietaryRestrictionPresence?: boolean;
      };
    }> = [];
  
    for (const ageRange of normalizedAgeRanges) {
      for (const familyComposition of familyCompositionTypes) {
        for (const dietaryRestriction of dietaryRestrictionHasTypes) {
          const restrictionLabel = dietaryRestriction ? "制限あり" : "制限なし";
          const segmentId = `seg_${ageRange.label}_${familyComposition}_${restrictionLabel}`;
  
          segments.push({
            segmentId,
            criteria: {
              ageRange: ageRange.label,
              familyComposition,
              dietaryRestrictionPresence: dietaryRestriction
            }
          });
        }
      }
    }
  
    return {
      isValid: true,
      segments
    };
  }
  
  function checkAgeRangeOverlap(
    ageRanges: Array<{ minAge: number; maxAge: number; label: string }>
  ): boolean {
    if (ageRanges.length < 2) {
      return false;
    }
  
    for (let i = 0; i < ageRanges.length; i++) {
      for (let j = i + 1; j < ageRanges.length; j++) {
        const range1 = ageRanges[i];
        const range2 = ageRanges[j];
  
        // Check if ranges overlap
        if (!(range1.maxAge <= range2.minAge || range2.maxAge <= range1.minAge)) {
          return true;
        }
      }
    }
  
    return false;
  }
  return { defineSegmentClassificationCriteria };
})();
export const defineSegmentClassificationCriteria = __aivicBundle_238_defineSegmentClassificationCriteria.defineSegmentClassificationCriteria;
/* AIVIC_FUNCTION_BUNDLE_END owner=defineSegmentClassificationCriteria */

/* AIVIC_FUNCTION_BUNDLE_START owner=aggregateSegmentSuccessRates exports=aggregateSegmentSuccessRates */
const __aivicBundle_239_aggregateSegmentSuccessRates = (() => {
  function aggregateSegmentSuccessRates(
    mealPlanLogs: Array<{
      segmentId: string;
      attemptId?: string;
      success: boolean;
      timestamp?: Date;
      userId?: string;
      generatedAt?: Date;
      acceptedFlag?: boolean;
      satisfactionScore?: number;
    }>
  ): Array<{
    segmentId: string;
    totalAttempts: number;
    successCount: number;
    successRate: number;
    avgSatisfactionScore?: number;
  }> {
    const segmentMap = new Map<
      string,
      {
        totalAttempts: number;
        successCount: number;
        satisfactionScores: number[];
      }
    >();
  
    for (const log of mealPlanLogs) {
      const { segmentId } = log;
      const isSuccess = log.success ?? log.acceptedFlag ?? false;
      const satisfactionScore = log.satisfactionScore ?? 0;
  
      if (!segmentMap.has(segmentId)) {
        segmentMap.set(segmentId, {
          totalAttempts: 0,
          successCount: 0,
          satisfactionScores: [],
        });
      }
  
      const segment = segmentMap.get(segmentId)!;
      segment.totalAttempts += 1;
      if (isSuccess) {
        segment.successCount += 1;
      }
      if (satisfactionScore > 0) {
        segment.satisfactionScores.push(satisfactionScore);
      }
    }
  
    const result: Array<{
      segmentId: string;
      totalAttempts: number;
      successCount: number;
      successRate: number;
      avgSatisfactionScore?: number;
    }> = [];
  
    for (const [segmentId, data] of segmentMap.entries()) {
      const successRate =
        data.totalAttempts > 0
          ? Math.round((data.successCount / data.totalAttempts) * 10000) / 100
          : 0;
  
      const avgSatisfactionScore =
        data.satisfactionScores.length > 0
          ? Math.round(
              (data.satisfactionScores.reduce((a, b) => a + b, 0) /
                data.satisfactionScores.length) *
                100
            ) / 100
          : undefined;
  
      result.push({
        segmentId,
        totalAttempts: data.totalAttempts,
        successCount: data.successCount,
        successRate,
        ...(avgSatisfactionScore !== undefined && { avgSatisfactionScore }),
      });
    }
  
    return result;
  }
  return { aggregateSegmentSuccessRates };
})();
export const aggregateSegmentSuccessRates = __aivicBundle_239_aggregateSegmentSuccessRates.aggregateSegmentSuccessRates;
/* AIVIC_FUNCTION_BUNDLE_END owner=aggregateSegmentSuccessRates */

