/* AIVIC_FUNCTION_BUNDLE_START owner=calculateCookingTimeReductionMetrics exports=calculateCookingTimeReductionMetrics */
const __aivicBundle_242_calculateCookingTimeReductionMetrics = (() => {
  function calculateCookingTimeReductionMetrics(input: {
    segmentId: string;
    segmentName: string;
    targetCookingTimeMinutes: number;
    actualCookingTimeMinutes: number;
  }): {
    timeDifferenceMinutes: number;
    achievementPercentage: number;
  } {
    if (!String(input.segmentId).trim()) {
      throw new Error("segmentId is required");
    }
    if (!String(input.segmentName).trim()) {
      throw new Error("segmentName is required");
    }
  
    const timeDifferenceMinutes =
      input.targetCookingTimeMinutes - input.actualCookingTimeMinutes;
  
    const achievementPercentage = Math.min(
      100,
      Math.max(0, (timeDifferenceMinutes / input.targetCookingTimeMinutes) * 100)
    );
  
    return {
      timeDifferenceMinutes,
      achievementPercentage,
    };
  }
  return { calculateCookingTimeReductionMetrics };
})();
