const __aivicBundle_244_calculateCookingTimeReductionRate = (() => {
  function calculateCookingTimeReductionRate(input: {
    targetCookingTimeMinutes: number;
    actualCookingTimeMinutes: number;
  }): number {
    const { targetCookingTimeMinutes, actualCookingTimeMinutes } = input;
  
    if (targetCookingTimeMinutes === 0) {
      throw new Error('目標調理時間がゼロです');
    }
  
    if (targetCookingTimeMinutes < 0) {
      throw new Error('無効な目標調理時間');
    }
  
    if (actualCookingTimeMinutes < 0) {
      throw new Error('無効な実績調理時間');
    }
  
    const reductionRate =
      ((targetCookingTimeMinutes - actualCookingTimeMinutes) /
        targetCookingTimeMinutes) *
      100;
  
    return reductionRate;
  }
  return { calculateCookingTimeReductionRate };
})();
