/* AIVIC_FUNCTION_BUNDLE_START owner=calculateSegmentCookingTimeReductionAnalysis exports=calculateSegmentCookingTimeReductionAnalysis */
const __aivicBundle_245_calculateSegmentCookingTimeReductionAnalysis = (() => {
  function calculateSegmentCookingTimeReductionAnalysis(input: any): any {
    if (!input || !input.segments || !Array.isArray(input.segments)) {
      return {
        segments: [],
        analysisTimestamp: new Date().toISOString(),
      };
    }
  
    const analysisResults = input.segments.map((segment: any) => {
      const targetTime = segment.targetCookingTimeMinutes ?? 0;
      const actualTime = segment.actualCookingTimeMinutes ?? 0;
      const reductionMinutes = targetTime - actualTime;
      const reductionPercent =
        targetTime > 0 ? Math.round((reductionMinutes / targetTime) * 100) : 0;
  
      return {
        segmentId: segment.segmentId,
        segmentName: segment.segmentName,
        targetCookingTimeMinutes: targetTime,
        actualCookingTimeMinutes: actualTime,
        reductionRatePercent: reductionPercent,
      };
    });
  
    const sortedSegments = analysisResults.sort(
      (a: any, b: any) => b.reductionRatePercent - a.reductionRatePercent
    );
  
    return {
      segments: sortedSegments,
      analysisTimestamp: new Date().toISOString(),
    };
  }
  return { calculateSegmentCookingTimeReductionAnalysis };
})();
