/* AIVIC_FUNCTION_BUNDLE_START owner=identifyMaxDifferentiationSegment exports=identifyMaxDifferentiationSegment */
const __aivicBundle_246_identifyMaxDifferentiationSegment = (() => {
  function identifyMaxDifferentiationSegment(
    segments: Array<{
      segmentId: string;
      segmentName?: string;
      occurrenceFrequency: number;
      improvementEffect: number;
    }>
  ): {
    scores: Array<{
      segmentId: string;
      segmentName?: string;
      priorityScore: number;
    }>;
    maxSegment: {
      segmentId: string;
      segmentName?: string;
      priorityScore: number;
    };
  } {
    if (!segments || segments.length === 0) {
      throw new Error('セグメント分析データが不足しています。先に分析を完了してください');
    }
  
    for (const segment of segments) {
      if (segment.occurrenceFrequency < 0) {
        throw new Error('発生頻度は0以上の値で指定してください');
      }
      if (segment.improvementEffect < 0) {
        throw new Error('改善効果は0以上の値で指定してください');
      }
    }
  
    const maxOccurrenceFrequency = Math.max(
      ...segments.map(s => s.occurrenceFrequency)
    );
    const maxImprovementEffect = Math.max(
      ...segments.map(s => s.improvementEffect)
    );
  
    const scores = segments.map(segment => {
      const frequencyNormalized =
        maxOccurrenceFrequency > 0
          ? (segment.occurrenceFrequency / maxOccurrenceFrequency) * 50
          : 0;
      const effectNormalized =
        maxImprovementEffect > 0
          ? (segment.improvementEffect / maxImprovementEffect) * 50
          : 0;
      const priorityScore = frequencyNormalized + effectNormalized;
  
      return {
        segmentId: segment.segmentId,
        segmentName: segment.segmentName,
        priorityScore,
      };
    });
  
    scores.sort((a, b) => b.priorityScore - a.priorityScore);
  
    const maxSegment = scores[0];
  
    return {
      scores,
      maxSegment,
    };
  }
  return { identifyMaxDifferentiationSegment };
})();
export const identifyMaxDifferentiationSegment = __aivicBundle_246_identifyMaxDifferentiationSegment.identifyMaxDifferentiationSegment;
/* AIVIC_FUNCTION_BUNDLE_END owner=identifyMaxDifferentiationSegment */

/* AIVIC_FUNCTION_BUNDLE_START owner=prioritizeSegmentsByDifferentiationEffect exports=prioritizeSegmentsByDifferentiationEffect */
const __aivicBundle_247_prioritizeSegmentsByDifferentiationEffect = (() => {
  function prioritizeSegmentsByDifferentiationEffect(
    segments: Array<{
      segmentId: string;
      segmentName?: string;
      occurrenceFrequency?: number;
      improvementEffectRate?: number;
      successRate?: number;
      satisfactionScore?: number;
      marketDemand?: number;
      competitorCoverage?: number;
    }>
  ): Array<{
    rank: number;
    priority: number;
    segmentId: string;
    segmentName?: string;
    priorityScore?: number;
    differentiationPotential?: number;
    recommendation?: string;
  }> {
    if (!segments || segments.length === 0) {
      return [];
    }
  
    const scoredSegments = segments.map((segment) => {
      let priorityScore = 0;
      let differentiationPotential = 0;
  
      if (
        segment.occurrenceFrequency !== undefined &&
        segment.improvementEffectRate !== undefined
      ) {
        priorityScore =
          segment.occurrenceFrequency * (segment.improvementEffectRate / 100);
        differentiationPotential = segment.improvementEffectRate / 100;
      } else if (
        segment.successRate !== undefined &&
        segment.marketDemand !== undefined &&
        segment.competitorCoverage !== undefined
      ) {
        differentiationPotential =
          segment.successRate * (1 - segment.competitorCoverage) * (segment.marketDemand / 100);
        priorityScore = differentiationPotential * 100;
      }
  
      return {
        segmentId: segment.segmentId,
        segmentName: segment.segmentName,
        priorityScore,
        differentiationPotential,
        originalIndex: segments.indexOf(segment),
      };
    });
  
    const groupedByScore = new Map<number, typeof scoredSegments>();
    scoredSegments.forEach((item) => {
      const key = item.priorityScore;
      if (!groupedByScore.has(key)) {
        groupedByScore.get(key) || groupedByScore.set(key, []);
      }
      groupedByScore.get(key)!.push(item);
    });
  
    const sortedScores = Array.from(groupedByScore.keys()).sort((a, b) => b - a);
  
    const result: Array<{
      rank: number;
      priority: number;
      segmentId: string;
      segmentName?: string;
      priorityScore?: number;
      differentiationPotential?: number;
      recommendation?: string;
    }> = [];
  
    let currentRank = 1;
    sortedScores.forEach((score) => {
      const itemsWithScore = groupedByScore.get(score)!;
      const priority = currentRank;
  
      itemsWithScore.forEach((item) => {
        let recommendation = 'Secondary priority';
        if (priority === 1) {
          recommendation = 'Prioritize for feature development';
        } else if (priority === 2) {
          recommendation = 'Secondary priority';
        } else {
          recommendation = 'Low priority';
        }
  
        result.push({
          rank: result.length + 1,
          priority,
          segmentId: item.segmentId,
          segmentName: item.segmentName,
          priorityScore: item.priorityScore,
          differentiationPotential: item.differentiationPotential,
          recommendation,
        });
      });
  
      currentRank += itemsWithScore.length;
    });
  
    return result;
  }
  return { prioritizeSegmentsByDifferentiationEffect };
})();
