/* AIVIC_FUNCTION_BUNDLE_START owner=evaluateSegmentStatisticalSignificance exports=evaluateSegmentStatisticalSignificance */
const __aivicBundle_250_evaluateSegmentStatisticalSignificance = (() => {
  function evaluateSegmentStatisticalSignificance(
    segmentAnalysisResults: Array<{
      segmentId: string;
      segmentName: string;
      successRate: number;
      successRatePValue: number;
      cookingTimeReduction: number;
      cookingTimeReductionPValue: number;
      satisfactionScore: number;
      satisfactionScorePValue: number;
      sampleSize: number;
      analysisTimestamp: string;
    }>,
    significanceThreshold: number
  ): {
    totalSegments: number;
    significantResults: number;
    requiresInvestigation: number;
    segmentEvaluations: Array<{
      segmentId: string;
      segmentName: string;
      successRateSignificant: boolean;
      successRatePValue: number;
      cookingTimeReductionSignificant: boolean;
      cookingTimeReductionPValue: number;
      satisfactionScoreSignificant: boolean;
      satisfactionScorePValue: number;
      overallSignificant: boolean;
      flagForInvestigation: boolean;
      investigationReason: string;
      sampleSize: number;
    }>;
    filterableMetadata: {
      analysisTimestamp: string;
      significanceThreshold: number;
      evaluatedAt: string;
      dataQualityIndicator: string;
    };
  } {
    const segmentEvaluations = segmentAnalysisResults.map((segment) => {
      const successRateSignificant = segment.successRatePValue < significanceThreshold;
      const cookingTimeReductionSignificant =
        segment.cookingTimeReductionPValue < significanceThreshold;
      const satisfactionScoreSignificant =
        segment.satisfactionScorePValue < significanceThreshold;
  
      const allSignificant =
        successRateSignificant &&
        cookingTimeReductionSignificant &&
        satisfactionScoreSignificant;
  
      const insignificantMetrics: string[] = [];
      if (!successRateSignificant) {
        insignificantMetrics.push('successRate');
      }
      if (!cookingTimeReductionSignificant) {
        insignificantMetrics.push('cookingTimeReduction');
      }
      if (!satisfactionScoreSignificant) {
        insignificantMetrics.push('satisfactionScore');
      }
  
      const flagForInvestigation = insignificantMetrics.length > 0;
      const investigationReason = insignificantMetrics.join(', ');
  
      return {
        segmentId: segment.segmentId,
        segmentName: segment.segmentName,
        successRateSignificant,
        successRatePValue: segment.successRatePValue,
        cookingTimeReductionSignificant,
        cookingTimeReductionPValue: segment.cookingTimeReductionPValue,
        satisfactionScoreSignificant,
        satisfactionScorePValue: segment.satisfactionScorePValue,
        overallSignificant: allSignificant,
        flagForInvestigation,
        investigationReason,
        sampleSize: segment.sampleSize,
      };
    });
  
    const significantCount = segmentEvaluations.filter(
      (seg) => seg.overallSignificant
    ).length;
  
    const investigationCount = segmentEvaluations.filter(
      (seg) => seg.flagForInvestigation
    ).length;
  
    const analysisTimestamp =
      segmentAnalysisResults.length > 0
        ? segmentAnalysisResults[0].analysisTimestamp
        : new Date().toISOString();
  
    return {
      totalSegments: segmentAnalysisResults.length,
      significantResults: significantCount,
      requiresInvestigation: investigationCount,
      segmentEvaluations,
      filterableMetadata: {
        analysisTimestamp,
        significanceThreshold,
        evaluatedAt: new Date().toISOString(),
        dataQualityIndicator: 'PASSED',
      },
    };
  }
  return { evaluateSegmentStatisticalSignificance };
})();
