/* AIVIC_FUNCTION_BUNDLE_START owner=validateStatisticalSignificance exports=validateStatisticalSignificance */
const __aivicBundle_251_validateStatisticalSignificance = (() => {
  interface ValidateStatisticalSignificanceInput {
    segmentId: string;
    segmentName: string;
    metricsData: Array<{
      recordId: string;
      menuGenerationSuccessRate: number;
      cookingTimeShorteningDegree: number;
      userSatisfactionScore: number;
      timestamp: number;
    }>;
    sampleSize: number;
  }
  
  interface ValidateStatisticalSignificanceResult {
    segmentId: string;
    segmentName: string;
    sampleSize: number;
    isStatisticallySignificant: boolean;
    confidenceLevel: 'low' | 'acceptable' | 'high';
    shouldExcludeFromDisplay: boolean;
    exclusionReason: string | null;
    menuGenerationSuccessRateMean: number;
    cookingTimeShorteningDegreeMean: number;
    userSatisfactionScoreMean: number;
    standardDeviationSuccessRate: number;
    standardDeviationShorteningDegree: number;
    standardDeviationSatisfactionScore: number;
  }
  
   function validateStatisticalSignificance(
    input: ValidateStatisticalSignificanceInput
  ): ValidateStatisticalSignificanceResult {
    const { segmentId, segmentName, metricsData, sampleSize } = input;
  
    // Calculate means for each metric
    const successRates = metricsData.map((m) => m.menuGenerationSuccessRate);
    const shorteningDegrees = metricsData.map((m) => m.cookingTimeShorteningDegree);
    const satisfactionScores = metricsData.map((m) => m.userSatisfactionScore);
  
    const menuGenerationSuccessRateMean =
      successRates.reduce((a, b) => a + b, 0) / successRates.length;
    const cookingTimeShorteningDegreeMean =
      shorteningDegrees.reduce((a, b) => a + b, 0) / shorteningDegrees.length;
    const userSatisfactionScoreMean =
      satisfactionScores.reduce((a, b) => a + b, 0) / satisfactionScores.length;
  
    // Calculate standard deviations
    const calculateStdDev = (values: number[], mean: number): number => {
      if (values.length === 0) return 0;
      const variance =
        values.reduce((sum, val) => sum + Math.pow(val - mean, 2), 0) /
        values.length;
      return Math.sqrt(variance);
    };
  
    const standardDeviationSuccessRate = calculateStdDev(
      successRates,
      menuGenerationSuccessRateMean
    );
    const standardDeviationShorteningDegree = calculateStdDev(
      shorteningDegrees,
      cookingTimeShorteningDegreeMean
    );
    const standardDeviationSatisfactionScore = calculateStdDev(
      satisfactionScores,
      userSatisfactionScoreMean
    );
  
    // Determine statistical significance based on sample size threshold
    const SAMPLE_SIZE_THRESHOLD = 30;
    const isStatisticallySignificant = sampleSize >= SAMPLE_SIZE_THRESHOLD;
  
    // Determine confidence level and exclusion status
    let confidenceLevel: 'low' | 'acceptable' | 'high';
    let shouldExcludeFromDisplay: boolean;
    let exclusionReason: string | null;
  
    if (sampleSize < SAMPLE_SIZE_THRESHOLD) {
      confidenceLevel = 'low';
      shouldExcludeFromDisplay = true;
      exclusionReason = 'サンプルサイズが30未満';
    } else {
      confidenceLevel = 'acceptable';
      shouldExcludeFromDisplay = false;
      exclusionReason = null;
    }
  
    return {
      segmentId,
      segmentName,
      sampleSize,
      isStatisticallySignificant,
      confidenceLevel,
      shouldExcludeFromDisplay,
      exclusionReason,
      menuGenerationSuccessRateMean,
      cookingTimeShorteningDegreeMean,
      userSatisfactionScoreMean,
      standardDeviationSuccessRate,
      standardDeviationShorteningDegree,
      standardDeviationSatisfactionScore,
    };
  }
  return { validateStatisticalSignificance };
})();
export const validateStatisticalSignificance = __aivicBundle_251_validateStatisticalSignificance.validateStatisticalSignificance;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateStatisticalSignificance */

/* AIVIC_FUNCTION_BUNDLE_START owner=validateSegmentBehaviorIndicators exports=validateSegmentBehaviorIndicators */
const __aivicBundle_252_validateSegmentBehaviorIndicators = (() => {
  function validateSegmentBehaviorIndicators(
    input: any
  ): { segmentId: string; isValid: boolean; violatedThresholds: string[]; overallValidationScore: number; recommendation: string }[] | void {
    // Handle single object input (from test)
    if (input && typeof input === 'object' && !Array.isArray(input)) {
      const { successRate, cookingTimeReductionDegree } = input;
      
      // Validate cookingTimeReductionDegree is not negative
      if (cookingTimeReductionDegree !== undefined && cookingTimeReductionDegree < 0) {
        throw new Error(`調理時間短縮度が負の値です: ${cookingTimeReductionDegree}`);
      }
      
      return;
    }
  
    // Handle array of segment behavior data with thresholds
    if (!Array.isArray(input)) {
      return [];
    }
  
    const segmentBehaviorData = input;
    const minimumThresholds = {
      minAttempts: 100,
      minSuccessRate: 0.85,
      maxRejectionRate: 0.15,
      minSatisfactionScore: 4.0,
      minCookingTimeReduction: 0.10
    };
  
    return segmentBehaviorData.map((segment: any) => {
      const violatedThresholds: string[] = [];
      let validationScoreSum = 0;
      let validationScoreCount = 0;
  
      // Check minAttempts
      if (segment.mealGenerationAttempts < minimumThresholds.minAttempts) {
        violatedThresholds.push(`minAttempts (${segment.mealGenerationAttempts} < ${minimumThresholds.minAttempts})`);
        validationScoreSum += (segment.mealGenerationAttempts / minimumThresholds.minAttempts) * 20;
      } else {
        validationScoreSum += 20;
      }
      validationScoreCount++;
  
      // Check minSuccessRate
      const successRate = segment.successfulGenerations / segment.mealGenerationAttempts;
      if (successRate < minimumThresholds.minSuccessRate) {
        violatedThresholds.push(`minSuccessRate (${successRate.toFixed(2)} < ${minimumThresholds.minSuccessRate})`);
        validationScoreSum += (successRate / minimumThresholds.minSuccessRate) * 20;
      } else {
        validationScoreSum += 20;
      }
      validationScoreCount++;
  
      // Check maxRejectionRate
      if (segment.rejectionRate > minimumThresholds.maxRejectionRate) {
        violatedThresholds.push(`maxRejectionRate (${segment.rejectionRate} > ${minimumThresholds.maxRejectionRate})`);
        validationScoreSum += (1 - (segment.rejectionRate / minimumThresholds.maxRejectionRate)) * 20;
      } else {
        validationScoreSum += 20;
      }
      validationScoreCount++;
  
      // Check minSatisfactionScore
      if (segment.averageSatisfactionScore < minimumThresholds.minSatisfactionScore) {
        violatedThresholds.push(`minSatisfactionScore (${segment.averageSatisfactionScore} < ${minimumThresholds.minSatisfactionScore})`);
        validationScoreSum += (segment.averageSatisfactionScore / minimumThresholds.minSatisfactionScore) * 20;
      } else {
        validationScoreSum += 20;
      }
      validationScoreCount++;
  
      // Check minCookingTimeReduction
      if (segment.averageCookingTimeReduction < minimumThresholds.minCookingTimeReduction) {
        violatedThresholds.push(`minCookingTimeReduction (${segment.averageCookingTimeReduction} < ${minimumThresholds.minCookingTimeReduction})`);
        validationScoreSum += (segment.averageCookingTimeReduction / minimumThresholds.minCookingTimeReduction) * 20;
      } else {
        validationScoreSum += 20;
      }
      validationScoreCount++;
  
      const overallValidationScore = validationScoreCount > 0 ? validationScoreSum / validationScoreCount : 0;
      const isValid = violatedThresholds.length === 0;
      const recommendation = isValid
        ? 'Segment meets all behavioral indicators'
        : 'Segment fails multiple thresholds - requires improvement';
  
      return {
        segmentId: segment.segmentId,
        isValid,
        violatedThresholds,
        overallValidationScore: Math.round(overallValidationScore * 10) / 10,
        recommendation
      };
    });
  }
  return { validateSegmentBehaviorIndicators };
})();
export const validateSegmentBehaviorIndicators = __aivicBundle_252_validateSegmentBehaviorIndicators.validateSegmentBehaviorIndicators;
/* AIVIC_FUNCTION_BUNDLE_END owner=validateSegmentBehaviorIndicators */

