const __aivicBundle_254_detectAndExcludeOutliers = (() => {
  function detectAndExcludeOutliers(inputDataset: any): any {
    if (!inputDataset || !Array.isArray(inputDataset)) {
      return {
        detected_outliers: [],
        cleaned_dataset: [],
      };
    }
  
    const detected_outliers: any[] = [];
    const cleaned_dataset: any[] = [];
  
    // 満足度スコアの有効範囲は 0-100
    const MIN_SATISFACTION = 0;
    const MAX_SATISFACTION = 100;
  
    inputDataset.forEach((item: any, index: number) => {
      const score = item.satisfaction_score;
  
      // 範囲外の値を異常値として検出
      if (score < MIN_SATISFACTION || score > MAX_SATISFACTION) {
        detected_outliers.push({
          ...item,
          error_type: 'OutOfRange',
          error_message: `Satisfaction score ${score} is outside valid range [${MIN_SATISFACTION}, ${MAX_SATISFACTION}]`,
          outlier_index: index,
        });
      } else {
        // 正常値をクリーニング済みデータセットに追加
        cleaned_dataset.push(item);
      }
    });
  
    return {
      detected_outliers,
      cleaned_dataset,
    };
  }
  return { detectAndExcludeOutliers };
})();
